            {locationsLoading ? <Typography variant="body2">Loading locations…</Typography> : null}
            {(locations ?? []).map((loc) => (
              <Paper key={loc.id} variant="outlined" sx={{ p: 1 }}>
                <Stack spacing={1}>
                  <TextField
                    size="small"
                    label="Location code"
