                      if (editingLocationId !== loc.id) setEditingLocationId(loc.id);
                      qc.setQueryData<CustomerLocationRow[]>(['customer-locations', selectedRow.id], (prev = []) =>
                        prev.map((x) => (x.id === loc.id ? { ...x, location_code: e.target.value } : x))
