function distGridShortDateTime(p: { value: unknown }): string {
  const v = p.value as string | null | undefined;
  if (!v) return '—';
  try {
    return new Date(v).toLocaleString(undefined, { dateStyle: 'short', timeStyle: 'short' });
  } catch {
    return String(v);
  }
}

