function AdminDistributorsPageContent() {
  const qc = useQueryClient();
  const lineIdent = useLineIdentifierPreference();
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const [tab, setTab] = useState(0);
  const [addOpen, setAddOpen] = useState(false);
  const [code, setCode] = useState('');
  const [name, setName] = useState('');
  const [drawerRow, setDrawerRow] = useState<DistributorRow | null>(null);
  const [promoteTarget, setPromoteTarget] = useState<DistributorRow | null>(null);
  const [locationDraft, setLocationDraft] = useState({
    location_code: '',
    location_name: '',
    location_type: 'branch',
    country_code: '',
    address_summary: '',
    is_active: true,
    notes_summary: '',
  });
  const [contactDraft, setContactDraft] = useState({
    contact_name: '',
    contact_role: 'general',
    email: '',
    phone: '',
    is_primary: false,
    is_active: true,
    notes_summary: '',
  });
  const [editingLocationId, setEditingLocationId] = useState<number | null>(null);
  const [editingContactId, setEditingContactId] = useState<number | null>(null);
  const [distGridApi, setDistGridApi] = useState<GridApi<DistributorRow> | null>(null);
  const [bulkSelectionMode, setBulkSelectionMode] = useState<BulkTableSelectionMode>('normal');
  const [bulkDeleteOpen, setBulkDeleteOpen] = useState(false);
  const [bulkDeletePreview, setBulkDeletePreview] = useState<MasterBulkDeletePreview | null>(null);
  const [bulkDeleteBusy, setBulkDeleteBusy] = useState(false);
  const [bulkDeleteAck, setBulkDeleteAck] = useState(false);
  const [bulkSelectedCount, setBulkSelectedCount] = useState(0);
  const [bulkPromoteOpen, setBulkPromoteOpen] = useState(false);
  const [dispositionOpen, setDispositionOpen] = useState(false);

  const page = Number(searchParams.get('page') || '1') || 1;
  const pageSize = Number(searchParams.get('page_size') || `${DEFAULT_PAGE_SIZE}`) || DEFAULT_PAGE_SIZE;
  const q = searchParams.get('q') ?? '';
  const sortBy = searchParams.get('sort_by') ?? DEFAULT_SORT_BY;
  const sortDir = (searchParams.get('sort_dir') as 'asc' | 'desc' | null) ?? DEFAULT_SORT_DIR;
  const linkageFilter = searchParams.get('linkage_status') ?? '';
  const minAliasCountFilter = searchParams.get('min_alias_count') ?? '';
  const aliasLinkFilter = searchParams.get('alias_link') ?? '';
  const dispositionFilter = searchParams.get('disposition') ?? '';

  const setParamState = useCallback(
    (changes: Record<string, string | null>, resetPage = false) => {
      const sp = new URLSearchParams(searchParams.toString());
      for (const [k, v] of Object.entries(changes)) {
        if (v == null || v === '') sp.delete(k);
        else sp.set(k, v);
      }
      if (resetPage) sp.set('page', '1');
      router.replace(`${pathname}?${sp.toString()}`);
    },
    [pathname, router, searchParams]
  );

  const {
    data: distributors,
    isLoading: distLoading,
    isError: distIsError,
    error: distErr,
    refetch: refetchDist,
  } = useQuery({
    queryKey: [
      'admin-distributors',
      page,
      pageSize,
      q,
      sortBy,
      sortDir,
      linkageFilter,
      minAliasCountFilter,
      aliasLinkFilter,
      dispositionFilter,
    ],
    queryFn: ({ signal }) => {
      const sp = new URLSearchParams();
      sp.set('page', String(page));
      sp.set('page_size', String(pageSize));
      sp.set('q', q);
      sp.set('sort_by', sortBy);
      sp.set('sort_dir', sortDir);
      if (linkageFilter) sp.set('linkage_status', linkageFilter);
      const mac = minAliasCountFilter.trim();
      if (mac !== '' && Number.isFinite(Number(mac))) sp.set('min_alias_count', String(Number(mac)));
      const al = aliasLinkFilter.trim().toLowerCase();
      if (al === 'linked' || al === 'unlinked') sp.set('alias_link', al);
      if (dispositionFilter) sp.set('disposition', dispositionFilter);
      return apiGet<DistributorListResponse>(`/api/v1/distributors?${sp.toString()}`, { signal });
    },
  });
  const selectedDistributorId = drawerRow?.id ?? null;
  const { data: distributorLocations } = useQuery({
    queryKey: ['distributor-locations', selectedDistributorId],
    queryFn: ({ signal }) =>
      apiGet<DistributorLocationRow[]>(`/api/v1/distributors/${selectedDistributorId}/locations`, { signal }),
    enabled: selectedDistributorId != null,
  });
  const { data: distributorContacts } = useQuery({
    queryKey: ['distributor-contacts', selectedDistributorId],
    queryFn: ({ signal }) =>
      apiGet<DistributorContactRow[]>(`/api/v1/distributors/${selectedDistributorId}/contacts`, { signal }),
    enabled: selectedDistributorId != null,
  });
  const { data: templates } = useQuery({
    queryKey: ['import-templates-distributors'],
    queryFn: ({ signal }) => apiGet<ImportTemplate[]>('/api/v1/imports/templates', { signal }),
  });
  const {
    data: sellout,
    isLoading: sellLoading,
    isError: sellIsError,
    error: sellErr,
    refetch: refetchSell,
  } = useQuery({
    queryKey: ['admin-sellout'],
    queryFn: ({ signal }) => apiGet<SelloutRow[]>('/api/v1/sellout', { signal }),
    enabled: tab === 1,
  });
  const {
    data: inbound,
    isLoading: inboundLoading,
    isError: inboundIsError,
    error: inboundErr,
    refetch: refetchInbound,
  } = useQuery({
    queryKey: ['admin-inbound'],
    queryFn: ({ signal }) => apiGet<InboundRow[]>('/api/v1/inbound-shipments', { signal }),
    enabled: tab === 2,
  });

  const distCodes = useMemo(
    () => ['', ...((distributors?.items ?? []).map((d) => d.distributor_code) ?? [])],
    [distributors?.items]
  );

  const createDist = useMutation({
    mutationFn: () =>
      apiPost<DistributorRow>('/api/v1/distributors', {
        distributor_code: code.trim(),
        distributor_name: name.trim(),
      }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      setAddOpen(false);
      setCode('');
      setName('');
    },
  });

  const delDist = useMutation({
    mutationFn: (id: number) => apiDelete(`/api/v1/distributors/${id}`),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-distributors'] }),
  });
  const delSell = useMutation({
    mutationFn: (id: number) => apiDelete(`/api/v1/sellout/${id}`),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-sellout'] }),
  });
  const clearSell = useMutation({
    mutationFn: () => apiPost<{ deleted: number }>('/api/v1/sellout/clear-all', { confirm: true }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-sellout'] }),
  });
  const delInbound = useMutation({
    mutationFn: (id: number) => apiDelete(`/api/v1/inbound-shipments/${id}`),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-inbound'] }),
  });
  const clearInbound = useMutation({
    mutationFn: () => apiPost<{ deleted: number }>('/api/v1/inbound-shipments/clear-all', { confirm: true }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['admin-inbound'] }),
  });
  const createLocation = useMutation({
    mutationFn: async () =>
      apiPost<DistributorLocationRow>(`/api/v1/distributors/${selectedDistributorId}/locations`, {
        location_code: locationDraft.location_code.trim(),
        location_name: locationDraft.location_name.trim(),
        location_type: locationDraft.location_type,
        country_code: locationDraft.country_code.trim() || null,
        address_summary: locationDraft.address_summary.trim() || null,
        is_active: locationDraft.is_active,
        notes_summary: locationDraft.notes_summary.trim() || null,
      }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['distributor-locations', selectedDistributorId] });
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      setLocationDraft({
        location_code: '',
        location_name: '',
        location_type: 'branch',
        country_code: '',
        address_summary: '',
        is_active: true,
        notes_summary: '',
      });
    },
  });
  const patchLocation = useMutation({
    mutationFn: async (locationId: number) =>
      apiPatch<DistributorLocationRow>(`/api/v1/distributors/${selectedDistributorId}/locations/${locationId}`, {
        location_code: locationDraft.location_code.trim(),
        location_name: locationDraft.location_name.trim(),
        location_type: locationDraft.location_type,
        country_code: locationDraft.country_code.trim() || null,
        address_summary: locationDraft.address_summary.trim() || null,
        is_active: locationDraft.is_active,
        notes_summary: locationDraft.notes_summary.trim() || null,
      }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['distributor-locations', selectedDistributorId] });
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      setEditingLocationId(null);
      setLocationDraft({
        location_code: '',
        location_name: '',
        location_type: 'branch',
        country_code: '',
        address_summary: '',
        is_active: true,
        notes_summary: '',
      });
    },
  });
  const deleteLocation = useMutation({
    mutationFn: async (locationId: number) =>
      apiDelete(`/api/v1/distributors/${selectedDistributorId}/locations/${locationId}`),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['distributor-locations', selectedDistributorId] });
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
    },
  });
  const createContact = useMutation({
    mutationFn: async () =>
      apiPost<DistributorContactRow>(`/api/v1/distributors/${selectedDistributorId}/contacts`, {
        contact_name: contactDraft.contact_name.trim(),
        contact_role: contactDraft.contact_role,
        email: contactDraft.email.trim() || null,
        phone: contactDraft.phone.trim() || null,
        is_primary: contactDraft.is_primary,
        is_active: contactDraft.is_active,
        notes_summary: contactDraft.notes_summary.trim() || null,
      }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['distributor-contacts', selectedDistributorId] });
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      setContactDraft({
        contact_name: '',
        contact_role: 'general',
        email: '',
        phone: '',
        is_primary: false,
        is_active: true,
        notes_summary: '',
      });
    },
  });
  const patchContact = useMutation({
    mutationFn: async (contactId: number) =>
      apiPatch<DistributorContactRow>(`/api/v1/distributors/${selectedDistributorId}/contacts/${contactId}`, {
        contact_name: contactDraft.contact_name.trim(),
        contact_role: contactDraft.contact_role,
        email: contactDraft.email.trim() || null,
        phone: contactDraft.phone.trim() || null,
        is_primary: contactDraft.is_primary,
        is_active: contactDraft.is_active,
        notes_summary: contactDraft.notes_summary.trim() || null,
      }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['distributor-contacts', selectedDistributorId] });
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      setEditingContactId(null);
      setContactDraft({
        contact_name: '',
        contact_role: 'general',
        email: '',
        phone: '',
        is_primary: false,
        is_active: true,
        notes_summary: '',
      });
    },
  });
  const deleteContact = useMutation({
    mutationFn: async (contactId: number) =>
      apiDelete(`/api/v1/distributors/${selectedDistributorId}/contacts/${contactId}`),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['distributor-contacts', selectedDistributorId] });
      qc.invalidateQueries({ queryKey: ['admin-distributors'] });
    },
  });

  const onDistCell = useCallback(
    async (e: CellValueChangedEvent<DistributorRow>) => {
      const id = e.data?.id;
      if (id == null || e.colDef.field !== 'distributor_name' || e.oldValue === e.newValue) return;
      try {
        await apiPatch(`/api/v1/distributors/${id}`, { distributor_name: String(e.newValue ?? '') });
        await qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      } catch (err) {
        console.error(err);
        await qc.invalidateQueries({ queryKey: ['admin-distributors'] });
      }
    },
    [qc]
  );

  const onSellCell = useCallback(
    async (e: CellValueChangedEvent<SelloutRow>) => {
      const id = e.data?.id;
      if (id == null || e.colDef.field !== 'distributor_code' || e.oldValue === e.newValue) return;
      const codeVal = String(e.newValue ?? '');
      const d = (distributors?.items ?? []).find((x) => x.distributor_code === codeVal);
      try {
        await apiPatch(`/api/v1/sellout/${id}`, { distributor_id: d ? d.id : null });
        await qc.invalidateQueries({ queryKey: ['admin-sellout'] });
      } catch (err) {
        console.error(err);
        await qc.invalidateQueries({ queryKey: ['admin-sellout'] });
      }
    },
    [distributors, qc]
  );

  const onInboundCell = useCallback(
    async (e: CellValueChangedEvent<InboundRow>) => {
      const id = e.data?.id;
      if (id == null || e.colDef.field !== 'distributor_code' || e.oldValue === e.newValue) return;
      const codeVal = String(e.newValue ?? '');
      const d = (distributors?.items ?? []).find((x) => x.distributor_code === codeVal);
      try {
        await apiPatch(`/api/v1/inbound-shipments/${id}`, { distributor_id: d ? d.id : null });
        await qc.invalidateQueries({ queryKey: ['admin-inbound'] });
      } catch (err) {
        console.error(err);
        await qc.invalidateQueries({ queryKey: ['admin-inbound'] });
      }
    },
    [distributors, qc]
  );

  const distCols: ColDef<DistributorRow>[] = useMemo(
    () => [
      { field: 'distributor_code', headerName: 'Code', pinned: 'left', minWidth: 140, editable: false },
      {
        field: 'id',
        headerName: 'ID',
        minWidth: 80,
        maxWidth: 100,
        type: 'numericColumn',
        editable: false,
      },
      { field: 'distributor_name', headerName: 'Canonical name', flex: 1, minWidth: 220, editable: true },
      {
        field: 'no_code_disposition',
        headerName: 'Disposition',
        minWidth: 120,
        editable: false,
        cellRenderer: (p: { value?: string | null }) => {
          const v = (p.value || '').toLowerCase();
          if (v === 'parked') return <Chip size="small" label="Parked" />;
          if (v === 'excluded') return <Chip size="small" color="warning" label="Excluded" />;
          return '';
        },
      },
      {
        field: 'created_at',
        headerName: 'Created',
        minWidth: 160,
        editable: false,
        valueFormatter: distGridShortDateTime,
      },
      {
        field: 'updated_at',
        headerName: 'Updated',
        minWidth: 160,
        editable: false,
        valueFormatter: distGridShortDateTime,
      },
      {
        field: 'location_count',
        headerName: 'Locations #',
        minWidth: 110,
        type: 'numericColumn',
        editable: false,
      },
      {
        field: 'contact_count',
        headerName: 'Contacts #',
        minWidth: 110,
        type: 'numericColumn',
        editable: false,
      },
      {
        field: 'alias_count',
        headerName: 'Alias #',
        minWidth: 90,
        type: 'numericColumn',
        editable: false,
      },
      {
        field: 'last_import_at',
        headerName: 'Last import (alias)',
        minWidth: 160,
        editable: false,
        valueFormatter: distGridShortDateTime,
      },
      {
        field: 'alias_link_status',
        headerName: 'Alias link',
        minWidth: 120,
        editable: false,
        cellRenderer: ({ value }: { value?: string }) =>
          value === 'linked' ? (
            <Chip size="small" color="success" label="Linked" variant="outlined" />
          ) : (
            <Chip size="small" color="default" label="Unlinked" variant="outlined" />
          ),
      },
      {
        field: 'linkage_status',
        headerName: 'Linkage status',
        minWidth: 150,
        editable: false,
        cellRenderer: ({ value }: { value: DistributorRow['linkage_status'] }) => {
          const color =
            value === 'healthy' ? 'success' : value === 'partial' ? 'warning' : value === 'unmapped' ? 'error' : 'default';
          return <Chip size="small" color={color} label={value.replace(/_/g, ' ')} />;
        },
      },
      { field: 'linked_sellout_rows', headerName: 'Sell-out linked', minWidth: 130, editable: false },
      { field: 'linked_inbound_rows', headerName: 'Inbound linked', minWidth: 130, editable: false },
      { field: 'latest_sellout_period_start', headerName: 'Latest sell-out', minWidth: 140, editable: false },
      { field: 'latest_inbound_eta_date', headerName: 'Latest inbound', minWidth: 130, editable: false },
      {
        headerName: 'Details',
        colId: '__detail',
        minWidth: 160,
        editable: false,
        cellRenderer: ({ data }: { data: DistributorRow }) =>
          data ? (
            <Stack direction="row" spacing={0.5}>
              <Button size="small" onClick={() => setDrawerRow(data)}>
                Open
              </Button>
              {distributorPromoteActionVisible(data) ? (
                <Button size="small" color="primary" onClick={() => setPromoteTarget(data)}>
                  Promote
                </Button>
              ) : null}
            </Stack>
          ) : null,
      },
      gridDeleteColumn<DistributorRow>((id) => void delDist.mutate(id), { busy: delDist.isPending }),
    ],
    [delDist, delDist.isPending]
  );

  const distColumnLabelByField = useMemo(() => {
    const out: Record<string, string> = {};
    for (const col of distCols) {
      if (!col.field) continue;
      out[col.field] = (col.headerName as string) ?? col.field;
    }
    return out;
  }, [distCols]);

  const openDistributorBulkDeletePreview = useCallback(async () => {
    if (!distGridApi) return;
    const ids = distGridApi.getSelectedRows().map((r: DistributorRow) => r.id);
    if (!ids.length) return;
    setBulkDeleteBusy(true);
    setBulkDeleteAck(false);
    try {
      const data = await apiPost<MasterBulkDeletePreview>('/api/v1/distributors/bulk-delete-preview', {
        entity_ids: ids,
      });
      setBulkDeletePreview(data);
      setBulkDeleteOpen(true);
    } catch (e) {
      alert(safeDisplayError(e));
    } finally {
      setBulkDeleteBusy(false);
    }
  }, [distGridApi]);

  const closeDistributorBulkDeleteDialog = useCallback(() => {
    if (bulkDeleteBusy) return;
    setBulkDeleteOpen(false);
    setBulkDeletePreview(null);
  }, [bulkDeleteBusy]);

  const bulkMintCandidates = useMemo(() => {
    if (!distGridApi || bulkSelectionMode !== 'selecting') return [] as { tmp_code: string; name?: string }[];
    return (distGridApi.getSelectedRows() as DistributorRow[])
      .filter((r) => String(r.distributor_code || '').toUpperCase().startsWith('TMP-DIST-'))
      .map((r) => ({ tmp_code: String(r.distributor_code), name: r.distributor_name }));
  }, [distGridApi, bulkSelectionMode, bulkSelectedCount]);

  const dispositionDistributorIds = useMemo(() => {
    if (!distGridApi || bulkSelectionMode !== 'selecting') return [] as number[];
    return (distGridApi.getSelectedRows() as DistributorRow[]).map((r) => r.id);
  }, [distGridApi, bulkSelectionMode, bulkSelectedCount]);

  const confirmDistributorBulkDelete = useCallback(async () => {
    if (!bulkDeletePreview) return;
    setBulkDeleteBusy(true);
    try {
      await apiPost('/api/v1/distributors/bulk-delete-confirm', {
        entity_ids: bulkDeletePreview.entity_ids,
        deletable_ids: bulkDeletePreview.deletable_ids,
      });
      setBulkDeleteOpen(false);
      setBulkDeletePreview(null);
      setBulkSelectionMode('normal');
      delDist.reset();
      await qc.invalidateQueries({ queryKey: ['admin-distributors'] });
    } finally {
      setBulkDeleteBusy(false);
    }
  }, [bulkDeletePreview, delDist, qc]);

  const sellCols: ColDef<SelloutRow>[] = useMemo(
    () => {
      const busyDel = delSell.isPending || clearSell.isPending;
      return [
        ...lineIdent.columns<SelloutRow>(
          { sku: 'product_sku', salesModel: 'product_sales_model_name' },
          { minWidth: 130, editable: false },
        ),
        { field: 'customer_code', headerName: 'Customer', minWidth: 120, editable: false },
        { field: 'period_start', headerName: 'Period', minWidth: 120, editable: false },
        { field: 'units', headerName: 'Units', type: 'numericColumn', editable: false },
        {
          field: 'distributor_code',
          headerName: 'Distributor',
          minWidth: 180,
          editable: true,
          cellEditor: 'agSelectCellEditor',
          cellEditorParams: { values: distCodes },
        },
        gridDeleteColumn<SelloutRow>((id) => void delSell.mutate(id), { busy: busyDel }),
      ];
    },
    [distCodes, delSell, delSell.isPending, clearSell.isPending, lineIdent]
  );

  const inboundCols: ColDef<InboundRow>[] = useMemo(
    () => {
      const busyDel = delInbound.isPending || clearInbound.isPending;
      return [
        ...lineIdent.columns<InboundRow>(
          { sku: 'product_sku', salesModel: 'product_sales_model_name' },
          { minWidth: 130, editable: false },
        ),
        { field: 'eta_date', headerName: 'ETA', minWidth: 120, editable: false },
        { field: 'quantity', headerName: 'Qty', type: 'numericColumn', editable: false },
        { field: 'status', headerName: 'Status', minWidth: 100, editable: false },
        {
          field: 'distributor_code',
          headerName: 'Distributor',
          minWidth: 180,
          editable: true,
          cellEditor: 'agSelectCellEditor',
          cellEditorParams: { values: distCodes },
        },
        gridDeleteColumn<InboundRow>((id) => void delInbound.mutate(id), { busy: busyDel }),
      ];
    },
    [distCodes, delInbound, delInbound.isPending, clearInbound.isPending, lineIdent]
  );

  const sellGrid: GridOptions<SelloutRow> = useMemo(
    () => ({ singleClickEdit: true, onCellValueChanged: onSellCell }),
    [onSellCell]
  );
  const inboundGrid: GridOptions<InboundRow> = useMemo(
    () => ({ singleClickEdit: true, onCellValueChanged: onInboundCell }),
    [onInboundCell]
  );

  const drows = distributors?.items ?? [];
  const distributorMasterTemplate = (templates ?? []).find((t) => t.slug === 'distributor_master');
  const distributorInventoryTemplate = (templates ?? []).find((t) => t.slug === 'distributor_inventory');
  const hasDistributorMasterImport = Boolean(distributorMasterTemplate?.pipeline_ready);
  const hasDistributorInventoryImport = Boolean(distributorInventoryTemplate?.pipeline_ready);

  return (
    <>
      <Alert severity="info" sx={{ mb: 2 }}>
        Maintain distributor master records first, then monitor linkage health across sell-out and inbound feeds.
        Transitional fact-mapping tabs remain available below while import and routing maturity catches up.{' '}
        <Button component={Link} href="/admin/distributors/duplicates" size="small" sx={{ ml: 1 }}>
          Name-similarity duplicates
        </Button>
      </Alert>
      {delDist.isError ? (
        <Alert severity="warning" sx={{ mb: 2 }} onClose={() => delDist.reset()}>
          {HttpConflictError.is(delDist.error) ? (
            <Stack spacing={1}>
              <Typography variant="body2">{delDist.error.message}</Typography>
              {delDist.error.references.length > 0 ? (
                <Box component="ul" sx={{ m: 0, pl: 2 }}>
                  {delDist.error.references.map((r) => (
                    <Typography key={`${r.label}-${r.count}`} component="li" variant="body2">
                      {r.label} ({r.count})
                    </Typography>
                  ))}
                </Box>
              ) : null}
            </Stack>
          ) : (
            <Typography variant="body2">{(delDist.error as Error).message}</Typography>
          )}
        </Alert>
      ) : null}
      <Paper sx={{ px: 2, pt: 1 }}>
        <Tabs value={tab} onChange={(_, v) => setTab(v)}>
          <Tab label="Distributor master" />
          <Tab label="Transitional: sell-out mapping" />
          <Tab label="Transitional: inbound mapping" />
        </Tabs>
      </Paper>

      <TabPanel value={tab} index={0}>
        <MasterDataGridShell
          entityKey="distributors"
          rows={drows}
          columnDefs={distCols}
          total={distributors?.total ?? 0}
          isLoading={distLoading}
          isError={distIsError}
          error={toQueryError(distErr)}
          onRetry={() => void refetchDist()}
          intro={
            <>
              Distributor master and linkage health. Only operationally ready import paths are shown here; deferred
              templates stay hidden.
            </>
          }
          empty={{
            title: 'No distributors',
            description: hasDistributorMasterImport
              ? 'Use Add distributor above, or import distributor master data from your source feed.'
              : 'Use Add distributor above. Distributor master import is not currently ready.',
            primary: hasDistributorMasterImport
              ? { label: 'Import distributor master', href: '/admin/imports?template=distributor_master' }
              : { label: 'Import Center', href: '/admin/imports' },
            secondary: hasDistributorInventoryImport
              ? { label: 'Import distributor inventory', href: '/admin/imports?template=distributor_inventory' }
              : undefined,
          }}
          url={{
            page,
            pageSize,
            q,
            sortBy,
            sortDir,
          }}
          onUrlChange={setParamState}
          defaultPageSize={DEFAULT_PAGE_SIZE}
          defaultSortBy={DEFAULT_SORT_BY}
          defaultSortDir={DEFAULT_SORT_DIR}
          enableEmptyUrlSeed
          gridStateStorageKey={DISTRIBUTOR_MASTER_GRID_STATE_KEY}
          defaultInitiallyHiddenFields={DEFAULT_INITIALLY_HIDDEN_DISTRIBUTOR_FIELDS}
          columnPickerTitle="Manage distributor columns"
          columnPickerGroups={STATIC_DISTRIBUTOR_MASTER_COLUMN_GROUPS}
          columnLabelByField={distColumnLabelByField}
          gridHeight={440}
          onCellValueChanged={onDistCell}
          onGridApiChange={setDistGridApi}
          bulkSelectionMode={bulkSelectionMode}
          onBulkSelectionModeChange={setBulkSelectionMode}
          onBulkSelectedCountChange={setBulkSelectedCount}
          onPreviewBulkDelete={() => void openDistributorBulkDeletePreview()}
          previewBulkDeleteDisabled={bulkDeleteBusy}
          bulkBusy={bulkDeleteBusy}
          onRefresh={() => qc.invalidateQueries({ queryKey: ['admin-distributors'] })}
          refreshBusy={delDist.isPending || createDist.isPending || bulkDeleteBusy}
          toolbarStart={
            <>
              <Button variant="contained" onClick={() => setAddOpen(true)}>
                Add distributor
              </Button>
              {hasDistributorMasterImport ? (
                <Button variant="outlined" onClick={() => router.push('/admin/imports?template=distributor_master')}>
                  Import distributor master
                </Button>
              ) : null}
              {hasDistributorInventoryImport ? (
                <Button variant="outlined" onClick={() => router.push('/admin/imports?template=distributor_inventory')}>
                  Import distributor inventory
                </Button>
              ) : null}
              <Button variant="outlined" onClick={() => setBulkPromoteOpen(true)} data-testid="bulk-promote-open">
                Bulk promote…
              </Button>
              <Button
                variant="outlined"
                disabled={bulkSelectionMode !== 'selecting' || bulkSelectedCount === 0}
                onClick={() => setDispositionOpen(true)}
                data-testid="disposition-open"
              >
                Park / Exclude…
              </Button>
            </>
          }
          filterSlot={
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} useFlexGap alignItems={{ md: 'center' }}>
              <TextField
                size="small"
                label="Search distributors"
                value={q}
                onChange={(e) => setParamState({ q: e.target.value || null }, true)}
              />
              <FormControl size="small" sx={{ minWidth: 170 }}>
                <InputLabel id="dist-linkage-filter-label">Linkage status</InputLabel>
                <Select
                  labelId="dist-linkage-filter-label"
                  label="Linkage status"
                  value={linkageFilter}
                  onChange={(e) => setParamState({ linkage_status: String(e.target.value) || null }, true)}
                >
                  <MenuItem value="">All</MenuItem>
                  <MenuItem value="healthy">healthy</MenuItem>
                  <MenuItem value="partial">partial</MenuItem>
                  <MenuItem value="unmapped">unmapped</MenuItem>
                  <MenuItem value="no_fact_links">No linked sell-out or shipments</MenuItem>
                </Select>
              </FormControl>
              <TextField
                size="small"
                label="Min alias #"
                type="number"
                inputProps={{ min: 0 }}
                value={minAliasCountFilter}
                onChange={(e) => {
                  const v = e.target.value;
                  setParamState({ min_alias_count: v.trim() === '' ? null : v }, true);
                }}
                sx={{ minWidth: 120 }}
              />
              <FormControl size="small" sx={{ minWidth: 150 }}>
                <InputLabel id="dist-alias-link-label">Alias link</InputLabel>
                <Select
                  labelId="dist-alias-link-label"
                  label="Alias link"
                  value={aliasLinkFilter}
                  onChange={(e) => setParamState({ alias_link: String(e.target.value || '') }, true)}
                >
                  <MenuItem value="">All</MenuItem>
                  <MenuItem value="linked">Linked</MenuItem>
                  <MenuItem value="unlinked">Unlinked</MenuItem>
                </Select>
              </FormControl>
              <FormControl size="small" sx={{ minWidth: 150 }}>
                <InputLabel id="dist-disposition-filter-label">Disposition</InputLabel>
                <Select
                  labelId="dist-disposition-filter-label"
                  label="Disposition"
                  value={dispositionFilter}
                  onChange={(e) => setParamState({ disposition: String(e.target.value || '') }, true)}
                  data-testid="disposition-filter"
                >
                  <MenuItem value="">Any</MenuItem>
                  <MenuItem value="parked">Parked</MenuItem>
                  <MenuItem value="excluded">Excluded</MenuItem>
                  <MenuItem value="unset">None</MenuItem>
                  <MenuItem value="set">Any set</MenuItem>
                </Select>
              </FormControl>
              <FormControl size="small" sx={{ minWidth: 170 }}>
                <InputLabel id="dist-sort-by-label">Sort by</InputLabel>
                <Select
                  labelId="dist-sort-by-label"
                  label="Sort by"
                  value={sortBy}
                  onChange={(e) => setParamState({ sort_by: String(e.target.value || DEFAULT_SORT_BY) }, false)}
                >
                  <MenuItem value="distributor_code">Code</MenuItem>
                  <MenuItem value="distributor_name">Name</MenuItem>
                  <MenuItem value="id">ID</MenuItem>
                  <MenuItem value="created_at">Created</MenuItem>
                  <MenuItem value="updated_at">Updated</MenuItem>
                  <MenuItem value="location_count">Locations #</MenuItem>
                  <MenuItem value="contact_count">Contacts #</MenuItem>
                  <MenuItem value="latest_sellout_period_start">Latest sell-out</MenuItem>
                  <MenuItem value="latest_inbound_eta_date">Latest inbound</MenuItem>
                  <MenuItem value="linked_sellout_rows">Sell-out linked</MenuItem>
                  <MenuItem value="linked_inbound_rows">Inbound linked</MenuItem>
                  <MenuItem value="alias_count">Alias count</MenuItem>
                  <MenuItem value="last_import_at">Last import (alias)</MenuItem>
                </Select>
              </FormControl>
              <FormControl size="small" sx={{ minWidth: 130 }}>
                <InputLabel id="dist-sort-dir-label">Direction</InputLabel>
                <Select
                  labelId="dist-sort-dir-label"
                  label="Direction"
                  value={sortDir}
                  onChange={(e) => setParamState({ sort_dir: String(e.target.value || DEFAULT_SORT_DIR) }, false)}
                >
                  <MenuItem value="asc">Asc</MenuItem>
                  <MenuItem value="desc">Desc</MenuItem>
                </Select>
              </FormControl>
              <Button
                variant="text"
                onClick={() =>
                  setParamState(
                    {
                      q: '',
                      linkage_status: '',
                      min_alias_count: '',
                      alias_link: '',
                      disposition: '',
                      sort_by: DEFAULT_SORT_BY,
                      sort_dir: DEFAULT_SORT_DIR,
                    },
                    true
                  )
                }
              >
                Clear filters
              </Button>
            </Stack>
          }
          drawer={{
            open: Boolean(drawerRow),
            onClose: () => setDrawerRow(null),
            width: 460,
            title: 'Distributor details',
            children: !drawerRow ? null : (
<Stack spacing={1.25}>
              <Paper variant="outlined" sx={{ p: 1.25 }}>
                <Typography variant="subtitle2">Summary</Typography>
                <Typography variant="body2">
                  <strong>Code:</strong> {drawerRow.distributor_code}
                </Typography>
                <Typography variant="body2">
                  <strong>Canonical name:</strong> {drawerRow.distributor_name}
                </Typography>
                <Typography variant="body2">
                  <strong>Locations:</strong> {drawerRow.location_count ?? distributorLocations?.length ?? 0}
                </Typography>
                <Typography variant="body2">
                  <strong>Contacts:</strong> {drawerRow.contact_count ?? distributorContacts?.length ?? 0}
                </Typography>
                {distributorPromoteActionVisible(drawerRow) ? (
                  <Button size="small" variant="outlined" onClick={() => setPromoteTarget(drawerRow)}>
                    Promote provisional code…
                  </Button>
                ) : null}
              </Paper>
              <Paper variant="outlined" sx={{ p: 1.25 }}>
                <Typography variant="subtitle2">Linkage health</Typography>
                <Chip
                  sx={{ my: 0.75 }}
                  size="small"
                  color={
                    drawerRow.linkage_status === 'healthy'
                      ? 'success'
                      : drawerRow.linkage_status === 'partial'
                        ? 'warning'
                        : drawerRow.linkage_status === 'unmapped'
                          ? 'error'
                          : 'default'
                  }
                  label={drawerRow.linkage_status.replace(/_/g, ' ')}
                />
                <Typography variant="body2">
                  <strong>Sell-out linked:</strong> {drawerRow.linked_sellout_rows} / {drawerRow.total_sellout_rows}
                </Typography>
                <Typography variant="body2">
                  <strong>Inbound linked:</strong> {drawerRow.linked_inbound_rows} / {drawerRow.total_inbound_rows}
                </Typography>
                <Typography variant="body2">
                  <strong>Latest sell-out period:</strong> {drawerRow.latest_sellout_period_start ?? '—'}
                </Typography>
                <Typography variant="body2">
                  <strong>Latest inbound ETA:</strong> {drawerRow.latest_inbound_eta_date ?? '—'}
                </Typography>
              </Paper>
              <DistributorCommercialTermsPanel
                distributorId={drawerRow.id}
                distributorCode={drawerRow.distributor_code}
              />
              <Paper variant="outlined" sx={{ p: 1.25 }}>
                <Typography variant="subtitle2" sx={{ mb: 0.75 }}>
                  Locations
                </Typography>
                <Stack spacing={1} sx={{ mb: 1 }}>
                  {(distributorLocations ?? []).map((loc) => (
                    <Paper key={loc.id} variant="outlined" sx={{ p: 0.75 }}>
                      <Typography variant="body2">
                        <strong>{loc.location_code}</strong> — {loc.location_name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary" display="block">
                        {loc.location_type}
                        {loc.country_code ? ` · ${loc.country_code}` : ''} · {loc.is_active ? 'active' : 'inactive'}
                      </Typography>
                      <Stack direction="row" spacing={1} sx={{ mt: 0.5 }}>
                        <Button
                          size="small"
                          onClick={() => {
                            setEditingLocationId(loc.id);
                            setLocationDraft({
                              location_code: loc.location_code,
                              location_name: loc.location_name,
                              location_type: loc.location_type,
                              country_code: loc.country_code ?? '',
                              address_summary: loc.address_summary ?? '',
                              is_active: loc.is_active,
                              notes_summary: loc.notes_summary ?? '',
                            });
                          }}
                        >
                          Edit
                        </Button>
                        <Button size="small" color="error" onClick={() => void deleteLocation.mutate(loc.id)}>
                          Delete
                        </Button>
                      </Stack>
                    </Paper>
                  ))}
                </Stack>
                <Stack spacing={1}>
                  <TextField
                    size="small"
                    label="Location code"
                    value={locationDraft.location_code}
                    onChange={(e) => setLocationDraft((prev) => ({ ...prev, location_code: e.target.value }))}
                  />
                  <TextField
                    size="small"
                    label="Location name"
                    value={locationDraft.location_name}
                    onChange={(e) => setLocationDraft((prev) => ({ ...prev, location_name: e.target.value }))}
                  />
                  <FormControl size="small">
                    <InputLabel id="dist-location-type-label">Location type</InputLabel>
                    <Select
                      labelId="dist-location-type-label"
                      label="Location type"
                      value={locationDraft.location_type}
                      onChange={(e) => setLocationDraft((prev) => ({ ...prev, location_type: String(e.target.value) }))}
                    >
                      {DISTRIBUTOR_LOCATION_TYPE_OPTIONS.map((opt) => (
                        <MenuItem key={opt} value={opt}>
                          {opt}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                  <TextField
                    size="small"
                    label="Country code"
                    value={locationDraft.country_code}
                    onChange={(e) => setLocationDraft((prev) => ({ ...prev, country_code: e.target.value }))}
                  />
                  <TextField
                    size="small"
                    label="Address summary"
                    value={locationDraft.address_summary}
                    onChange={(e) => setLocationDraft((prev) => ({ ...prev, address_summary: e.target.value }))}
                  />
                  <TextField
                    size="small"
                    label="Notes"
                    value={locationDraft.notes_summary}
                    onChange={(e) => setLocationDraft((prev) => ({ ...prev, notes_summary: e.target.value }))}
                  />
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={locationDraft.is_active}
                        onChange={(_, checked) => setLocationDraft((prev) => ({ ...prev, is_active: checked }))}
                      />
                    }
                    label="Active location"
                  />
                  <Stack direction="row" spacing={1}>
                    {editingLocationId ? (
                      <>
                        <Button
                          size="small"
                          variant="contained"
                          onClick={() => void patchLocation.mutate(editingLocationId)}
                          disabled={!locationDraft.location_code.trim() || !locationDraft.location_name.trim()}
                        >
                          Save location
                        </Button>
                        <Button
                          size="small"
                          onClick={() => {
                            setEditingLocationId(null);
                            setLocationDraft({
                              location_code: '',
                              location_name: '',
                              location_type: 'branch',
                              country_code: '',
                              address_summary: '',
                              is_active: true,
                              notes_summary: '',
                            });
                          }}
                        >
                          Cancel
                        </Button>
                      </>
                    ) : (
                      <Button
                        size="small"
                        variant="contained"
                        onClick={() => void createLocation.mutate()}
                        disabled={!locationDraft.location_code.trim() || !locationDraft.location_name.trim()}
                      >
                        Add location
                      </Button>
                    )}
                  </Stack>
                </Stack>
              </Paper>
              <Paper variant="outlined" sx={{ p: 1.25 }}>
                <Typography variant="subtitle2" sx={{ mb: 0.75 }}>
                  Contacts
                </Typography>
                <Stack spacing={1} sx={{ mb: 1 }}>
                  {(distributorContacts ?? []).map((contact) => (
                    <Paper key={contact.id} variant="outlined" sx={{ p: 0.75 }}>
                      <Typography variant="body2">
                        <strong>{contact.contact_name}</strong> — {contact.contact_role}
                      </Typography>
                      <Typography variant="caption" color="text.secondary" display="block">
                        {[contact.email, contact.phone, contact.is_primary ? 'primary' : null, contact.is_active ? 'active' : 'inactive']
                          .filter(Boolean)
                          .join(' · ')}
                      </Typography>
                      <Stack direction="row" spacing={1} sx={{ mt: 0.5 }}>
                        <Button
                          size="small"
                          onClick={() => {
                            setEditingContactId(contact.id);
                            setContactDraft({
                              contact_name: contact.contact_name,
                              contact_role: contact.contact_role,
                              email: contact.email ?? '',
                              phone: contact.phone ?? '',
                              is_primary: contact.is_primary,
                              is_active: contact.is_active,
                              notes_summary: contact.notes_summary ?? '',
                            });
                          }}
                        >
                          Edit
                        </Button>
                        <Button size="small" color="error" onClick={() => void deleteContact.mutate(contact.id)}>
                          Delete
                        </Button>
                      </Stack>
                    </Paper>
                  ))}
                </Stack>
                <Stack spacing={1}>
                  <TextField
                    size="small"
                    label="Contact name"
                    value={contactDraft.contact_name}
                    onChange={(e) => setContactDraft((prev) => ({ ...prev, contact_name: e.target.value }))}
                  />
                  <FormControl size="small">
                    <InputLabel id="dist-contact-role-label">Contact role</InputLabel>
                    <Select
                      labelId="dist-contact-role-label"
                      label="Contact role"
                      value={contactDraft.contact_role}
                      onChange={(e) => setContactDraft((prev) => ({ ...prev, contact_role: String(e.target.value) }))}
                    >
                      {DISTRIBUTOR_CONTACT_ROLE_OPTIONS.map((opt) => (
                        <MenuItem key={opt} value={opt}>
                          {opt}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                  <TextField
                    size="small"
                    label="Email"
                    value={contactDraft.email}
                    onChange={(e) => setContactDraft((prev) => ({ ...prev, email: e.target.value }))}
                  />
                  <TextField
                    size="small"
                    label="Phone"
                    value={contactDraft.phone}
                    onChange={(e) => setContactDraft((prev) => ({ ...prev, phone: e.target.value }))}
                  />
                  <TextField
                    size="small"
                    label="Notes"
                    value={contactDraft.notes_summary}
                    onChange={(e) => setContactDraft((prev) => ({ ...prev, notes_summary: e.target.value }))}
                  />
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={contactDraft.is_primary}
                        onChange={(_, checked) => setContactDraft((prev) => ({ ...prev, is_primary: checked }))}
                      />
                    }
                    label="Primary contact"
                  />
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={contactDraft.is_active}
                        onChange={(_, checked) => setContactDraft((prev) => ({ ...prev, is_active: checked }))}
                      />
                    }
                    label="Active contact"
                  />
                  <Stack direction="row" spacing={1}>
                    {editingContactId ? (
                      <>
                        <Button
                          size="small"
                          variant="contained"
                          onClick={() => void patchContact.mutate(editingContactId)}
                          disabled={!contactDraft.contact_name.trim()}
                        >
                          Save contact
                        </Button>
                        <Button
                          size="small"
                          onClick={() => {
                            setEditingContactId(null);
                            setContactDraft({
                              contact_name: '',
                              contact_role: 'general',
                              email: '',
                              phone: '',
                              is_primary: false,
                              is_active: true,
                              notes_summary: '',
                            });
                          }}
                        >
                          Cancel
                        </Button>
                      </>
                    ) : (
                      <Button
                        size="small"
                        variant="contained"
                        onClick={() => void createContact.mutate()}
                        disabled={!contactDraft.contact_name.trim()}
                      >
                        Add contact
                      </Button>
                    )}
                  </Stack>
                </Stack>
              </Paper>
              <Paper variant="outlined" sx={{ p: 1.25 }}>
                <Typography variant="subtitle2" sx={{ mb: 0.75 }}>
                  Imports
                </Typography>
                <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap">
                  {hasDistributorMasterImport ? (
                    <Button
                      size="small"
                      variant="outlined"
                      onClick={() => router.push('/admin/imports?template=distributor_master')}
                    >
                      Import distributor master
                    </Button>
                  ) : null}
                  {hasDistributorInventoryImport ? (
                    <Button
                      size="small"
                      variant="outlined"
                      onClick={() => router.push('/admin/imports?template=distributor_inventory')}
                    >
                      Import distributor inventory
                    </Button>
                  ) : null}
                </Stack>
                {!hasDistributorMasterImport && !hasDistributorInventoryImport ? (
                  <Alert severity="info" sx={{ mt: 1 }}>
                    Distributor import templates are not currently ready in this environment.
                  </Alert>
                ) : null}
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.75 }}>
                  The distributor import updates distributor records. The inventory import checks SKU and on-hand snapshots. Types that are not ready to apply are not shown as ready paths.
                </Typography>
              </Paper>
            </Stack>
            ),
          }}
        />
      </TabPanel>

      <TabPanel value={tab} index={1}>
        <Paper sx={{ p: 2 }}>
          <ModuleDataSection
            intro={
              <>
                Distributor sell-out linkage. Kept while distributor matching is still being finished.
              </>
            }
            isLoading={sellLoading}
            isError={sellIsError}
            error={toQueryError(sellErr)}
            onRetry={() => void refetchSell()}
            isEmpty={(sellout ?? []).length === 0}
            empty={{
              title: 'No sell-out rows',
              description: 'Load sales facts via Import Center or upstream connectors when available.',
              primary: { label: 'Import Center', href: '/admin/imports' },
            }}
            toolbar={
              <ModuleGridToolbar
                onRefresh={() => qc.invalidateQueries({ queryKey: ['admin-sellout'] })}
                onClearAll={() => {
                  if (!window.confirm('Delete every sell-out fact row? This cannot be undone.')) return;
                  void clearSell.mutate();
                }}
                importsHref="/admin/imports"
                busy={delSell.isPending || clearSell.isPending}
              />
            }
          >
            <EnterpriseDataGrid rowData={sellout ?? []} columnDefs={sellCols} gridOptions={sellGrid} height={480} />
          </ModuleDataSection>
        </Paper>
      </TabPanel>

      <TabPanel value={tab} index={2}>
        <Paper sx={{ p: 2 }}>
          <ModuleDataSection
            intro={
              <>
                Inbound shipment linkage, kept so current operations keep running.
              </>
            }
            isLoading={inboundLoading}
            isError={inboundIsError}
            error={toQueryError(inboundErr)}
            onRetry={() => void refetchInbound()}
            isEmpty={(inbound ?? []).length === 0}
            empty={{
              title: 'No inbound rows',
              description: 'Inbound shipment facts appear when purchase-order or ASN data is loaded.',
              primary: { label: 'Import Center', href: '/admin/imports' },
            }}
            toolbar={
              <ModuleGridToolbar
                onRefresh={() => qc.invalidateQueries({ queryKey: ['admin-inbound'] })}
                onClearAll={() => {
                  if (!window.confirm('Delete every inbound shipment row? This cannot be undone.')) return;
                  void clearInbound.mutate();
                }}
                importsHref="/admin/imports"
                busy={delInbound.isPending || clearInbound.isPending}
              />
            }
          >
            <EnterpriseDataGrid rowData={inbound ?? []} columnDefs={inboundCols} gridOptions={inboundGrid} height={480} />
          </ModuleDataSection>
        </Paper>
      </TabPanel>

      <Dialog open={addOpen} onClose={() => !createDist.isPending && setAddOpen(false)} fullWidth maxWidth="sm">
        <DialogTitle>New distributor</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <TextField label="Code" value={code} onChange={(e) => setCode(e.target.value)} required />
            <TextField label="Name" value={name} onChange={(e) => setName(e.target.value)} required />
          </Stack>
          {createDist.isError ? (
            <Alert severity="error" sx={{ mt: 2 }}>
              {(createDist.error as Error).message}
            </Alert>
          ) : null}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAddOpen(false)} disabled={createDist.isPending}>
            Cancel
          </Button>
          <Button
            variant="contained"
            disabled={createDist.isPending || !code.trim() || !name.trim()}
            onClick={() => createDist.mutate()}
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>
      <DistributorPromoteDialog
        open={Boolean(promoteTarget)}
        distributor={
          promoteTarget
            ? {
                id: promoteTarget.id,
                distributor_code: promoteTarget.distributor_code,
                distributor_name: promoteTarget.distributor_name,
              }
            : null
        }
        onClose={() => {
          setPromoteTarget(null);
          void qc.invalidateQueries({ queryKey: ['admin-distributors'] });
        }}
      />
      <DistributorBulkPromoteDialog
        open={bulkPromoteOpen}
        mintCandidates={bulkMintCandidates}
        onClose={() => {
          setBulkPromoteOpen(false);
          void qc.invalidateQueries({ queryKey: ['admin-distributors'] });
        }}
      />
      <DistributorDispositionDialog
        open={dispositionOpen}
        distributorIds={dispositionDistributorIds}
        onClose={() => {
          setDispositionOpen(false);
          void qc.invalidateQueries({ queryKey: ['admin-distributors'] });
        }}
      />
      <MasterBulkDeleteImpactDialog
        open={bulkDeleteOpen}
        busy={bulkDeleteBusy}
        preview={bulkDeletePreview}
        entityLabel="distributors"
        impactAcknowledged={bulkDeleteAck}
        onImpactAcknowledgedChange={setBulkDeleteAck}
        onClose={closeDistributorBulkDeleteDialog}
        onConfirm={() => void confirmDistributorBulkDelete()}
      />
    </>
  );
}

export default function AdminDistributorsPage() {
  return (
    <DataChrome>
      <Suspense fallback={<Typography color="text.secondary">Loading distributors workspace…</Typography>}>
        <AdminDistributorsPageContent />
      </Suspense>
    </DataChrome>
  );
}

'use client';

import HistoryOutlinedIcon from '@mui/icons-material/HistoryOutlined';
import {
  Alert,
  Box,
  Button,
  Chip,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { useQuery } from '@tanstack/react-query';
import { useMemo } from 'react';

import { apiGet } from '@/lib/api';

export type DsiCoverageFlag = {
  distributor_id: number;
  distributor_name: string;
  signal: 'sellout' | 'soh';
  week_start: string;
  message: string;
};

export type DsiCoverageDistributor = {
  distributor_id: number;
  distributor_name: string;
  sellout: {
    weekly_active: boolean;
    covered_weeks: string[];
    missed_weeks: string[];
  };
  soh: {
    weekly_active: boolean;
    covered_weeks: string[];
    missed_weeks: string[];
  };
};

export type DsiCoverageResponse = {
  data_unavailable: boolean;
  source_id?: number | null;
  weeks: number;
  week_starts: string[];
  distributors: DsiCoverageDistributor[];
  flags: DsiCoverageFlag[];
};

function formatWeekLabel(iso: string): string {
  const d = new Date(`${iso}T12:00:00`);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}

function cellStatus(
  dist: DsiCoverageDistributor,
  week: string,
  signal: 'sellout' | 'soh'
): 'covered' | 'missed' | 'inactive' {
  const block = signal === 'sellout' ? dist.sellout : dist.soh;
  if (!block.weekly_active) return 'inactive';
  if (block.covered_weeks.includes(week)) return 'covered';
  if (block.missed_weeks.includes(week)) return 'missed';
  return 'inactive';
}

export type DsiCoveragePanelProps = {
  sourceId: number | null;
  weeks?: number;
  /** Show compact flag banner only (validate step). */
  flagsOnly?: boolean;
  onUploadHistorical?: () => void;
};

export function DsiCoveragePanel({
  sourceId,
  weeks = 12,
  flagsOnly = false,
  onUploadHistorical,
}: DsiCoveragePanelProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: ['dsi-coverage', sourceId, weeks],
    queryFn: ({ signal }) =>
      apiGet<DsiCoverageResponse>(
        `/api/v1/imports/dsi/coverage?weeks=${weeks}${sourceId != null ? `&source_id=${sourceId}` : ''}`,
        { signal }
      ),
    enabled: sourceId != null,
    staleTime: 60_000,
  });

  const flags = data?.flags ?? [];
  const recentFlags = useMemo(() => flags.slice(0, 8), [flags]);

  if (sourceId == null) return null;
  if (isLoading) {
    return (
      <Typography variant="body2" color="text.secondary" data-testid="dsi-coverage-loading">
        Loading weekly coverage…
      </Typography>
    );
  }
  if (isError || data?.data_unavailable) return null;

  if (flagsOnly) {
    if (!flags.length) return null;
    return (
      <Alert
        severity="warning"
        data-testid="dsi-missed-weeks-flag"
        action={
          onUploadHistorical ? (
            <Button
              color="inherit"
              size="small"
              startIcon={<HistoryOutlinedIcon />}
              onClick={onUploadHistorical}
              data-testid="dsi-upload-historical-backfill"
            >
              Historical upload
            </Button>
          ) : undefined
        }
      >
        <Typography variant="body2" fontWeight={600} gutterBottom>
          Missed weekly coverage detected (informational — does not block apply)
        </Typography>
        <Stack component="ul" sx={{ m: 0, pl: 2.5 }} spacing={0.25}>
          {recentFlags.map((f) => (
            <Typography component="li" variant="caption" key={`${f.distributor_id}-${f.signal}-${f.week_start}`}>
              {f.message}
            </Typography>
          ))}
        </Stack>
        {flags.length > recentFlags.length ? (
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 0.5 }}>
            +{flags.length - recentFlags.length} more — see coverage panel below
          </Typography>
        ) : null}
      </Alert>
    );
  }

  const distributors = (data?.distributors ?? []).filter(
    (d) => d.sellout.weekly_active || d.soh.weekly_active
  );
  const weekStarts = data?.week_starts ?? [];

  if (!distributors.length) {
    return (
      <Alert severity="info" data-testid="dsi-coverage-empty">
        No weekly-active distributors in the last {weeks} weeks for this source yet.
      </Alert>
    );
  }

  return (
    <Paper variant="outlined" sx={{ p: 2 }} data-testid="dsi-coverage-panel">
      <Stack spacing={1.5}>
        <Stack direction="row" alignItems="center" justifyContent="space-between" flexWrap="wrap" gap={1}>
          <Typography variant="subtitle2">Weekly DSI coverage (last {weeks} ISO weeks)</Typography>
          <Stack direction="row" gap={0.5}>
            <Chip size="small" label="Sell-out" variant="outlined" />
            <Chip size="small" label="SOH" variant="outlined" color="secondary" />
          </Stack>
        </Stack>
        <Typography variant="caption" color="text.secondary">
          Green = data present · Red = missed week for a weekly-active distributor · FLAG only — upload gaps do not
          block this week&apos;s apply.
        </Typography>
        <Box sx={{ overflowX: 'auto' }}>
          <Table size="small" data-testid="dsi-coverage-grid">
            <TableHead>
              <TableRow>
                <TableCell>Distributor</TableCell>
                <TableCell>Signal</TableCell>
                {weekStarts.map((w) => (
                  <TableCell key={w} align="center" sx={{ minWidth: 48, px: 0.5 }}>
                    <Typography variant="caption">{formatWeekLabel(w)}</Typography>
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {distributors.flatMap((dist) =>
                (['sellout', 'soh'] as const).map((signal) => {
                  const block = signal === 'sellout' ? dist.sellout : dist.soh;
                  if (!block.weekly_active) return null;
                  return (
                    <TableRow key={`${dist.distributor_id}-${signal}`}>
                      <TableCell>{dist.distributor_name}</TableCell>
                      <TableCell>{signal === 'sellout' ? 'Sell-out' : 'SOH'}</TableCell>
                      {weekStarts.map((w) => {
                        const status = cellStatus(dist, w, signal);
                        const bg =
                          status === 'covered'
                            ? 'success.light'
                            : status === 'missed'
                              ? 'error.light'
                              : 'action.hover';
                        return (
                          <TableCell
                            key={w}
                            align="center"
                            sx={{
                              px: 0.25,
                              bgcolor: bg,
                              opacity: status === 'inactive' ? 0.35 : 1,
                            }}
                            data-testid={`dsi-cov-${dist.distributor_id}-${signal}-${w}`}
                          >
                            {status === 'covered' ? '●' : status === 'missed' ? '○' : '·'}
                          </TableCell>
                        );
                      })}
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </Box>
        {flags.length ? (
          <Alert severity="warning" variant="outlined">
            {flags.length} missed week{flags.length === 1 ? '' : 's'} flagged across active distributors.
            {onUploadHistorical ? (
              <>
                {' '}
                <Button
                  size="small"
                  startIcon={<HistoryOutlinedIcon />}
                  onClick={onUploadHistorical}
                  data-testid="dsi-coverage-historical-cta"
                >
                  Upload historical backfill
                </Button>
              </>
            ) : null}
          </Alert>
        ) : null}
      </Stack>
    </Paper>
  );
}

'use client';

import NextLink from 'next/link';
import Link from '@mui/material/Link';
import {
  Alert,
  Box,
  Button,
  Divider,
  Drawer,
  Stack,
  Typography,
} from '@mui/material';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { MouseEvent } from 'react';
import { useQuery } from '@tanstack/react-query';
import { BulkSelectionToolbar, type BulkTableSelectionMode } from '@/components/bulkTable/BulkSelectionToolbar';

import type { PlanApplyFeedback } from '@/app/(app)/admin/imports/dsi/dsiSteward.types';
import {
  StewardCandidatesPagination,
  StewardPendingButton,
  StewardEntityTabsBar,
  StewardResolutionPlanToolbar,
  StewardCandidateFilters,
  ImportStewardCandidateWorkspace,
  StewardWorkspaceViewportShell,
  StewardBulkActionInlineForm,
  StewardBulkSection,
  StewardCandidateDrawer,
  computeImportStewardSelectionHeaderState,
  formatPlanActionLabel,
  useStewardBulkSteward,
  PlanDialogRowDetail,
} from '@/features/import-steward';
import {
  defaultDsiStewardCandidateFilterState,
  filterDsiStewardCandidates,
  paginateDsiStewardCandidateRows,
  type DsiStewardCandidateFilterState,
} from '@/app/(app)/admin/imports/dsi';
import {
  DsiMappingStewardPanel,
  DsiProductCandidateExportToolbar,
  DsiCountryRegionFallback,
  DsiRegionChannelTabPanel,
  isDsiEntityCandidateTab,
  DsiStewardLoadingCallout,
  DSI_STEWARD_CONFIG,
  DSI_ENGINE_CONFIG,
  DSI_ENTITY_TABS,
  useDsiCandidatesPage,
  useDsiEntityTabCounts,
  defaultDsiStewardFiltersForTab,
  dsiStewardFiltersMatchTabDefault,
  dsiTabDependencyNudge,
  formatDsiEntityTabLabel,
  useDsiResolutionPlan,
  type DsiBulkAction,
  type DsiCandidateRow,
  type DsiEntityTabId,
  type DsiRegionEvidenceDto,
} from '@/app/(app)/admin/imports/dsi';
import { DsiCustomerSearchFields } from '@/app/(app)/admin/imports/dsi/DsiCustomerSearchFields';
import { useDsiStewardBulkBusy } from '@/app/(app)/admin/imports/dsi/useDsiStewardBulkBusy';
import { apiGet, safeDisplayError } from '@/lib/api';

import {
  buildDuplicateClusterIndex,
  duplicateClusterMembersForKey,
} from '@/app/(app)/admin/imports/dsi/dsiDuplicateCluster';

import { buildDsiResolutionWorkspaceColumns } from './dsi/dsiResolutionWorkspaceTableProps';
import type { DistributorSiSummary } from './dsiStepUtils';
import {
  dsiDataQualityBlockingRows,
  dsiStewardMapBlockingRows,
} from './dsiStepUtils';

export function DsiImportJobResolutionSection({
  importJobId,
  candidates: candidatesOverride,
  candidatesLoading: candidatesLoadingOverride,
  candidatesError: candidatesErrorOverride,
  onInvalidate,
  dsiPipelineRunning = false,
  onAsyncPipelineStarted,
  validateSummary = null,
  initialTab,
  focusNormalizedKey,
  focusCandidateId,
}: {
  importJobId: number;
  /** Test / story override — skips paginated fetch when provided. */
  candidates?: DsiCandidateRow[];
  candidatesLoading?: boolean;
  candidatesError?: unknown;
  onInvalidate: () => void;
  /** True while validate/revalidate Celery pipeline is in flight (imports page). */
  dsiPipelineRunning?: boolean;
  onAsyncPipelineStarted?: (args: { importJobId: number; taskId?: string | null }) => void;
  /** Latest distributor_si_summary for blocker empty-state copy. */
  validateSummary?: DistributorSiSummary | null;
  initialTab?: DsiEntityTabId;
  focusNormalizedKey?: string;
  focusCandidateId?: number;
}) {
  const tabbedMode = candidatesOverride == null;
  const startTab = initialTab ?? 'distributor';

  const [activeTab, setActiveTab] = useState<DsiEntityTabId>(startTab);
  const [visitedTabs, setVisitedTabs] = useState<Set<DsiEntityTabId>>(() => new Set([startTab]));
  const [filtersByTab, setFiltersByTab] = useState<Record<DsiEntityTabId, DsiStewardCandidateFilterState>>(() => ({
    distributor: defaultDsiStewardFiltersForTab('distributor'),
    customer: defaultDsiStewardFiltersForTab('customer'),
    product: defaultDsiStewardFiltersForTab('product'),
    region_channel: defaultDsiStewardFiltersForTab('region_channel'),
  }));

  const [detailCandidate, setDetailCandidate] = useState<DsiCandidateRow | null>(null);
  const [rowActionPendingId, setRowActionPendingId] = useState<number | null>(null);
  const [candidateFilters, setCandidateFilters] = useState<DsiStewardCandidateFilterState>(
    defaultDsiStewardCandidateFilterState
  );
  const [bulkMode, setBulkMode] = useState<BulkTableSelectionMode>('normal');
  const [selectedIds, setSelectedIds] = useState<number[]>([]);
  const [planApplySummary, setPlanApplySummary] = useState<PlanApplyFeedback | null>(null);
  const selectionAnchorIdRef = useRef<number | null>(null);
  const workspaceToolbarRef = useRef<HTMLDivElement | null>(null);

  const focusWorkspaceToolbar = useCallback(() => {
    const el = workspaceToolbarRef.current?.querySelector<HTMLElement>(
      'button:not([disabled]), [href], [tabindex]:not([tabindex="-1"])'
    );
    el?.focus();
  }, []);

  const activeFilters = tabbedMode ? filtersByTab[activeTab] : candidateFilters;
  const setActiveFilters = useCallback(
    (next: DsiStewardCandidateFilterState) => {
      if (tabbedMode) {
        setFiltersByTab((prev) => ({ ...prev, [activeTab]: next }));
      } else {
        setCandidateFilters(next);
      }
    },
    [activeTab, tabbedMode]
  );

  const { counts: tabCounts, openByTab, productMatchStatusCounts } = useDsiEntityTabCounts(
    importJobId,
    tabbedMode
  );

  const isCandidateTab = isDsiEntityCandidateTab(activeTab);

  const candidatesPage = useDsiCandidatesPage(importJobId, activeFilters, {
    enabled: tabbedMode && visitedTabs.has(activeTab) && isCandidateTab,
    tabKey: activeTab,
  });

  const candidates = candidatesOverride ?? candidatesPage.candidates;
  const candidatesLoading =
    candidatesLoadingOverride ??
    (candidatesPage.query.isLoading ||
      (candidatesPage.query.isFetching && candidatesPage.candidates.length === 0));
  const candidatesError =
    candidatesErrorOverride ?? (candidatesPage.query.isError ? candidatesPage.query.error : null);
  const candidatesTotal = candidatesOverride != null ? candidates.length : candidatesPage.total;

  const focusAppliedRef = useRef(false);
  const dsiClearInitRef = useRef(true);

  useEffect(() => {
    if (dsiClearInitRef.current) {
      dsiClearInitRef.current = false;
      return;
    }
    setSelectedIds([]);
    setDetailCandidate(null);
    selectionAnchorIdRef.current = null;
  }, [
    candidatesOverride,
    activeTab,
    candidatesPage.page,
    candidatesPage.pageSize,
    candidatesPage.skip,
  ]);
  const focusQuery = useQuery({
    queryKey: ['dsi-focus-candidate', importJobId, focusNormalizedKey, focusCandidateId, startTab],
    queryFn: ({ signal }) => {
      const q = new URLSearchParams();
      q.set('limit', '5');
      q.set('status', 'all');
      if (startTab === 'customer') q.set('entity', 'customer');
      else if (startTab === 'product') q.set('entity', 'product');
      else if (startTab === 'distributor') q.set('entity', 'distributor');
      if (focusNormalizedKey) q.set('normalized_key', focusNormalizedKey);
      if (focusCandidateId != null) q.set('candidate_id', String(focusCandidateId));
      return apiGet<{ items: DsiCandidateRow[] }>(
        `/api/v1/mappings/import-jobs/${importJobId}/distributor-si-candidates?${q.toString()}`,
        { signal }
      );
    },
    enabled: tabbedMode && importJobId > 0 && Boolean(focusNormalizedKey || focusCandidateId),
  });

  useEffect(() => {
    if (focusAppliedRef.current) return;
    const items = focusQuery.data?.items ?? [];
    const row =
      (focusCandidateId != null ? items.find((c) => c.id === focusCandidateId) : undefined) ??
      (focusNormalizedKey ? items.find((c) => c.normalized_key === focusNormalizedKey) : undefined) ??
      items[0];
    if (!row) return;
    setDetailCandidate(row);
    focusAppliedRef.current = true;
  }, [focusQuery.data, focusCandidateId, focusNormalizedKey]);

  const plan = useDsiResolutionPlan({
    importJobId,
    candidates,
    onInvalidate,
    onAsyncPipelineStarted,
    setSelectedIds,
    setPlanApplySummary,
  });

  const stewardBulk = useDsiStewardBulkBusy(importJobId);

  const planComputeBlocking =
    (plan.suggestionsQuery.isFetching && !plan.suggestionsQuery.data) ||
    (stewardBulk.computeActive && !plan.applyResolutionPlan.isPending);

  const planApplyBlocked =
    planComputeBlocking ||
    stewardBulk.applyActive ||
    plan.refreshPlanEffective.isPending;

  const bulk = useStewardBulkSteward({
    importJobId,
    selectedIds,
    setSelectedIds,
    setBulkMode,
    onInvalidate,
    onBulkClosed: focusWorkspaceToolbar,
    onPlanRefresh: () => plan.refreshSuggestions(),
    onEvictResolvedCandidates: plan.evictResolvedCandidates,
    onShrinkPlanScope: plan.shrinkPlanScope,
    onApplyPlanFallback: async ({ action, regionId, channelId }) => {
      if (action === 'set_plan_fallback_channel') {
        plan.setPlanChannelId(channelId);
        await plan.suggestionsQuery.refetch();
      }
    },
    applySuggestedRegion: async ({ candidateIds }) => {
      for (const id of candidateIds) {
        const row = plan.planByCandidateId.get(id);
        const ev = row?.region_evidence as DsiRegionEvidenceDto | undefined;
        const rid = ev?.suggested_region_id;
        if (rid != null && Number.isFinite(Number(rid))) {
          plan.patchPlanOverride(id, { region_id: Number(rid) });
        }
      }
      await plan.refreshPlanEffective.mutateAsync({
        overrides: plan.overridesPayload(),
        globalSuspicious: plan.planGlobalSuspicious,
      });
    },
    config: DSI_ENGINE_CONFIG,
  });

  const closeBulkForm = useCallback(() => {
    setBulkMode('normal');
    setSelectedIds([]);
    bulk.setPreviewOpen(false);
    focusWorkspaceToolbar();
  }, [bulk, focusWorkspaceToolbar]);

  const filteredCandidates = useMemo(
    () => filterDsiStewardCandidates(candidates, activeFilters, plan.planByCandidateId),
    [candidates, activeFilters, plan.planByCandidateId]
  );

  const clientQueueFilterActive = tabbedMode && candidatesPage.clientQueueFilterActive;

  const filteredPageCount = Math.max(
    1,
    Math.ceil(filteredCandidates.length / Math.max(1, candidatesPage.pageSize))
  );

  const gridCandidates = useMemo(() => {
    if (!clientQueueFilterActive) return filteredCandidates;
    return paginateDsiStewardCandidateRows(
      filteredCandidates,
      candidatesPage.page,
      candidatesPage.pageSize
    );
  }, [
    filteredCandidates,
    clientQueueFilterActive,
    candidatesPage.page,
    candidatesPage.pageSize,
  ]);

  useEffect(() => {
    if (!clientQueueFilterActive || candidatesPage.query.isFetching) return;
    if (candidatesPage.page > 0 && candidatesPage.page >= filteredPageCount) {
      candidatesPage.setPage(Math.max(0, filteredPageCount - 1));
    }
  }, [
    clientQueueFilterActive,
    candidatesPage.page,
    candidatesPage.setPage,
    candidatesPage.query.isFetching,
    filteredPageCount,
  ]);

  const displayedCandidates = gridCandidates;

  const openBulkWorkflow = useCallback(
    (action: DsiBulkAction) => {
      bulk.setBulkAction(action);
      setBulkMode('selecting');
      if (selectedIds.length === 0 && displayedCandidates.length > 0) {
        setSelectedIds(displayedCandidates.map((c) => c.id));
      }
    },
    [bulk, displayedCandidates, selectedIds.length]
  );

  const selectedReadyPlanIds = useMemo(() => {
    const ready = new Set(plan.readyPlanCandidateIds);
    return selectedIds.filter((id) => ready.has(id));
  }, [selectedIds, plan.readyPlanCandidateIds]);

  const supervisedAutoResolvedRows = useMemo(() => {
    const raw = plan.resolutionPlan?.rows;
    if (!Array.isArray(raw)) return [] as Array<Record<string, unknown>>;
    return raw.filter((row) => {
      const r = row as Record<string, unknown>;
      return r.auto_resolved_supervised === true;
    }) as Array<Record<string, unknown>>;
  }, [plan.resolutionPlan]);

  const selectVisibleReadyInGrid = useCallback(() => {
    setSelectedIds(
      displayedCandidates
        .filter((c) => plan.planByCandidateId.get(c.id)?.ready === true)
        .map((c) => c.id)
    );
  }, [displayedCandidates, plan.planByCandidateId]);

  const candidatesById = useMemo(() => {
    const m: Record<number, DsiCandidateRow> = {};
    for (const c of candidates) m[c.id] = c;
    return m;
  }, [candidates]);

  const openStewardDrawer = useCallback((row: DsiCandidateRow) => {
    setDetailCandidate(row);
  }, []);

  const isDsiRowTerminal = useCallback(
    (row: DsiCandidateRow) => DSI_STEWARD_CONFIG.terminalStatuses.has((row.status || '').trim()),
    []
  );

  const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const workspaceVisibleRowIds = useMemo(() => displayedCandidates.map((c) => c.id), [displayedCandidates]);
  const workspaceHeaderState = useMemo(
    () => computeImportStewardSelectionHeaderState(workspaceVisibleRowIds, selectedIdSet),
    [workspaceVisibleRowIds, selectedIdSet]
  );

  const onWorkspaceToggleRowSelection = useCallback(
    (rowId: number, event?: MouseEvent) => {
      const visibleIds = workspaceVisibleRowIds;
      if (event?.shiftKey && selectionAnchorIdRef.current != null) {
        const anchorId = selectionAnchorIdRef.current;
        const i0 = visibleIds.indexOf(anchorId);
        const i1 = visibleIds.indexOf(rowId);
        if (i0 >= 0 && i1 >= 0) {
          const [lo, hi] = i0 < i1 ? [i0, i1] : [i1, i0];
          const rangeIds = visibleIds.slice(lo, hi + 1);
          setSelectedIds((prev) => Array.from(new Set([...prev, ...rangeIds])));
          selectionAnchorIdRef.current = rowId;
          return;
        }
      }
      setSelectedIds((prev) => (prev.includes(rowId) ? prev.filter((x) => x !== rowId) : [...prev, rowId]));
      selectionAnchorIdRef.current = rowId;
    },
    [workspaceVisibleRowIds]
  );

  const onWorkspaceToggleAllVisibleSelection = useCallback(() => {
    setSelectedIds((prev) => {
      const prevSet = new Set(prev);
      const allVisibleSelected =
        workspaceVisibleRowIds.length > 0 && workspaceVisibleRowIds.every((id) => prevSet.has(id));
      if (allVisibleSelected) {
        return prev.filter((id) => !workspaceVisibleRowIds.includes(id));
      }
      return Array.from(new Set([...prev, ...workspaceVisibleRowIds]));
    });
  }, [workspaceVisibleRowIds]);

  const workspaceSelection = useMemo(
    () => ({
      selectedIds: selectedIdSet,
      onToggle: onWorkspaceToggleRowSelection,
      onToggleAllVisible: onWorkspaceToggleAllVisibleSelection,
      visibleRowIds: workspaceVisibleRowIds,
      headerState: workspaceHeaderState,
    }),
    [
      selectedIdSet,
      onWorkspaceToggleRowSelection,
      onWorkspaceToggleAllVisibleSelection,
      workspaceVisibleRowIds,
      workspaceHeaderState,
    ]
  );

  const onTabChange = useCallback((tab: DsiEntityTabId) => {
    setVisitedTabs((prev) => {
      if (prev.has(tab)) return prev;
      const next = new Set(prev);
      next.add(tab);
      return next;
    });
    setActiveTab(tab);
  }, []);

  const dependencyNudge = tabbedMode
    ? dsiTabDependencyNudge(activeTab, openByTab, openByTab.region_channel)
    : null;

  const revalidatePipelineBusy =
    dsiPipelineRunning || plan.dsiRevalidateFromServer.isPending;

  const stewardOverlayBusy =
    bulk.bulkPreview.isPending ||
    bulk.bulkApply.isPending ||
    plan.applyResolutionPlan.isPending ||
    plan.refreshPlanEffective.isPending ||
    planComputeBlocking ||
    (stewardBulk.applyActive && !plan.applyResolutionPlan.isPending) ||
    revalidatePipelineBusy;

  const stewardBusyMessage = useMemo(() => {
    if (bulk.bulkApply.isPending) return 'Applying bulk steward actions…';
    if (bulk.bulkPreview.isPending) return 'Building bulk steward preview…';
    if (plan.applyResolutionPlan.isPending || stewardBulk.applyActive) {
      return 'Applying resolution plan… Large batches can take 10+ minutes — you can keep working; progress appears in the activity bell.';
    }
    if (planComputeBlocking) {
      return 'Computing resolution plan… Apply is disabled until compute finishes.';
    }
    if (plan.refreshPlanEffective.isPending) return 'Updating resolution plan after your edits…';
    if (revalidatePipelineBusy) return 'Re-running import validation on the server…';
    return undefined;
  }, [
    bulk.bulkApply.isPending,
    bulk.bulkPreview.isPending,
    plan.applyResolutionPlan.isPending,
    stewardBulk.applyActive,
    planComputeBlocking,
    plan.refreshPlanEffective.isPending,
    revalidatePipelineBusy,
  ]);

  const planInitialLoading =
    candidates.length > 0 &&
    plan.suggestionsQuery.fetchStatus === 'fetching' &&
    !plan.suggestionsQuery.data;

  const isRegionChannelTab = activeTab === 'region_channel';

  /** Keep table shell whenever the job workspace is shown so chips + empty state stay aligned. */
  const keepTableWhenFilterEmpty =
    importJobId != null && !candidatesLoading && isCandidateTab;

  const effectiveDetailCandidate = useMemo(() => {
    if (detailCandidate == null) return null;
    return candidates.find((c) => c.id === detailCandidate.id) ?? detailCandidate;
  }, [detailCandidate, candidates]);

  const duplicateClusterIndex = useMemo(() => buildDuplicateClusterIndex(candidates), [candidates]);

  const customerNormalizedKeysOnPage = useMemo(
    () =>
      candidates
        .filter((c) => c.entity_type === 'customer_dealer_token')
        .map((c) => c.normalized_key)
        .filter(Boolean),
    [candidates]
  );

  const duplicateClusterMembersForSelection = useMemo(() => {
    if (!effectiveDetailCandidate) return [];
    return [
      ...duplicateClusterMembersForKey(
        duplicateClusterIndex,
        effectiveDetailCandidate.normalized_key
      ),
    ];
  }, [duplicateClusterIndex, effectiveDetailCandidate]);

  useEffect(() => {
    if (rowActionPendingId == null) return;
    const row = candidates.find((c) => c.id === rowActionPendingId);
    if (row && DSI_STEWARD_CONFIG.terminalStatuses.has((row.status || '').trim())) {
      setRowActionPendingId(null);
    }
  }, [candidates, rowActionPendingId]);

  const workspaceColumns = useMemo(
    () =>
      buildDsiResolutionWorkspaceColumns({
        planByCandidateId: plan.planByCandidateId,
        formatPlanActionLabel,
        isTerminal: isDsiRowTerminal,
        onFocusRow: openStewardDrawer,
        onOpenPlanDrawer: (id) => plan.handleOpenSuggestionRow(id),
        rowActionPendingId,
        jobId: importJobId,
      }),
    [
      plan.planByCandidateId,
      isDsiRowTerminal,
      openStewardDrawer,
      plan.handleOpenSuggestionRow,
      rowActionPendingId,
      importJobId,
    ]
  );

  const refreshResolutionPlanEffective = useCallback(async () => {
    if (plan.planLoadToken === 0) return;
    await plan.refreshPlanEffective.mutateAsync({
      overrides: plan.overridesPayload(),
      globalSuspicious: plan.planGlobalSuspicious,
    });
  }, [plan]);

  const lookupPeerCandidateByNormalizedKey = useCallback(
    (normalizedKey: string) =>
      candidates.find(
        (c) =>
          c.entity_type === 'customer_dealer_token' && c.normalized_key === normalizedKey
      ) ?? null,
    [candidates]
  );

  const openPeerCandidateByNormalizedKey = useCallback(
    (normalizedKey: string) => {
      const peer = lookupPeerCandidateByNormalizedKey(normalizedKey);
      if (peer) setDetailCandidate(peer);
    },
    [lookupPeerCandidateByNormalizedKey]
  );

  const openActionableCandidates = useMemo(
    () => candidates.filter((c) => !DSI_STEWARD_CONFIG.terminalStatuses.has((c.status || '').trim())),
    [candidates]
  );
  const masterMergeExcluded = validateSummary?.master_merge_excluded_rows ?? 0;
  const stewardMapBlockers = dsiStewardMapBlockingRows(validateSummary);
  const dataQualityBlockers = dsiDataQualityBlockingRows(validateSummary);
  const showBlockerEmptyState =
    !candidatesLoading &&
    (stewardMapBlockers > 0 || dataQualityBlockers > 0 || masterMergeExcluded > 0) &&
    openActionableCandidates.length === 0;

  const candidateWorkspace = (
    <ImportStewardCandidateWorkspace<DsiCandidateRow>
      embedded
      keepTableWhenFilterEmpty={keepTableWhenFilterEmpty}
      rootTestId="dsi-resolution-candidate-grid"
      listDomainId={DSI_STEWARD_CONFIG.listDomainId}
      importJobId={importJobId}
      copy={DSI_STEWARD_CONFIG.listShellCopy}
      openRows={isRegionChannelTab ? [] : candidates}
      filteredRows={isRegionChannelTab ? [] : displayedCandidates}
      busy={stewardOverlayBusy}
      busyOverlay={stewardBusyMessage ? { message: stewardBusyMessage } : null}
      columns={workspaceColumns}
      selection={workspaceSelection}
      tabsSlot={
        tabbedMode ? (
          <Stack spacing={1}>
            <StewardEntityTabsBar
              tabs={DSI_ENTITY_TABS}
              activeTab={activeTab}
              onChange={onTabChange}
              counts={tabCounts}
              busy={stewardOverlayBusy}
              testIdPrefix="dsi"
              ariaLabel="DSI entity resolution"
              formatTabAriaLabel={formatDsiEntityTabLabel}
            />
            {dependencyNudge ? (
              <Alert severity="warning" variant="outlined" data-testid="dsi-tab-dependency-nudge">
                {dependencyNudge}
              </Alert>
            ) : null}
          </Stack>
        ) : undefined
      }
      filtersSlot={
        isRegionChannelTab ? null : (
          <StewardCandidateFilters
            filters={activeFilters}
            onChange={setActiveFilters}
            visibleCount={
              clientQueueFilterActive ? filteredCandidates.length : displayedCandidates.length
            }
            totalCount={tabbedMode ? candidatesPage.total : Math.max(candidatesTotal, candidates.length)}
            hideEntityFilter={tabbedMode}
            hidePartyFilter={tabbedMode && activeTab !== 'distributor'}
            showProductMatchStatusChips={tabbedMode && activeTab === 'product'}
            productMatchStatusCounts={
              tabbedMode && activeTab === 'product' ? productMatchStatusCounts : undefined
            }
            clearToDefault={
              tabbedMode ? () => defaultDsiStewardFiltersForTab(activeTab) : undefined
            }
            isAtDefault={
              tabbedMode
                ? (filters) => dsiStewardFiltersMatchTabDefault(filters, activeTab)
                : undefined
            }
          />
        )
      }
      mainContentSlot={
        isRegionChannelTab ? (
          <DsiRegionChannelTabPanel
            importJobId={importJobId}
            unresolvedGeoQuery={plan.unresolvedGeoQuery}
            catalogChannels={plan.channels}
            catalogRegions={plan.regions}
            onInvalidate={plan.invalidateGeoAndPlan}
          />
        ) : undefined
      }
      isLoading={isRegionChannelTab ? plan.unresolvedGeoQuery.isLoading : candidatesLoading}
      toolbarSlot={
        <Stack ref={workspaceToolbarRef} direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
            {bulkMode === 'selecting' ? (
              <BulkSelectionToolbar
                mode={bulkMode}
                selectedCount={selectedIds.length}
                visibleRowCount={displayedCandidates.length}
                onEnterSelectionMode={() => setBulkMode('selecting')}
                onExitSelectionMode={closeBulkForm}
                onSelectAllVisible={() => setSelectedIds(displayedCandidates.map((c) => c.id))}
                onDeselectAll={() => setSelectedIds([])}
                busy={
                  bulk.bulkPreview.isPending ||
                  bulk.bulkApply.isPending ||
                  plan.applyResolutionPlan.isPending ||
                  plan.refreshPlanEffective.isPending
                }
                previewDangerLabel="Preview bulk steward"
                previewDangerDisabled={
                  selectedIds.length === 0 || bulk.bulkPreview.isPending || !bulk.bulkFormReady
                }
                onPreviewDangerAction={() => void bulk.bulkPreview.mutateAsync()}
              />
            ) : isRegionChannelTab ? (
              <>
                <Button
                  size="small"
                  variant="outlined"
                  onClick={() => openBulkWorkflow('set_plan_fallback_channel')}
                  data-testid="dsi-bulk-channel-open"
                >
                  Plan fallback channel…
                </Button>
                <Typography variant="caption" color="text.secondary">
                  Plan fallbacks below — use bulk Register ISO regions for geographic channel tokens.
                </Typography>
              </>
            ) : (
              <>
                <Button
                  size="small"
                  variant="outlined"
                  disabled={displayedCandidates.length === 0 && selectedIds.length === 0}
                  onClick={() => openBulkWorkflow('map_customer')}
                  data-testid="dsi-bulk-map-open"
                >
                  Bulk map…
                </Button>
                <Button
                  size="small"
                  variant="outlined"
                  disabled={displayedCandidates.length === 0 && selectedIds.length === 0}
                  onClick={() => openBulkWorkflow('create_provisional_customer')}
                  data-testid="dsi-bulk-provisional-open"
                >
                  Bulk provisional…
                </Button>
            <Button
              size="small"
              variant="outlined"
              onClick={() => openBulkWorkflow('apply_suggested_region')}
              disabled={selectedIds.length === 0}
              data-testid="dsi-bulk-apply-suggested-region"
            >
              Apply suggested region…
            </Button>
              </>
            )}
            {tabbedMode && activeTab === 'product' && bulkMode !== 'selecting' && !isRegionChannelTab ? (
              <DsiProductCandidateExportToolbar candidates={displayedCandidates} />
            ) : null}
            {activeTab === 'customer' && bulkMode !== 'selecting' ? (
              <DsiCountryRegionFallback
                importJobId={importJobId}
                enabled={plan.planRegionFallbackEnabled}
                onEnabledChange={plan.setPlanRegionFallbackEnabled}
                onRegionIdChange={plan.setPlanRegionId}
                disabled={stewardOverlayBusy}
                catalogRegions={plan.regions}
              />
            ) : null}
            {!isRegionChannelTab ? (
              <>
                <Button
                  size="small"
                  variant="outlined"
                  disabled={!displayedCandidates.some((c) => plan.planByCandidateId.get(c.id)?.ready === true)}
                  onClick={selectVisibleReadyInGrid}
                  data-testid="dsi-plan-select-visible-ready"
                >
                  Select visible ready
                </Button>
                <Typography variant="caption" color="text.secondary">
                  {selectedIds.length} selected · Ready {plan.readyPlanCandidateIds.length}
                </Typography>
                <Box sx={{ flexGrow: 1 }} />
                <StewardPendingButton
                  variant="outlined"
                  size="small"
                  pending={plan.applyResolutionPlan.isPending}
                  pendingLabel="Applying…"
                  disabled={
                    selectedReadyPlanIds.length === 0 ||
                    planApplyBlocked ||
                    (stewardOverlayBusy && !plan.applyResolutionPlan.isPending)
                  }
                  onClick={() =>
                    void plan.applyResolutionPlan.mutateAsync(selectedReadyPlanIds).catch(() => {})
                  }
                  data-testid="dsi-resolution-plan-apply-selected"
                >
                  Apply selected ready ({selectedReadyPlanIds.length})
                </StewardPendingButton>
              </>
            ) : (
              <Box sx={{ flexGrow: 1 }} />
            )}
          </Stack>
      }
      bulkFormSlot={
        bulkMode === 'selecting' ? (
          <StewardBulkActionInlineForm
            bulk={bulk}
            regions={plan.regions}
            channels={plan.channels}
            onCancel={closeBulkForm}
            testIds={DSI_ENGINE_CONFIG.bulkTestIds}
            renderMapCustomerFields={(args) => <DsiCustomerSearchFields {...args} />}
          />
        ) : null
      }
      getRowSx={(row) => {
        const selected = selectedIdSet.has(row.id);
        const drawerOpen = effectiveDetailCandidate?.id === row.id;
        const verify =
          row.entity_type === 'customer_dealer_token' &&
          row.context &&
          row.context.needs_name_review === true;
        if (verify) {
          return (theme) => ({
            ...(selected || drawerOpen ? { bgcolor: 'action.selected' } : {}),
            boxShadow: `inset 3px 0 0 ${theme.palette.warning.main}`,
          });
        }
        if (selected || drawerOpen) {
          return { bgcolor: 'action.selected' };
        }
        return undefined;
      }}
    />
  );

  return (
    <Stack spacing={2} data-testid="dsi-import-job-resolution">
      <Typography variant="subtitle2">Resolve blockers for this import</Typography>
      <Alert severity="info">
        <Typography variant="body2" component="div">
          <strong>Validate → Resolve → Revalidate → Apply</strong>. Use entity tabs for distributors, customers, and
          products; use <strong>Region &amp; channel</strong> when file geography does not match the catalog.{' '}
          <Link component={NextLink} href={`/admin/imports?job=${importJobId}`}>
            Import job workspace
          </Link>{' '}
          ·{' '}
          <Link component={NextLink} href={`/admin/mappings?import_job_id=${importJobId}`}>
            Mapping queue (legacy)
          </Link>
          .
        </Typography>
      </Alert>

      {showBlockerEmptyState ? (
        <Alert severity="warning" data-testid="dsi-blocker-empty-state">
          <Typography variant="body2" component="div">
            {dataQualityBlockers > 0 ? (
              <>
                <strong>{dataQualityBlockers}</strong> row(s) have a blank product identifier — there is no steward
                candidate for these. Fix the product column mapping on the mapping step, exclude the source file/sheet,
                or remove blank product lines from the file, then re-validate.
                {stewardMapBlockers > 0 || masterMergeExcluded > 0 ? ' ' : null}
              </>
            ) : null}
            {stewardMapBlockers > 0 ? (
              <>
                <strong>{stewardMapBlockers}</strong> row(s) still need steward mapping (unmapped customers or products).
                Open the matching entity tab and clear default filters, or use the global{' '}
                <Link component={NextLink} href={`/admin/mappings?import_job_id=${importJobId}`}>
                  mapping queue
                </Link>
                .
                {masterMergeExcluded > 0 ? ' ' : null}
              </>
            ) : null}
            {masterMergeExcluded > 0 ? (
              <>
                <strong>{masterMergeExcluded}</strong> sell-out row(s) are held for master-data alias conflicts — merge
                duplicate customers on{' '}
                <Link component={NextLink} href="/admin/customers/duplicates?tab=alias_scope">
                  Alias-scope conflicts
                </Link>
                , then re-validate this job.
              </>
            ) : null}
          </Typography>
        </Alert>
      ) : null}

      <StewardResolutionPlanToolbar
        plan={{
          candidatesCount: candidatesTotal,
          readyCount: plan.readyPlanCandidateIds.length,
          suggestionsQuery: plan.suggestionsQuery,
        }}
        testIds={DSI_ENGINE_CONFIG.planToolbarTestIds}
        onApplyAllReady={() => plan.setApplyAllConfirmOpen(true)}
        applyAllPending={plan.applyResolutionPlan.isPending}
        applyAllDisabled={
          plan.readyPlanCandidateIds.length === 0 ||
          planApplyBlocked ||
          (stewardOverlayBusy && !plan.applyResolutionPlan.isPending)
        }
        applyAllLabel={`Apply all ready (${plan.readyPlanCandidateIds.length})`}
        applyAllTestId="dsi-resolution-plan-apply-all"
        dsiExtras={{
          resolutionPlan: plan.resolutionPlan,
          planGlobalSuspicious: plan.planGlobalSuspicious,
          setPlanGlobalSuspicious: plan.setPlanGlobalSuspicious,
          planLoadToken: plan.planLoadToken,
          planTableRows: plan.planTableRows,
          refreshPlanEffective: plan.refreshPlanEffective,
          overridesPayload: plan.overridesPayload,
        }}
      />

      {supervisedAutoResolvedRows.length > 0 ? (
        <Alert severity="info" data-testid="dsi-supervised-auto-resolve-section">
          <Typography variant="subtitle2" sx={{ mb: 1 }}>
            Auto-resolved from prior decisions — review before apply
          </Typography>
          <Typography variant="body2" component="div">
            {supervisedAutoResolvedRows.map((row) => {
              const cid = row.candidate_id;
              const label = row.suggested_target_label ?? row.suggested_target_id ?? '—';
              const nk = row.normalized_key ?? '';
              return (
                <Box key={String(cid)} sx={{ mb: 0.5 }}>
                  <strong>{String(nk)}</strong> → {String(label)} (ready — supervised auto-resolution)
                </Box>
              );
            })}
          </Typography>
        </Alert>
      ) : null}

      {planInitialLoading ? (
        <DsiStewardLoadingCallout
          message="Computing resolution plan…"
          detail="Plan is scoped to the current page of candidates. Large pages may take a few seconds."
          testId="dsi-resolution-plan-loading"
        />
      ) : null}

      {candidatesError ? (
        <Alert severity="error" data-testid="dsi-candidates-load-error">
          {safeDisplayError(candidatesError)}
        </Alert>
      ) : null}

      <StewardWorkspaceViewportShell
        rootTestId="dsi-steward-workspace-viewport-shell"
        left={
          <>
            {planApplySummary ? (
              <Alert
                severity={planApplySummary.severity}
                data-testid="dsi-plan-apply-summary"
                onClose={() => setPlanApplySummary(null)}
              >
                {planApplySummary.message}
              </Alert>
            ) : null}
            {plan.applyResolutionPlan.isError && !planApplySummary ? (
              <Alert severity="error" data-testid="dsi-plan-apply-error">
                Apply failed. Check the activity bell or try again with a smaller batch.
              </Alert>
            ) : null}
            <Box sx={{ flex: 1, minHeight: 0, minWidth: 0, display: 'flex', flexDirection: 'column' }}>
              {candidateWorkspace}
            </Box>

            {tabbedMode && isCandidateTab ? (
              <StewardCandidatesPagination
                page={candidatesPage.page}
                pageCount={clientQueueFilterActive ? filteredPageCount : candidatesPage.pageCount}
                pageSize={candidatesPage.pageSize}
                total={clientQueueFilterActive ? filteredCandidates.length : candidatesPage.total}
                skip={candidatesPage.skip}
                pageItemCount={displayedCandidates.length}
                busy={candidatesPage.query.isFetching}
                onPageChange={candidatesPage.setPage}
                onPageSizeChange={candidatesPage.setPageSize}
              />
            ) : null}
          </>
        }
        drawer={
          effectiveDetailCandidate && isCandidateTab ? (
            <StewardCandidateDrawer
              title={DSI_ENGINE_CONFIG.titleForCandidate(effectiveDetailCandidate)}
              onClose={() => setDetailCandidate(null)}
              rootTestId={DSI_ENGINE_CONFIG.drawerTestIds.root}
              closeTestId={DSI_ENGINE_CONFIG.drawerTestIds.close}
              ariaLabel={DSI_ENGINE_CONFIG.drawerTestIds.ariaLabel}
            >
              <DsiMappingStewardPanel
                importJobId={importJobId}
                candidate={effectiveDetailCandidate}
                planRow={plan.planByCandidateId.get(effectiveDetailCandidate.id) ?? null}
                onRowActionStart={(candidateId) => setRowActionPendingId(candidateId)}
                onRowActionEnd={() => setRowActionPendingId(null)}
                onDone={() => setDetailCandidate(null)}
                onStewardFastComplete={plan.evictResolvedCandidates}
                lookupPeerCandidate={lookupPeerCandidateByNormalizedKey}
                onOpenPeerByNormalizedKey={openPeerCandidateByNormalizedKey}
                customerNormalizedKeysOnPage={customerNormalizedKeysOnPage}
                duplicateClusterMembers={duplicateClusterMembersForSelection}
              />
            </StewardCandidateDrawer>
          ) : null
        }
      />

      <StewardBulkSection
        bulk={bulk}
        plan={plan}
        testIds={DSI_ENGINE_CONFIG.bulkTestIds}
        formatProposedLabel={DSI_ENGINE_CONFIG.formatBulkProposedLabel}
        formatAliasEvidence={DSI_ENGINE_CONFIG.formatBulkAliasEvidence}
      />

      <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
        <StewardPendingButton
          variant="outlined"
          pending={revalidatePipelineBusy}
          pendingLabel="Re-running import validation…"
          disabled={stewardOverlayBusy && !revalidatePipelineBusy}
          onClick={() => void plan.dsiRevalidateFromServer.mutateAsync().catch(() => {})}
          data-testid="dsi-import-revalidate-server"
        >
          Re-run import validation (server)
        </StewardPendingButton>
        <Typography variant="caption" color="text.secondary" sx={{ maxWidth: 520 }}>
          Runs the DSI import validator on the server so staging and blockers refresh. Use after steward saves (single-row,
          bulk, or resolution plan apply). This is <strong>not</strong> the same as <strong>Refresh suggestions</strong>{' '}
          (read-only plan recompute).
        </Typography>
      </Stack>
      {plan.dsiRevalidateFromServer.isError ? (
        <Alert severity="error">{safeDisplayError(plan.dsiRevalidateFromServer.error)}</Alert>
      ) : null}

      <Drawer
        anchor="right"
        open={plan.suggestionDrawerId != null}
        onClose={() => plan.setSuggestionDrawerId(null)}
        PaperProps={{ sx: { width: { xs: '100%', sm: 440 }, maxWidth: '100%' } }}
      >
        <Box sx={{ p: 2 }} data-testid="dsi-resolution-suggestion-drawer">
          <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ mb: 1 }}>
            <Typography variant="subtitle1">Resolution detail</Typography>
            <Button size="small" onClick={() => plan.setSuggestionDrawerId(null)}>
              Close
            </Button>
          </Stack>
          <Divider sx={{ mb: 2 }} />
          {plan.planDrawerRow ? (
            <PlanDialogRowDetail
              r={plan.planDrawerRow}
              candidate={candidatesById[Number(plan.planDrawerRow.candidate_id)]}
              regions={plan.regions}
              channels={plan.channels}
              planOverrideMap={plan.planOverrideMap}
              patchPlanOverride={plan.patchPlanOverride}
            />
          ) : (
            <Typography variant="body2" color="text.secondary" data-testid="dsi-resolution-plan-detail-empty">
              No suggestion row for this candidate.
            </Typography>
          )}
        </Box>
      </Drawer>
    </Stack>
  );
}

'use client';

import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Chip,
  LinearProgress,
  Stack,
  Typography,
} from '@mui/material';
import { alpha, keyframes } from '@mui/material/styles';
import { useEffect, useMemo, useRef, useState } from 'react';

export type PmProgressRailStep = {
  id: string;
  label: string;
  description: string;
  state: 'complete' | 'current' | 'waiting' | 'failed';
};

export type PmProgressSnapshot = {
  phase_id: string;
  phase_label: string;
  phase_description: string;
  rail_index: number;
  step_count: number;
  steps: PmProgressRailStep[];
  job_stage: string;
  job_status: string;
  validation_passed: boolean | null;
  total_rows: number | null | undefined;
  staged_row_count: number;
  row_result_info: number;
  row_result_warnings: number;
  row_result_errors: number;
  error_summary?: string | null;
  started_at?: string | null;
  updated_at?: string | null;
  completed_at?: string | null;
  /** queued | running | failed when async Product Master commit is active */
  commit_async_phase?: string | null;
};

const pulse = keyframes`
  0% { opacity: 0.55; }
  50% { opacity: 1; }
  100% { opacity: 0.55; }
`;

export type PmImportProgressPanelProps = {
  progress: PmProgressSnapshot | null | undefined;
  /** Raw import_job.status (commit_queued / commit_running / …) */
  jobStatus?: string | null;
  isValidating: boolean;
  isCommitting: boolean;
  isSavingMapping?: boolean;
};

function formatElapsed(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}m ${s}s`;
}

export function PmImportProgressPanel({
  progress,
  jobStatus,
  isValidating,
  isCommitting,
  isSavingMapping,
}: PmImportProgressPanelProps) {
  const asyncCommitPending =
    jobStatus === 'commit_queued' || jobStatus === 'commit_running';
  const asyncValidatePending =
    jobStatus === 'validate_queued' || jobStatus === 'validate_running';
  const busy =
    isValidating ||
    isCommitting ||
    Boolean(isSavingMapping) ||
    asyncCommitPending ||
    asyncValidatePending;
  const startRef = useRef<number | null>(null);
  const [tick, setTick] = useState(0);

  useEffect(() => {
    if (busy) {
      if (startRef.current == null) startRef.current = Date.now();
    } else {
      startRef.current = null;
    }
  }, [busy]);

  useEffect(() => {
    if (!busy) return;
    const id = window.setInterval(() => setTick((t) => t + 1), 1000);
    return () => window.clearInterval(id);
  }, [busy]);

  const elapsedSec =
    busy && startRef.current != null
      ? Math.max(0, Math.floor((Date.now() - startRef.current) / 1000))
      : null;
  void tick;

  const phaseTitle = useMemo(() => {
    if (isSavingMapping) return 'Saving mapping';
    if (isValidating) return 'Enqueueing validation';
    if (jobStatus === 'validate_running') return 'Validating (background worker)';
    if (jobStatus === 'validate_queued') return 'Validation queued';
    if (isCommitting) return 'Enqueueing commit';
    if (jobStatus === 'commit_running') return 'Committing (background worker)';
    if (jobStatus === 'commit_queued') return 'Commit queued';
    return progress?.phase_label ?? 'Import status';
  }, [isCommitting, isSavingMapping, isValidating, jobStatus, progress?.phase_description, progress?.phase_label]);

  const phaseDescription = useMemo(() => {
    if (isSavingMapping) return 'Updating column mapping on the server…';
    if (isValidating) return 'Running row checks and building staged metadata. Safe to wait — this can take a while on large files.';
    if (isCommitting) return 'Sending the commit job to the worker…';
    if (jobStatus === 'commit_running') {
      return (
        progress?.phase_description ||
        'The worker is writing product and catalogue rows. This can take several minutes for large files.'
      );
    }
    if (jobStatus === 'commit_queued') {
      return 'Your commit is in the queue and will start when the worker picks it up.';
    }
    return progress?.phase_description ?? '';
  }, [isCommitting, isSavingMapping, isValidating, jobStatus, progress?.phase_description]);

  const steps = progress?.steps ?? [];

  return (
    <Box
      sx={{
        borderRadius: 2,
        p: 2.5,
        mb: 2,
        border: '1px solid',
        borderColor: (t) => alpha(t.palette.divider, 0.9),
        background: (t) =>
          `linear-gradient(165deg, ${alpha(t.palette.primary.main, 0.04)} 0%, ${alpha(t.palette.background.paper, 1)} 42%)`,
        boxShadow: (t) => `0 1px 0 ${alpha(t.palette.common.black, 0.04)}`,
      }}
    >
      <Stack spacing={2}>
        <Stack direction="row" justifyContent="space-between" alignItems="flex-start" flexWrap="wrap" useFlexGap>
          <Box sx={{ minWidth: 200, flex: 1 }}>
            <Typography variant="overline" color="text.secondary" sx={{ letterSpacing: 0.12, fontWeight: 600 }}>
              Product Master import
            </Typography>
            <Typography variant="h6" sx={{ fontWeight: 600, mt: 0.25 }}>
              {phaseTitle}
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5, maxWidth: 640 }}>
              {phaseDescription}
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
            {busy ? (
              <Chip
                size="small"
                label="In progress"
                color="primary"
                variant="outlined"
                sx={{ animation: `${pulse} 1.6s ease-in-out infinite` }}
              />
            ) : null}
            {progress?.job_status ? (
              <Chip size="small" label={progress.job_status} variant="outlined" />
            ) : null}
            {elapsedSec != null ? (
              <Typography variant="caption" color="text.secondary">
                Elapsed {formatElapsed(elapsedSec)}
              </Typography>
            ) : null}
          </Stack>
        </Stack>

        {busy ? (
          <LinearProgress
            variant="indeterminate"
            sx={{
              height: 4,
              borderRadius: 99,
              bgcolor: (t) => alpha(t.palette.primary.main, 0.12),
              '& .MuiLinearProgress-bar': { borderRadius: 99 },
            }}
          />
        ) : (
          <LinearProgress
            variant="determinate"
            value={
              progress && progress.step_count > 1
                ? Math.min(100, (progress.rail_index / (progress.step_count - 1)) * 100)
                : 0
            }
            sx={{
              height: 4,
              borderRadius: 99,
              bgcolor: (t) => alpha(t.palette.text.primary, 0.06),
              '& .MuiLinearProgress-bar': { borderRadius: 99 },
            }}
          />
        )}

        <Stack direction="row" spacing={0.5} flexWrap="wrap" useFlexGap sx={{ pt: 0.5 }}>
          {steps.map((s, i) => {
            const isLast = i === steps.length - 1;
            const color =
              s.state === 'complete'
                ? 'success.main'
                : s.state === 'failed'
                  ? 'error.main'
                  : s.state === 'current'
                    ? 'primary.main'
                    : 'text.disabled';
            const bg =
              s.state === 'complete'
                ? 'success.main'
                : s.state === 'failed'
                  ? 'error.main'
                  : s.state === 'current'
                    ? 'primary.main'
                    : 'action.hover';
            return (
              <Stack key={s.id} direction="row" alignItems="center" sx={{ flex: isLast ? '0 0 auto' : '1 1 0', minWidth: 0 }}>
                <Stack alignItems="center" sx={{ flex: 1, minWidth: 0 }}>
                  <Box
                    sx={{
                      width: 10,
                      height: 10,
                      borderRadius: '50%',
                      bgcolor: bg,
                      opacity: s.state === 'waiting' ? 0.35 : 1,
                      boxShadow: s.state === 'current' ? (t) => `0 0 0 4px ${alpha(t.palette.primary.main, 0.2)}` : 'none',
                      transition: 'box-shadow 0.25s ease, opacity 0.25s ease',
                    }}
                  />
                  <Typography variant="caption" sx={{ mt: 0.5, fontWeight: s.state === 'current' ? 600 : 500, color, textAlign: 'center' }}>
                    {s.label}
                  </Typography>
                </Stack>
                {!isLast ? (
                  <Box
                    sx={{
                      flex: 1,
                      height: 2,
                      mx: 0.5,
                      mb: 2,
                      borderRadius: 99,
                      bgcolor: (t) => alpha(t.palette.text.primary, i < (progress?.rail_index ?? -1) ? 0.18 : 0.08),
                      minWidth: 8,
                    }}
                  />
                ) : null}
              </Stack>
            );
          })}
        </Stack>

        <Accordion disableGutters elevation={0} sx={{ bgcolor: 'transparent', '&:before': { display: 'none' } }}>
          <AccordionSummary expandIcon={<ExpandMoreIcon fontSize="small" />}>
            <Typography variant="caption" color="text.secondary" fontWeight={600}>
              Details &amp; counts
            </Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Stack spacing={0.75}>
              <Typography variant="body2" color="text.secondary">
                <strong>Rows in file:</strong> {progress?.total_rows ?? '—'}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Staged metadata rows:</strong> {progress?.staged_row_count ?? 0}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                <strong>Import messages:</strong> info {progress?.row_result_info ?? 0}, warnings{' '}
                {progress?.row_result_warnings ?? 0}, errors {progress?.row_result_errors ?? 0}
              </Typography>
              {progress?.error_summary ? (
                <Typography variant="body2" color="warning.main">
                  <strong>Summary:</strong> {progress.error_summary}
                </Typography>
              ) : null}
              <Typography variant="caption" color="text.secondary" component="div">
                Stage: {progress?.job_stage ?? '—'} · Last update: {progress?.updated_at ?? '—'}
              </Typography>
            </Stack>
          </AccordionDetails>
        </Accordion>
      </Stack>
    </Box>
  );
}

