        {activeStep === 3 && selectedTemplate && !isPm && !isShipmentEvidence ? (
          <Stack spacing={2}>
            <FormControl size="small" sx={{ maxWidth: 360 }}>
              <InputLabel id="mode-label">Import mode</InputLabel>
