              </Button>
            </Stack>
          </Stack>
        ) : null}

        {activeStep === 4 && isPm && selectedTemplate ? (
          <Stack spacing={2}>
            {pmStateIsError ? (
              <Alert
                severity="error"
                action={
                  <Button color="inherit" size="small" onClick={() => void refetchPmState()}>
