            </Typography>
            <CanonicalColumnMappingPanel
              testIdPrefix="pm"
              fileHeaders={pmJobState.file_headers}
              draft={pmMapDraft}
              onChange={(next) => setPmColumns((prev) => applyPmTargetDraft(prev, next))}
              targetOptions={pmCanonicalTargetOptions}
              columnSamples={pmColumnSamples}
