                Save mapping
              </Button>
              <Button
                variant="contained"
                disabled={!requiredOk || savePmMapping.isPending}
                onClick={() =>
                  void savePmMapping.mutateAsync().then(() => {
                    void refetchPmState();
                    setActiveStep(5);
                  })
                }
              >
                Save & continue to validate
              </Button>
            </Stack>
              </>
            ) : null}
            {pmStateIsError || (!pmJobState?.file_headers?.length && !pmStateLoading) ? (
