                    unmatched names before you apply.
                  </Alert>
                ) : null}
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Row</TableCell>
                      <TableCell>Severity</TableCell>
                      <TableCell>Code</TableCell>
                      <TableCell>Message</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {previewRows.map((r) => (
                      <TableRow key={r.id}>
                        <TableCell>{r.row_number}</TableCell>
                        <TableCell>{r.severity}</TableCell>
                        <TableCell>{r.code}</TableCell>
                        <TableCell>{r.message}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </>
            ) : null}
            {(pmJobState?.staged_row_count ?? 0) > 0 ? (
              <Alert severity="info">
                Staged metadata rows: <strong>{pmJobState?.staged_row_count ?? 0}</strong> row(s) with stage_raw values —
                merged into <code>specs_json.import_staging</code> on commit (derived from the file, not stored on the job).
              </Alert>
            ) : null}
            <Stack direction="row" spacing={1}>
              <Button onClick={() => setActiveStep(4)}>Back</Button>
              <Button variant="contained" disabled={pmJobState?.validation_passed !== true} onClick={() => setActiveStep(6)}>
                Continue to commit
              </Button>
            </Stack>
          </Stack>
        ) : null}

