              </Button>
            </Stack>
          </Stack>
        ) : null}
        </StewardWriteFieldset>
      </Paper>
      </Box>

      <Paper sx={{ p: 2, order: wizardEngaged ? 1 : 0 }} data-testid="import-jobs-panel">
        <Typography variant="subtitle1" fontWeight={600} gutterBottom>
