  ResolutionWorklist,
  type WorkItemProtection,
} from '@/features/steward-worklist';

import { PoDismissReasonDialog } from './PoDismissReasonDialog';
import { currentQuarterLabel } from './poPeriodUtils';

type MatchedProduct = {
  product_id: number;
  sku?: string | null;
  sales_model_name?: string | null;
  marketing_name?: string | null;
  planned_units: number;
  shipped_units: number;
  open_order_units?: number;
};

export type BulkProtection = {
  selection_protected: boolean;
  requires_allow_protected: boolean;
  reasons: string[];
  contested: boolean;
};

export type PoAutoLinkCompetition = {
  status: string;
  reason?: string | null;
  competing_case_ids?: number[];
  case_bus?: string[] | null;
  ship_bus?: string[] | null;
  period_keys?: string[] | null;
  blocks_apply?: boolean;
};

export type PoAutoLinkProposal = {
  proposal_key: string;
  case_id: number;
  case_period_label: string | null;
  inferred_period_start: string | null;
  file_name?: string | null;
  file_base?: string | null;
  version_prefix?: string | null;
  customer_id: number | null;
  customer_label: string | null;
  distributor_id: number | null;
  distributor_code: string | null;
  distributor_name: string | null;
  purchase_order_id: number;
  po_number: string | null;
  po_number_norm: string | null;
  confidence: 'high' | 'medium';
  reason: string;
  date_source: string;
  dismissed?: boolean;
  matched_products: MatchedProduct[];
  total_planned_units: number;
  total_shipped_units: number;
  total_open_order_units?: number;
  commercial_status?: string | null;
  po_link_count?: number;
  competition?: PoAutoLinkCompetition | null;
  bulk_protection?: BulkProtection | null;
};

function protectionReasonLabels(p: PoAutoLinkProposal): string[] {
  const labels: string[] = [];
  const reasons = p.bulk_protection?.reasons ?? [];
  for (const r of reasons) {
    if (r === 'status_advanced') labels.push(`status ${p.commercial_status ?? 'advanced'}`);
    else if (r === 'confirmed_po_links') labels.push(`has ${p.po_link_count ?? '?'} PO link(s)`);
    else if (r === 'tenant_protected_id') labels.push('tenant-protected case id');
    else labels.push(r);
  }
  if (p.bulk_protection?.contested || p.competition?.status === 'contested') {
    labels.push('contested PO');
  }
  return labels;
}

function isSelectionProtected(p: PoAutoLinkProposal): boolean {
  return Boolean(p.bulk_protection?.selection_protected);
}

function requiresAllowProtected(p: PoAutoLinkProposal): boolean {
  return Boolean(p.bulk_protection?.requires_allow_protected);
}

function isContested(p: PoAutoLinkProposal): boolean {
  return Boolean(p.bulk_protection?.contested || p.competition?.status === 'contested');
}

function toWorkItemProtection(p: PoAutoLinkProposal): WorkItemProtection | null {
  const bp = p.bulk_protection;
  const contested = isContested(p);
  if (!bp && !contested) return null;
  return {
    selectionProtected: Boolean(bp?.selection_protected || contested),
    requiresOverride: Boolean(bp?.requires_allow_protected),
    contested,
    reasonLabels: protectionReasonLabels(p),
  };
}

type PoAutoLinkBucketId = 'all' | 'contested' | 'clean' | 'high' | 'medium';

function matchesBucket(p: PoAutoLinkProposal, bucket: PoAutoLinkBucketId): boolean {
  if (bucket === 'all') return true;
  if (bucket === 'high') return p.confidence === 'high';
  if (bucket === 'medium') return p.confidence === 'medium';
  if (bucket === 'contested') return isContested(p);
  if (bucket === 'clean') return !isContested(p);
  return true;
}

function proposalGroupKey(p: PoAutoLinkProposal): string {
  const period = p.case_period_label ?? p.inferred_period_start ?? '';
  return `${period}|${p.customer_id ?? 'null'}`;
}

type GroupCoverageEntry = {
  group_key: string;
  linked_shipped_units: number;
  group_planned_units?: number;
};

type ProposalsResponse = {
  proposals: PoAutoLinkProposal[];
  total: number;
  returned: number;
  dismissed?: { proposal_key: string; case_id: number; purchase_order_id: number; reason_code: string | null }[];
  dismissed_count?: number;
  data_unavailable?: boolean;
  group_coverage?: GroupCoverageEntry[];
  group_coverage_by_key?: Record<string, GroupCoverageEntry>;
};

export type PoAutoLinkProposalGroup = {
  groupKey: string;
  case_period_label: string | null;
  inferred_period_start: string | null;
  customer_id: number | null;
  customer_label: string | null;
  groupPlanUnits: number;
  proposedShipUnits: number;
  proposedPipelineUnits: number;
  linkedShipUnits: number;
  proposals: PoAutoLinkProposal[];
};

function fmtUnits(n: number | null | undefined): string {
  if (n == null) return '—';
  return new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(n);
}

function confidenceColor(c: string): 'success' | 'warning' | 'default' {
  if (c === 'high') return 'success';
  if (c === 'medium') return 'warning';
  return 'default';
}

function reasonLabel(reason: string): string {
  const map: Record<string, string> = {
    customer_product_crad_in_period: 'Customer + product + CRAD in period',
    customer_product_date_fallback_in_period: 'Customer + product + ship date in period',
    product_period_customer_unresolved: 'Product + period (customer unresolved)',
  };
  return map[reason] ?? reason;
}

function productDisplayLabel(m: MatchedProduct): string {
  const parts = [m.sales_model_name, m.sku].filter(Boolean);
  if (parts.length) return parts.join(' · ');
  if (m.marketing_name) return m.marketing_name;
  return `Product #${m.product_id}`;
}

function customerDisplayLabel(p: PoAutoLinkProposal): string {
  if (p.customer_label?.trim()) return p.customer_label.trim();
  if (p.customer_id != null) return `Customer #${p.customer_id}`;
  return 'Unresolved customer';
}

function periodSortKey(g: PoAutoLinkProposalGroup): string {
  return g.inferred_period_start ?? g.case_period_label ?? '';
}

export function dedupeGroupPlanUnits(proposals: PoAutoLinkProposal[]): number {
  const byProduct = new Map<number, number>();
  for (const p of proposals) {
    for (const m of p.matched_products) {
      byProduct.set(m.product_id, Math.max(byProduct.get(m.product_id) ?? 0, m.planned_units));
    }
  }
  return [...byProduct.values()].reduce((sum, n) => sum + n, 0);
}

function sumProposedShipUnits(proposals: PoAutoLinkProposal[]): number {
  return proposals.reduce((sum, p) => sum + (p.total_shipped_units ?? 0), 0);
}

function sumProposedPipelineUnits(proposals: PoAutoLinkProposal[]): number {
  return proposals.reduce((sum, p) => sum + (p.total_open_order_units ?? 0), 0);
}

export function formatCoverageLineParts({
  planUnits,
  proposedShipUnits,
  proposedPipelineUnits,
  linkedShipUnits,
}: {
  planUnits: number;
  proposedShipUnits: number;
  proposedPipelineUnits: number;
  linkedShipUnits: number;
}): string {
  const parts: string[] = [`Plan ${fmtUnits(planUnits)}`];
  if (proposedShipUnits > 0 || proposedPipelineUnits > 0) {
    let proposed = `shipped ${fmtUnits(proposedShipUnits)}`;
    if (proposedPipelineUnits > 0) {
      proposed += ` + pipeline ${fmtUnits(proposedPipelineUnits)} proposed`;
    } else if (proposedShipUnits > 0) {
      proposed += ' proposed';
    }
    parts.push(proposed);
  }
  if (linkedShipUnits > 0) {
    parts.push(`${fmtUnits(linkedShipUnits)} already linked`);
  }
  return parts.join(' · ');
}

function sortProposalsInGroup(proposals: PoAutoLinkProposal[]): PoAutoLinkProposal[] {
  return [...proposals].sort((a, b) => {
    const conf = (b.confidence === 'high' ? 1 : 0) - (a.confidence === 'high' ? 1 : 0);
    if (conf !== 0) return conf;
    const poA = a.po_number ?? String(a.purchase_order_id);
    const poB = b.po_number ?? String(b.purchase_order_id);
    return poA.localeCompare(poB);
  });
}

export function buildProposalGroups(
  proposals: PoAutoLinkProposal[],
  coverageByKey?: Record<string, GroupCoverageEntry>,
): PoAutoLinkProposalGroup[] {
  const groups = new Map<string, PoAutoLinkProposal[]>();
  for (const p of proposals) {
    const key = proposalGroupKey(p);
    const bucket = groups.get(key) ?? [];
    bucket.push(p);
    groups.set(key, bucket);
  }

  return [...groups.entries()]
    .map(([groupKey, bucket]) => {
      const first = bucket[0];
      return {
        groupKey,
        case_period_label: first.case_period_label,
        inferred_period_start: first.inferred_period_start,
        customer_id: first.customer_id,
        customer_label: first.customer_label,
        groupPlanUnits:
          coverageByKey?.[groupKey]?.group_planned_units ?? dedupeGroupPlanUnits(bucket),
        proposedShipUnits: sumProposedShipUnits(bucket),
        proposedPipelineUnits: sumProposedPipelineUnits(bucket),
        linkedShipUnits: coverageByKey?.[groupKey]?.linked_shipped_units ?? 0,
        proposals: sortProposalsInGroup(bucket),
      };
    })
    .sort((a, b) => {
      const periodCmp = periodSortKey(b).localeCompare(periodSortKey(a));
      if (periodCmp !== 0) return periodCmp;
      return customerDisplayLabel(a.proposals[0]).localeCompare(customerDisplayLabel(b.proposals[0]));
    });
}

/** @deprecated Use buildProposalGroups — kept for tests migrating off synthetic grid rows. */
export function buildGroupedPoAutoLinkRows(proposals: PoAutoLinkProposal[]) {
  return buildProposalGroups(proposals);
}

function MatchedProductsChip({ products }: { products: MatchedProduct[] }) {
  if (!products.length) {
    return <Chip size="small" variant="outlined" label="0 products" />;
  }
  const preview = products.slice(0, 5).map(productDisplayLabel).join(' · ');
  const suffix = products.length > 5 ? ` … +${products.length - 5} more` : '';
  return (
    <Tooltip title={`${preview}${suffix}`}>
      <Chip
        size="small"
        variant="outlined"
        label={`${products.length} product${products.length === 1 ? '' : 's'}`}
        data-testid="matched-products-count-chip"
      />
    </Tooltip>
  );
}

function PoAutoLinkConfirmDialog({
  open,
  proposal,
  onClose,
  onConfirm,
  isPending,
  error,
}: {
  open: boolean;
  proposal: PoAutoLinkProposal | null;
  onClose: () => void;
  onConfirm: (notes: string, allowProtected: boolean) => void;
  isPending: boolean;
  error: string | null;
}) {
  const [notes, setNotes] = useState('');
  const [allowProtected, setAllowProtected] = useState(false);

  if (!proposal) return null;

  const needsOverride = requiresAllowProtected(proposal);
  const protectionLabels = protectionReasonLabels(proposal);

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth data-testid="po-auto-link-confirm-dialog">
      <DialogTitle>Link PO to lineup case</DialogTitle>
      <DialogContent>
        <Stack spacing={2} sx={{ mt: 1 }}>
          <Typography variant="body2" color="text.secondary">
            This links the observed purchase order to the lineup case and sets the case to{' '}
            <strong>PO linked</strong>. Review customer and product overlap before confirming.
          </Typography>
          {protectionLabels.length > 0 ? (
            <Alert
              severity={needsOverride ? 'warning' : 'info'}
              data-testid="po-auto-link-confirm-protection"
            >
              Protected from bulk automation: {protectionLabels.join('; ')}.
              {needsOverride
                ? ' Deliberate override required to link.'
                : ' Contested items stay linkable individually (FLAG≠BLOCK).'}
            </Alert>
          ) : null}
          <Box>
            <Typography variant="caption" color="text.secondary">
              Customer
            </Typography>
            <Typography variant="body1" data-testid="confirm-customer-label">
              {customerDisplayLabel(proposal)}
            </Typography>
          </Box>
          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap data-testid="po-auto-link-confirm-case-meta">
            <CaseFileChips proposal={proposal} />
            <Chip size="small" label={proposal.case_period_label ?? proposal.inferred_period_start ?? '—'} />
            <Chip size="small" color={confidenceColor(proposal.confidence)} label={proposal.confidence} />
            <Chip size="small" variant="outlined" label={reasonLabel(proposal.reason)} />
            {proposal.commercial_status ? (
              <Chip size="small" variant="outlined" label={proposal.commercial_status} />
            ) : null}
            <CompetitionChip proposal={proposal} />
          </Stack>
          {proposal.competition?.competing_case_ids?.filter((id) => id !== proposal.case_id).length ? (
            <Alert severity="warning" data-testid="po-auto-link-confirm-competitors">
              Also proposed for case(s){' '}
              {proposal.competition.competing_case_ids
                .filter((id) => id !== proposal.case_id)
                .join(', ')}
              . Do not link both sides blindly — confirm this winner only.
            </Alert>
          ) : null}
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>PO</TableCell>
                <TableCell>Distributor</TableCell>
                <TableCell align="right">Planned</TableCell>
                <TableCell align="right">Shipped</TableCell>
                <TableCell align="right">Pipeline</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              <TableRow>
                <TableCell>{proposal.po_number ?? `#${proposal.purchase_order_id}`}</TableCell>
                <TableCell>
                  {[proposal.distributor_code, proposal.distributor_name].filter(Boolean).join(' — ') || '—'}
                </TableCell>
                <TableCell align="right">{fmtUnits(proposal.total_planned_units)}</TableCell>
                <TableCell align="right">{fmtUnits(proposal.total_shipped_units)}</TableCell>
                <TableCell align="right">{fmtUnits(proposal.total_open_order_units ?? 0)}</TableCell>
              </TableRow>
            </TableBody>
          </Table>
          {proposal.matched_products.length > 0 && (
            <Box>
              <Typography variant="subtitle2" gutterBottom>
                Matched products ({proposal.matched_products.length})
              </Typography>
              <Table size="small" data-testid="po-auto-link-matched-products-table">
                <TableHead>
                  <TableRow>
                    <TableCell>Product</TableCell>
                    <TableCell align="right">Planned</TableCell>
                    <TableCell align="right">Shipped</TableCell>
                    <TableCell align="right">Pipeline</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {proposal.matched_products.map((m) => (
                    <TableRow key={m.product_id} data-testid={`matched-product-${m.product_id}`}>
                      <TableCell>
                        <Tooltip title={`Product ID ${m.product_id}`}>
                          <span data-testid={`matched-product-label-${m.product_id}`}>{productDisplayLabel(m)}</span>
                        </Tooltip>
                        {m.marketing_name && m.sales_model_name ? (
                          <Typography variant="caption" color="text.secondary" display="block">
                            {m.marketing_name}
                          </Typography>
                        ) : null}
                      </TableCell>
                      <TableCell align="right">{fmtUnits(m.planned_units)}</TableCell>
                      <TableCell align="right">{fmtUnits(m.shipped_units)}</TableCell>
                      <TableCell align="right">{fmtUnits(m.open_order_units ?? 0)}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </Box>
          )}
          <TextField
            size="small"
            label="Notes (optional)"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            multiline
            rows={2}
            fullWidth
          />
          {needsOverride ? (
            <FormControlLabel
              control={
                <Checkbox
                  size="small"
                  checked={allowProtected}
                  onChange={(e) => setAllowProtected(e.target.checked)}
                  inputProps={
                    { 'data-testid': 'po-auto-link-allow-protected' } as InputHTMLAttributes<HTMLInputElement>
                  }
                />
              }
              label="Allow linking this protected case (deliberate override)"
            />
          ) : null}
          {error && (
            <Alert severity="error" data-testid="po-auto-link-confirm-error">
              {error}
            </Alert>
          )}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button size="small" onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button
          size="small"
          variant="contained"
          disabled={isPending || (needsOverride && !allowProtected)}
          onClick={() => onConfirm(notes, allowProtected)}
          data-testid="po-auto-link-confirm-submit"
        >
          {isPending ? 'Linking…' : 'Link PO to case'}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

function BulkLinkConfirmDialog({
  open,
  totalCount,
  byCustomer,
  excluded,
  onClose,
  onConfirm,
  isPending,
  error,
  progress,
}: {
  open: boolean;
  totalCount: number;
  byCustomer: { label: string; count: number }[];
  excluded: { label: string; reasons: string }[];
  onClose: () => void;
  onConfirm: () => void;
  isPending: boolean;
  error: string | null;
  progress?: PoAutoLinkApplyProgress | null;
}) {
  const breakdown =
    byCustomer.map((c) => `${c.label} ${c.count}`).join(', ') || '—';

  return (
    <Dialog
      open={open}
      onClose={isPending ? undefined : onClose}
      maxWidth="sm"
      fullWidth
      data-testid="po-auto-link-bulk-confirm-dialog"
    >
      <DialogTitle>Confirm bulk link</DialogTitle>
      <DialogContent>
        <Stack spacing={2} sx={{ mt: 1 }}>
          <Typography variant="body2" data-testid="po-auto-link-bulk-confirm-summary">
            Linking {totalCount} proposal{totalCount === 1 ? '' : 's'}: {breakdown}
          </Typography>
          {excluded.length > 0 ? (
            <Alert severity="warning" data-testid="po-auto-link-bulk-excluded">
              Excluded from bulk ({excluded.length}):{' '}
              {excluded.map((e) => `${e.label} (${e.reasons})`).join('; ')}
            </Alert>
          ) : null}
          {!isPending ? (
            <Typography variant="body2" color="text.secondary">
              Each selected PO will be linked to its lineup case (status advances to PO linked; steward work stays open).
              Protected / contested cases stay out of select-all; override is single-item only.
            </Typography>
          ) : null}
          {isPending && progress ? (
            <Box>
              <Typography variant="body2" sx={{ mb: 0.5 }}>
                {progress.itemsDone} / {progress.itemsTotal} processed
                {progress.batchTotal > 1 ? ` · batch ${progress.batchIndex} of ${progress.batchTotal}` : ''}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={progress.itemsTotal > 0 ? (progress.itemsDone / progress.itemsTotal) * 100 : 0}
              />
            </Box>
          ) : null}
          {error && <Alert severity="error">{error}</Alert>}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button size="small" onClick={onClose} disabled={isPending}>
          Cancel
        </Button>
        <Button
          size="small"
          variant="contained"
          disabled={isPending || totalCount === 0}
          onClick={onConfirm}
          data-testid="po-auto-link-bulk-confirm-submit"
        >
          {isPending ? 'Linking…' : `Link ${totalCount} proposal${totalCount === 1 ? '' : 's'}`}
        </Button>
      </DialogActions>
    </Dialog>
  );
}

function CoverageLine({
  planUnits,
  proposedShipUnits,
  proposedPipelineUnits,
  linkedShipUnits,
}: {
  planUnits: number;
  proposedShipUnits: number;
  proposedPipelineUnits: number;
  linkedShipUnits: number;
}) {
  const overPlan =
    proposedShipUnits > planUnits && planUnits > 0 && proposedPipelineUnits === 0;
  return (
    <Stack direction="row" spacing={0.5} alignItems="center" flexWrap="wrap" useFlexGap>
      <Typography variant="body2" color="text.secondary" data-testid="po-auto-link-coverage-line" component="span">
        {formatCoverageLineParts({
          planUnits,
          proposedShipUnits,
          proposedPipelineUnits,
          linkedShipUnits,
        })}
      </Typography>
      {proposedPipelineUnits > 0 ? (
        <Chip
          size="small"
          label="pipeline"
          variant="outlined"
          color="info"
          sx={{ height: 20, fontSize: '0.7rem' }}
          data-testid="po-auto-link-pipeline-chip"
        />
      ) : null}
      {overPlan ? (
        <Typography component="span" variant="body2" color="text.secondary">
          (over plan — expected when multiple POs cover the same customer period)
        </Typography>
      ) : null}
    </Stack>
  );
}

function CompetitionChip({ proposal }: { proposal: PoAutoLinkProposal }) {
  const comp = proposal.competition;
  if (!comp?.status || comp.status === 'not_contested') return null;
  const rivals = (comp.competing_case_ids ?? []).filter((id) => id !== proposal.case_id);
  const statusBit =
    comp.status === 'contested'
      ? 'Contested'
      : comp.status === 'indeterminate'
        ? 'Indeterminate'
        : comp.status;
  const label =
    rivals.length > 0
      ? `${statusBit}: also cases ${rivals.join(', ')}`
      : `Competition: ${statusBit.toLowerCase()}`;
  const tipParts = [
    comp.reason,
    rivals.length ? `Competing case ids: ${rivals.join(', ')}` : null,
    comp.case_bus?.length ? `Case BUs: ${comp.case_bus.join(', ')}` : null,
    comp.ship_bus?.length ? `Ship BUs: ${comp.ship_bus.join(', ')}` : null,
    comp.period_keys?.length ? `Periods: ${comp.period_keys.join(', ')}` : null,
  ].filter(Boolean);
  return (
    <Tooltip title={tipParts.join(' · ') || label}>
      <Chip
        size="small"
        variant="outlined"
        color="warning"
        label={label}
        data-testid="po-auto-link-competition-chip"
      />
    </Tooltip>
  );
}

function CaseFileChips({ proposal }: { proposal: PoAutoLinkProposal }) {
  const fileLabel =
    proposal.version_prefix != null && proposal.file_base
      ? `v${proposal.version_prefix} · ${proposal.file_base}`
      : proposal.file_base || proposal.file_name || null;
  return (
    <>
      <Chip
        size="small"
        variant="outlined"
        component={Link}
        href="/lineup/cases"
        clickable
        label={`Case ${proposal.case_id}`}
        data-testid="po-auto-link-case-id-chip"
      />
      {fileLabel ? (
        <Tooltip title={proposal.file_name ?? fileLabel}>
          <Chip size="small" variant="outlined" label={fileLabel} data-testid="po-auto-link-file-chip" />
        </Tooltip>
      ) : null}
    </>
  );
}

function PoAutoLinkProposalRowContent({
  proposal,
  onReview,
  onDismiss,
  onRestore,
  restorePending,
}: {
  proposal: PoAutoLinkProposal;
  onReview: () => void;
  onDismiss: () => void;
  onRestore: () => void;
  restorePending: boolean;
}) {
  const dismissed = !!proposal.dismissed;

  return (
    <Stack
      direction={{ xs: 'column', sm: 'row' }}
      spacing={1}
      alignItems={{ sm: 'center' }}
      sx={{
        py: 0.75,
        px: 1,
        borderRadius: 1,
        opacity: dismissed ? 0.55 : 1,
        bgcolor: dismissed ? 'action.hover' : 'transparent',
        flex: 1,
      }}
    >
      <Stack direction="row" spacing={1} alignItems="center" flex={1} flexWrap="wrap" useFlexGap>
        <Tooltip title={reasonLabel(proposal.reason)}>
          <Chip size="small" color={confidenceColor(proposal.confidence)} label={proposal.confidence} />
        </Tooltip>
        <CaseFileChips proposal={proposal} />
        <Typography variant="body2" fontWeight={500}>
          {proposal.po_number ?? `#${proposal.purchase_order_id}`}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          {[proposal.distributor_code, proposal.distributor_name].filter(Boolean).join(' — ') || '—'}
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Shipped {fmtUnits(proposal.total_shipped_units)}
          {(proposal.total_open_order_units ?? 0) > 0 ? (
            <>
              {' '}
              <Typography component="span" variant="body2" color="info.main">
                +{fmtUnits(proposal.total_open_order_units)} pipeline
              </Typography>
            </>
          ) : null}
        </Typography>
        <MatchedProductsChip products={proposal.matched_products} />
        <CompetitionChip proposal={proposal} />
        {isSelectionProtected(proposal) ? (
          <Tooltip title={protectionReasonLabels(proposal).join('; ') || 'Protected'}>
            <Chip
              size="small"
              color="warning"
              variant="outlined"
              label={
                requiresAllowProtected(proposal)
                  ? 'Protected'
                  : proposal.competition?.status === 'contested'
                    ? 'Contested'
                    : 'Protected'
              }
              data-testid={`po-auto-link-protected-${proposal.proposal_key}`}
            />
          </Tooltip>
        ) : null}
      </Stack>
      <Stack direction="row" spacing={0.5} flexShrink={0}>
        {dismissed ? (
          <Button size="small" onClick={onRestore} disabled={restorePending} data-testid={`po-auto-link-restore-${proposal.proposal_key}`}>
            Restore
          </Button>
        ) : (
          <>
            <Button size="small" onClick={onReview} data-testid={`po-auto-link-review-${proposal.proposal_key}`}>
              Review
            </Button>
            <Button size="small" color="warning" onClick={onDismiss}>
              Dismiss
            </Button>
          </>
        )}
      </Stack>
    </Stack>
  );
}

function PoAutoLinkGroupHeader({
  group,
  expanded,
  onToggleExpanded,
  selected,
  onSelectAllInCard,
  onLinkSelectedInCard,
  applyPending,
}: {
  group: PoAutoLinkProposalGroup;
  expanded: boolean;
  onToggleExpanded: () => void;
  selected: Set<string>;
  onSelectAllInCard: (keys: string[]) => void;
  onLinkSelectedInCard: (keys: string[]) => void;
  applyPending: boolean;
}) {
  const autoSelectable = group.proposals.filter((p) => !p.dismissed && !isSelectionProtected(p));
  const selectedInCard = group.proposals.filter((p) => !p.dismissed && selected.has(p.proposal_key));
  const selectedLinkable = selectedInCard.filter((p) => !requiresAllowProtected(p));
  const allSelected = autoSelectable.length > 0 && autoSelectable.every((p) => selected.has(p.proposal_key));
  const someSelected =
    autoSelectable.some((p) => selected.has(p.proposal_key)) && !allSelected;
  const protectedInCard = group.proposals.filter((p) => !p.dismissed && isSelectionProtected(p));
  const periodLabel = group.case_period_label ?? group.inferred_period_start ?? '—';
  const customerLabel = customerDisplayLabel(group.proposals[0]);

  return (
    <Card variant="outlined" data-testid={`po-auto-link-group-card-${group.groupKey}`} sx={{ mb: 1 }}>
      <CardContent sx={{ pb: expanded ? 2 : '16px !important' }}>
        <Stack spacing={1}>
          <Stack
            direction={{ xs: 'column', md: 'row' }}
            spacing={1}
            alignItems={{ md: 'center' }}
            justifyContent="space-between"
          >
            <Stack direction="row" spacing={1} alignItems="flex-start" flexWrap="wrap" useFlexGap sx={{ flex: 1 }}>
              <IconButton size="small" onClick={onToggleExpanded} aria-label={expanded ? 'Collapse card' : 'Expand card'}>
                {expanded ? <ExpandLessIcon fontSize="small" /> : <ExpandMoreIcon fontSize="small" />}
              </IconButton>
              <Chip size="small" label={periodLabel} />
              <Typography
                variant="subtitle1"
                fontWeight={600}
                sx={{ whiteSpace: 'normal', wordBreak: 'break-word', maxWidth: '100%' }}
                data-testid={`po-auto-link-group-customer-${group.groupKey}`}
              >
                {customerLabel}
              </Typography>
            </Stack>
            <Chip
              size="small"
              variant="outlined"
              label={`${selectedInCard.length} of ${group.proposals.filter((p) => !p.dismissed).length} selected`}
              data-testid={`po-auto-link-group-selection-${group.groupKey}`}
            />
          </Stack>

          <Box sx={{ pl: { xs: 0, sm: 5 } }}>
            <Typography variant="body2" color="text.secondary">
              Period plan (customer-scoped): {fmtUnits(group.groupPlanUnits)}
            </Typography>
            <CoverageLine
              planUnits={group.groupPlanUnits}
              proposedShipUnits={group.proposedShipUnits}
              proposedPipelineUnits={group.proposedPipelineUnits}
              linkedShipUnits={group.linkedShipUnits}
            />
          </Box>

          {!expanded && (
            <Typography variant="caption" color="text.secondary" sx={{ pl: { xs: 0, sm: 5 } }}>
              {group.proposals.length} proposal{group.proposals.length === 1 ? '' : 's'} · expand to review rows
            </Typography>
          )}

          <Collapse in={expanded}>
            <Divider sx={{ my: 1 }} />
            <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap sx={{ mb: 1 }}>
              <FormControlLabel
                control={
                  <Checkbox
                    size="small"
                    checked={allSelected}
                    indeterminate={someSelected}
                    disabled={!autoSelectable.length}
                    onChange={() => {
                      if (allSelected) onSelectAllInCard([]);
                      else onSelectAllInCard(autoSelectable.map((p) => p.proposal_key));
                    }}
                    inputProps={
                      { 'data-testid': `po-auto-link-card-select-all-${group.groupKey}` } as InputHTMLAttributes<HTMLInputElement>
                    }
                  />
                }
                label="Select all in card"
              />
              {protectedInCard.length > 0 ? (
                <Typography
                  variant="caption"
                  color="warning.main"
                  data-testid={`po-auto-link-card-excluded-${group.groupKey}`}
                >
                  {protectedInCard.length} excluded from select-all (protected/contested — select individually)
                </Typography>
              ) : null}
              <Button
                size="small"
                variant="contained"
                disabled={!selectedLinkable.length || applyPending}
                onClick={() => onLinkSelectedInCard(selectedLinkable.map((p) => p.proposal_key))}
                data-testid={`po-auto-link-card-link-${group.groupKey}`}
              >
                Link selected ({selectedLinkable.length})
              </Button>
            </Stack>
          </Collapse>
        </Stack>
      </CardContent>
    </Card>
  );
}

const PO_AUTO_LINK_APPLY_CHUNK = 100;

type PoAutoLinkApplyResponse = {
  applied_count?: number;
  error_count?: number;
  errors?: { error: string }[];
  applied?: { newly_linked?: boolean }[];
};

type PoAutoLinkApplyProgress = {
  itemsDone: number;
  itemsTotal: number;
  batchIndex: number;
  batchTotal: number;
};

async function applyPoAutoLinkInChunks(
  items: { case_id: number; purchase_order_id: number; notes?: string; allow_protected?: boolean }[],
  notes?: string,
  onProgress?: (progress: PoAutoLinkApplyProgress) => void,
): Promise<PoAutoLinkApplyResponse & { newly_linked_count: number }> {
  let applied_count = 0;
  let newly_linked_count = 0;
  let error_count = 0;
  const errors: { error: string }[] = [];
  const batchTotal = Math.max(1, Math.ceil(items.length / PO_AUTO_LINK_APPLY_CHUNK));
  onProgress?.({ itemsDone: 0, itemsTotal: items.length, batchIndex: 0, batchTotal });

  for (let i = 0; i < items.length; i += PO_AUTO_LINK_APPLY_CHUNK) {
    const batchIndex = Math.floor(i / PO_AUTO_LINK_APPLY_CHUNK) + 1;
    const chunk = items.slice(i, i + PO_AUTO_LINK_APPLY_CHUNK);
    onProgress?.({
      itemsDone: i,
      itemsTotal: items.length,
      batchIndex,
      batchTotal,
    });
    const data = await apiPost<PoAutoLinkApplyResponse>(
      '/api/v1/commercial-planner/lineup/po-auto-link/apply',
      { items: chunk, notes },
    );
    applied_count += data.applied_count ?? 0;
    newly_linked_count += (data.applied ?? []).filter((row) => row.newly_linked).length;
    error_count += data.error_count ?? 0;
    if (data.errors?.length) errors.push(...data.errors);
    onProgress?.({
      itemsDone: Math.min(i + chunk.length, items.length),
      itemsTotal: items.length,
      batchIndex,
      batchTotal,
    });
  }
  return { applied_count, newly_linked_count, error_count, errors };
}

export const PO_AUTO_LINK_SECTION_ID = 'po-auto-link-section';

type PoAutoLinkProposalsSectionProps = {
  /** Prefetch proposals on mount and auto-expand when pending count &gt; 0. */
  autoFetch?: boolean;
  onPendingCountChange?: (count: number) => void;
};

export function PoAutoLinkProposalsSection({
  autoFetch = false,
  onPendingCountChange,
}: PoAutoLinkProposalsSectionProps) {
  const qc = useQueryClient();
  const [expanded, setExpanded] = useState(false);
  const manualCollapseRef = useRef(false);
  const [period, setPeriod] = useState('');
  const [confidence, setConfidence] = useState<'all' | 'high' | 'medium'>('all');
  const [customerFilter, setCustomerFilter] = useState('');
  const [debouncedCustomer, setDebouncedCustomer] = useState('');
  const [bucket, setBucket] = useState<PoAutoLinkBucketId>('all');
  const [showDismissed, setShowDismissed] = useState(false);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [drawerKey, setDrawerKey] = useState<string | null>(null);
  const [confirmProposal, setConfirmProposal] = useState<PoAutoLinkProposal | null>(null);
  const [bulkConfirmKeys, setBulkConfirmKeys] = useState<string[] | null>(null);
  const [applyError, setApplyError] = useState<string | null>(null);
  const [applySuccess, setApplySuccess] = useState<string | null>(null);
  const [applyProgress, setApplyProgress] = useState<PoAutoLinkApplyProgress | null>(null);
  const [dismissTarget, setDismissTarget] = useState<PoAutoLinkProposal | null>(null);
  const [cardExpanded, setCardExpanded] = useState<Record<string, boolean>>({});
  const [manualCaseId, setManualCaseId] = useState('');
  const [manualPoNumber, setManualPoNumber] = useState('');
  const [manualError, setManualError] = useState<string | null>(null);
  const [manualPending, setManualPending] = useState(false);

  useEffect(() => {
    const handle = window.setTimeout(() => setDebouncedCustomer(customerFilter), 300);
    return () => window.clearTimeout(handle);
  }, [customerFilter]);

  const filtersAtDefault =
    period === '' && confidence === 'all' && customerFilter === '' && bucket === 'all';

  const queryKey = ['po-auto-link', period, confidence, showDismissed] as const;

  const proposalsQ = useQuery({
    queryKey,
    enabled: expanded || autoFetch,
    queryFn: ({ signal }) => {
      const params = new URLSearchParams({ limit: '200' });
      if (period.trim()) params.set('period', period.trim());
      if (confidence !== 'all') params.set('confidence', confidence);
      if (showDismissed) params.set('include_dismissed', 'true');
      return apiGet<ProposalsResponse>(
        `/api/v1/commercial-planner/lineup/po-auto-link/proposals?${params.toString()}`,
        { signal }
      );
    },
  });

  const applyMut = useMutation({
    mutationFn: (vars: { items: { case_id: number; purchase_order_id: number; notes?: string; allow_protected?: boolean }[]; notes?: string }) =>
      applyPoAutoLinkInChunks(vars.items, vars.notes, setApplyProgress),
    onSuccess: (data: {
      applied_count?: number;
      newly_linked_count?: number;
      error_count?: number;
      errors?: { error: string }[];
    }) => {
      const applied = data.applied_count ?? 0;
      const newly = data.newly_linked_count ?? 0;
      const skipped = Math.max(0, applied - newly);
      if (data.error_count) {
        setApplyError(
          data.errors?.map((e) => e.error).join('; ') ?? `${data.error_count} link(s) failed`,
        );
      } else {
        setApplyError(null);
      }
      if (applied > 0) {
        const parts = [`${newly} new PO link${newly === 1 ? '' : 's'} created`];
        if (skipped > 0) parts.push(`${skipped} already linked`);
        if (data.error_count) parts.push(`${data.error_count} failed`);
        setApplySuccess(`Bulk link complete: ${parts.join(' · ')}. Refreshing suggestions…`);
      } else if (!data.error_count) {
        setApplySuccess('Bulk link finished — no changes (all selected proposals were already linked).');
      }
      setConfirmProposal(null);
      setDrawerKey(null);
      setBulkConfirmKeys(null);
      setSelected(new Set());
      void qc.invalidateQueries({ queryKey: ['po-auto-link'] });
      void qc.invalidateQueries({ queryKey: ['po-management'] });
      void qc.invalidateQueries({ queryKey: ['lineup-cases'] });
      void qc.invalidateQueries({ queryKey: ['commercial-lineup-cases'] });
      setApplyProgress(null);
    },
    onError: (e) => {
      setApplyProgress(null);
      setApplySuccess(null);
      setApplyError(safeDisplayError(e));
    },
  });

  const dismissMut = useMutation({
    mutationFn: (vars: {
      proposal_key: string;
      case_id: number;
      purchase_order_id: number;
      reason_code: string;
    }) => apiPost('/api/v1/commercial-planner/lineup/po-auto-link/dismiss', vars),
    onSuccess: () => {
      setDismissTarget(null);
      setDrawerKey(null);
      void qc.invalidateQueries({ queryKey: ['po-auto-link'] });
    },
  });

  const restoreMut = useMutation({
    mutationFn: (proposalKey: string) =>
      apiPost(
        `/api/v1/commercial-planner/lineup/po-auto-link/restore?proposal_key=${encodeURIComponent(proposalKey)}`,
        undefined
      ),
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: ['po-auto-link'] });
    },
  });

  const proposals = proposalsQ.data?.proposals ?? [];
  const activeProposals = useMemo(
    () => (showDismissed ? proposals : proposals.filter((p) => !p.dismissed)),
    [proposals, showDismissed]
  );

  const customerFilteredProposals = useMemo(() => {
    const q = debouncedCustomer.trim().toLowerCase();
    if (!q) return activeProposals;
    return activeProposals.filter((p) => {
      const label = (p.customer_label ?? '').toLowerCase();
      const idToken = p.customer_id != null ? String(p.customer_id) : '';
      return label.includes(q) || idToken.includes(q);
    });
  }, [activeProposals, debouncedCustomer]);

  const bucketFilteredProposals = useMemo(
    () => customerFilteredProposals.filter((p) => matchesBucket(p, bucket)),
    [customerFilteredProposals, bucket],
  );

  const proposalGroups = useMemo(
    () => buildProposalGroups(bucketFilteredProposals, proposalsQ.data?.group_coverage_by_key),
    [bucketFilteredProposals, proposalsQ.data?.group_coverage_by_key],
  );

  const proposalGroupByKey = useMemo(() => {
    const map = new Map<string, PoAutoLinkProposalGroup>();
    for (const g of proposalGroups) map.set(g.groupKey, g);
    return map;
  }, [proposalGroups]);

  const proposalByKey = useMemo(() => {
    const map = new Map<string, PoAutoLinkProposal>();
    for (const p of bucketFilteredProposals) map.set(p.proposal_key, p);
    return map;
  }, [bucketFilteredProposals]);


  useEffect(() => {
    if (!proposalGroups.length) return;
    const defaultExpanded = proposalGroups.length <= 3;
    setCardExpanded((prev) => {
      const next = { ...prev };
      for (const g of proposalGroups) {
        if (!(g.groupKey in next)) next[g.groupKey] = defaultExpanded;
      }
      return next;
    });
  }, [proposalGroups]);

  const bucketCounts = useMemo(
    () => ({
      all: customerFilteredProposals.length,
      contested: customerFilteredProposals.filter((p) => matchesBucket(p, 'contested')).length,
      clean: customerFilteredProposals.filter((p) => matchesBucket(p, 'clean')).length,
      high: customerFilteredProposals.filter((p) => matchesBucket(p, 'high')).length,
      medium: customerFilteredProposals.filter((p) => matchesBucket(p, 'medium')).length,
    }),
    [customerFilteredProposals],
  );

  const pendingCount = Math.max(0, (proposalsQ.data?.total ?? 0) - (proposalsQ.data?.dismissed_count ?? 0));

  useEffect(() => {
    if (!autoFetch) return;
    onPendingCountChange?.(pendingCount);
    if (pendingCount > 0 && !manualCollapseRef.current) {
      setExpanded(true);
    }
  }, [autoFetch, onPendingCountChange, pendingCount]);

  const handleExpand = useCallback(() => {
    manualCollapseRef.current = false;
    setExpanded(true);
  }, []);

  const handleCollapse = useCallback(() => {
    manualCollapseRef.current = true;
    setExpanded(false);
  }, []);

  const toggleProposalSelection = useCallback((key: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }, []);

  const replaceCardSelection = useCallback((groupKey: string, keys: string[]) => {
    const group = proposalGroups.find((g) => g.groupKey === groupKey);
    if (!group) return;
    const groupKeys = new Set(group.proposals.map((p) => p.proposal_key));
    setSelected((prev) => {
      const next = new Set([...prev].filter((k) => !groupKeys.has(k)));
      for (const k of keys) next.add(k);
      return next;
    });
  }, [proposalGroups]);

  const selectAllHigh = () => {
    const keys = bucketFilteredProposals
      .filter((p) => p.confidence === 'high' && !p.dismissed && !isSelectionProtected(p))
      .map((p) => p.proposal_key);
    setSelected(new Set(keys));
  };

  const clearFiltersToDefault = () => {
    setPeriod('');
    setConfidence('all');
    setCustomerFilter('');
    setDebouncedCustomer('');
    setBucket('all');
    setSelected(new Set());
  };

  const handleBucketChange = (id: PoAutoLinkBucketId) => {
    setBucket(id);
    setSelected(new Set());
  };

  const openBulkConfirm = (keys: string[]) => {
    if (!keys.length) return;
    setApplyError(null);
    setBulkConfirmKeys(keys);
  };

  const bulkConfirmPartition = useMemo(() => {
    if (!bulkConfirmKeys?.length) {
      return { linkable: [] as PoAutoLinkProposal[], excluded: [] as PoAutoLinkProposal[] };
    }
    const linkable: PoAutoLinkProposal[] = [];
    const excluded: PoAutoLinkProposal[] = [];
    for (const key of bulkConfirmKeys) {
      const p = proposalByKey.get(key);
      if (!p || p.dismissed) continue;
      if (requiresAllowProtected(p)) excluded.push(p);
      else linkable.push(p);
    }
    return { linkable, excluded };
  }, [bulkConfirmKeys, proposalByKey]);

  const bulkConfirmBreakdown = useMemo(() => {
    const counts = new Map<string, number>();
    for (const p of bulkConfirmPartition.linkable) {
      const label = customerDisplayLabel(p);
      counts.set(label, (counts.get(label) ?? 0) + 1);
    }
    return [...counts.entries()]
      .map(([label, count]) => ({ label, count }))
      .sort((a, b) => a.label.localeCompare(b.label));
  }, [bulkConfirmPartition]);

  const bulkExcludedRows = useMemo(
    () =>
      bulkConfirmPartition.excluded.map((p) => ({
        label: `${customerDisplayLabel(p)} case ${p.case_id} PO ${p.po_number ?? p.purchase_order_id}`,
        reasons: protectionReasonLabels(p).join(', ') || 'protected',
      })),
    [bulkConfirmPartition]
  );

  const executeBulkApply = () => {
    const items = bulkConfirmPartition.linkable.map((p) => ({
      case_id: p.case_id,
      purchase_order_id: p.purchase_order_id,
    }));
    if (!items.length) return;
    setApplyError(null);
    setApplySuccess(null);
    applyMut.mutate({ items });
  };

  const handleSingleConfirm = (notes: string, allowProtected: boolean) => {
    if (!confirmProposal) return;
    setApplyError(null);
    applyMut.mutate({
      items: [
        {
          case_id: confirmProposal.case_id,
          purchase_order_id: confirmProposal.purchase_order_id,
          notes: notes.trim() || undefined,
          ...(allowProtected ? { allow_protected: true } : {}),
        },
      ],
    });
  };

  const handleManualLink = async () => {
    setManualError(null);
    const caseId = Number.parseInt(manualCaseId.trim(), 10);
    if (!Number.isFinite(caseId) || caseId < 1) {
      setManualError('Enter a valid case id');
      return;
    }
    if (!manualPoNumber.trim()) {
      setManualError('Enter an exact PO number');
      return;
    }
    setManualPending(true);
    try {
      const po = await apiGet<{
        purchase_order_id: number;
        po_number: string;
        po_number_norm: string;
      }>(
        `/api/v1/commercial-planner/lineup/po-auto-link/exact-po?po_number=${encodeURIComponent(manualPoNumber.trim())}`,
      );
      await applyPoAutoLinkInChunks(
        [{ case_id: caseId, purchase_order_id: po.purchase_order_id }],
        undefined,
        setApplyProgress,
      );
      setManualCaseId('');
      setManualPoNumber('');
      setApplySuccess(`Manual link applied for case ${caseId} ↔ ${po.po_number}.`);
      void qc.invalidateQueries({ queryKey: ['po-auto-link'] });
      void qc.invalidateQueries({ queryKey: ['po-management'] });
      void qc.invalidateQueries({ queryKey: ['lineup-cases'] });
      void qc.invalidateQueries({ queryKey: ['commercial-lineup-cases'] });
      setApplyProgress(null);
    } catch (e) {
      setManualError(safeDisplayError(e));
      setApplyProgress(null);
    } finally {
      setManualPending(false);
    }
  };

  const isGroupExpanded = (groupKey: string) =>
    cardExpanded[groupKey] ?? proposalGroups.length <= 3;

  return (
    <Card variant="outlined" id={PO_AUTO_LINK_SECTION_ID} data-testid="po-auto-link-section">
      <CardContent>
        <Stack spacing={2}>
          <Stack direction="row" spacing={1} alignItems="flex-start" justifyContent="space-between" flexWrap="wrap" useFlexGap>
            <Box>
              <Typography variant="h6" gutterBottom>
                Suggested PO ↔ lineup links
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Triage tool — compute CRAD-matched proposals on demand. Review and link, or dismiss bad suggestions.
              </Typography>
            </Box>
            {!expanded ? (
              <Button variant="contained" size="small" onClick={handleExpand} data-testid="po-auto-link-expand">
                {autoFetch && proposalsQ.isFetching
                  ? 'Loading suggestions…'
                  : pendingCount > 0
                    ? `Show ${pendingCount} suggestion${pendingCount === 1 ? '' : 's'}`
                    : 'Compute / show suggested links'}
              </Button>
            ) : (
              <Button size="small" variant="outlined" onClick={handleCollapse} data-testid="po-auto-link-collapse">
                Collapse
              </Button>
            )}
          </Stack>

          {(applyMut.isPending || applyProgress || manualPending) && (
            <Box data-testid="po-auto-link-apply-progress">
              <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 0.5 }}>
                <Typography variant="body2">
                  Linking proposals…{' '}
                  {applyProgress
                    ? `${applyProgress.itemsDone} / ${applyProgress.itemsTotal}`
                    : 'starting…'}
                </Typography>
                {applyProgress && applyProgress.batchTotal > 1 ? (
                  <Typography variant="caption" color="text.secondary">
                    Batch {applyProgress.batchIndex} of {applyProgress.batchTotal}
                  </Typography>
                ) : null}
              </Stack>
              <LinearProgress
                variant={applyProgress ? 'determinate' : 'indeterminate'}
                value={
                  applyProgress && applyProgress.itemsTotal > 0
                    ? (applyProgress.itemsDone / applyProgress.itemsTotal) * 100
                    : 0
                }
              />
            </Box>
          )}

          {applySuccess && !confirmProposal && !bulkConfirmKeys && (
            <Alert
              severity="success"
              data-testid="po-auto-link-apply-success"
              onClose={() => setApplySuccess(null)}
            >
              {applySuccess}
            </Alert>
          )}
          {applyError && !confirmProposal && !bulkConfirmKeys && (
            <Alert severity="error" data-testid="po-auto-link-apply-error" onClose={() => setApplyError(null)}>
              {applyError}
            </Alert>
          )}

          <Collapse in={expanded}>
            <Stack spacing={2}>
              {proposalsQ.isLoading ? (
                <Typography variant="body2" color="text.secondary" data-testid="po-auto-link-loading">
                  Computing proposals…
                </Typography>
              ) : proposalsQ.data?.data_unavailable ? (
                <Alert severity="info">Auto-link proposals are temporarily unavailable.</Alert>
              ) : (
                <>
                  <Typography variant="caption" color="text.secondary">
                    Showing {bucketFilteredProposals.length} of {proposalsQ.data?.total ?? 0} proposals
                    {debouncedCustomer.trim() && activeProposals.length !== bucketFilteredProposals.length
                      ? ` (${activeProposals.length} before customer/bucket filter)`
                      : ''}
                    {(proposalsQ.data?.dismissed_count ?? 0) > 0
                      ? ` · ${proposalsQ.data?.dismissed_count} dismissed`
                      : ''}
                  </Typography>
                  {!bucketFilteredProposals.length && !showDismissed ? (
                    <Alert severity="info" data-testid="po-auto-link-empty">
                      No link proposals for the current filters. Try clearing the period or customer filter or lowering confidence.
                    </Alert>
                  ) : null}
                  <Box data-testid="po-auto-link-cards">
                    <ResolutionWorklist<PoAutoLinkProposal, PoAutoLinkBucketId>
                      rootTestId="po-auto-link"
                      getCheckboxTestId={(k) => `po-auto-link-select-${k}`}
                      bordered
                      items={bucketFilteredProposals}
                      getItemKey={(p) => p.proposal_key}
                      getProtection={toWorkItemProtection}
                      buckets={[
                        { id: 'all', label: 'All', count: bucketCounts.all },
                        { id: 'contested', label: 'Contested', count: bucketCounts.contested },
                        { id: 'clean', label: 'Clean', count: bucketCounts.clean },
                        { id: 'high', label: 'High', count: bucketCounts.high },
                        { id: 'medium', label: 'Medium', count: bucketCounts.medium },
                      ]}
                      activeBucket={bucket}
                      onBucketChange={handleBucketChange}
                      groupBy={proposalGroupKey}
                      isGroupCollapsed={(groupKey) => !isGroupExpanded(groupKey)}
                      renderGroupHeader={(groupKey) => {
                        const group = proposalGroupByKey.get(groupKey);
                        if (!group) return null;
                        return (
                          <PoAutoLinkGroupHeader
                            group={group}
                            expanded={isGroupExpanded(groupKey)}
                            onToggleExpanded={() =>
                              setCardExpanded((prev) => ({
                                ...prev,
                                [groupKey]: !isGroupExpanded(groupKey),
                              }))
                            }
                            selected={selected}
                            onSelectAllInCard={(keys) => replaceCardSelection(groupKey, keys)}
                            onLinkSelectedInCard={openBulkConfirm}
                            applyPending={applyMut.isPending}
                          />
                        );
                      }}
                      renderRow={(proposal) => (
                        <PoAutoLinkProposalRowContent
                          proposal={proposal}
                          onReview={() => {
                            setApplyError(null);
                            setDrawerKey(proposal.proposal_key);
                          }}
                          onDismiss={() => setDismissTarget(proposal)}
                          onRestore={() => restoreMut.mutate(proposal.proposal_key)}
                          restorePending={restoreMut.isPending}
                        />
                      )}
                      selection={{
                        selected,
                        onToggle: toggleProposalSelection,
                        onReplace: (keys) => setSelected(new Set(keys)),
                      }}
                      renderFilters={() => (
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} flexWrap="wrap" useFlexGap>
                          <TextField
                            size="small"
                            label="Period filter"
                            placeholder="All periods / include residual"
                            value={period}
                            onChange={(e) => setPeriod(e.target.value)}
                            sx={{ minWidth: 180 }}
                            inputProps={{ 'data-testid': 'po-auto-link-period' }}
                          />
                          <Button
                            size="small"
                            variant="outlined"
                            onClick={() => setPeriod(currentQuarterLabel())}
                            data-testid="po-auto-link-period-this-quarter"
                          >
                            This quarter
                          </Button>
                          <TextField
                            size="small"
                            label="Customer filter"
                            placeholder="Name or customer id"
                            value={customerFilter}
                            onChange={(e) => setCustomerFilter(e.target.value)}
                            sx={{ minWidth: 160 }}
                            data-testid="po-auto-link-customer"
                          />
                          <FormControl size="small" sx={{ minWidth: 140 }}>
                            <InputLabel id="po-auto-link-confidence-label">Confidence</InputLabel>
                            <Select
                              labelId="po-auto-link-confidence-label"
                              label="Confidence"
                              value={confidence}
                              onChange={(e) => setConfidence(e.target.value as 'all' | 'high' | 'medium')}
                              data-testid="po-auto-link-confidence"
                            >
                              <MenuItem value="all">All</MenuItem>
                              <MenuItem value="high">High only</MenuItem>
                              <MenuItem value="medium">Medium only</MenuItem>
                            </Select>
                          </FormControl>
                          <Button size="small" onClick={() => void proposalsQ.refetch()} disabled={proposalsQ.isFetching}>
                            Refresh
                          </Button>
                          {!filtersAtDefault ? (
                            <Button size="small" onClick={clearFiltersToDefault} data-testid="po-auto-link-clear-filters">
                              Clear filters
                            </Button>
                          ) : null}
                        </Stack>
                      )}
                      renderToolbar={() => (
                        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                          <Button size="small" onClick={() => setShowDismissed((v) => !v)} data-testid="po-auto-link-toggle-dismissed">
                            {showDismissed ? 'Hide dismissed' : 'Show dismissed'}
                          </Button>
                          <Button
                            size="small"
                            onClick={selectAllHigh}
                            disabled={!bucketFilteredProposals.some((p) => p.confidence === 'high')}
                          >
                            Select all high
                          </Button>
                          <Button
                            size="small"
                            variant="contained"
                            disabled={selected.size === 0 || applyMut.isPending}
                            onClick={() => openBulkConfirm([...selected])}
                            data-testid="po-auto-link-bulk-apply"
                          >
                            Link selected ({selected.size})
                          </Button>
                        </Stack>
                      )}
                      renderManualLinkSlot={() => (
                        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'flex-start' }} flexWrap="wrap" useFlexGap>
                          <TextField
                            size="small"
                            label="Case id"
                            value={manualCaseId}
                            onChange={(e) => setManualCaseId(e.target.value)}
                            sx={{ minWidth: 100 }}
                            inputProps={{ 'data-testid': 'po-auto-link-manual-case-id' }}
                          />
                          <TextField
                            size="small"
                            label="Exact PO number"
                            value={manualPoNumber}
                            onChange={(e) => setManualPoNumber(e.target.value)}
                            sx={{ minWidth: 160 }}
                            inputProps={{ 'data-testid': 'po-auto-link-manual-po-number' }}
                          />
                          <Button
                            size="small"
                            variant="outlined"
                            disabled={manualPending || applyMut.isPending}
                            onClick={() => void handleManualLink()}
                            data-testid="po-auto-link-manual-link-btn"
                          >
                            Manual link
                          </Button>
                          {manualError ? (
                            <Alert severity="error" sx={{ flex: 1 }} data-testid="po-auto-link-manual-error">
                              {manualError}
                            </Alert>
                          ) : null}
                        </Stack>
                      )}
                      drawer={{
                        activeKey: drawerKey,
                        onClose: () => setDrawerKey(null),
                        title: (p) => `PO ${p.po_number ?? p.purchase_order_id} ↔ case ${p.case_id}`,
                        renderEvidence: (p) => (
                          <Stack spacing={1}>
                            <Typography variant="body2">
                              <strong>Case id:</strong> {p.case_id}
                            </Typography>
                            <Typography variant="body2">
                              <strong>Source file:</strong> {p.file_name ?? p.file_base ?? '—'}
                              {p.version_prefix != null ? ` (prefix ${p.version_prefix})` : ''}
                            </Typography>
                            <Typography variant="body2">
                              <strong>Period:</strong> {p.case_period_label ?? p.inferred_period_start ?? '—'}
                            </Typography>
                            <Typography variant="body2">
                              <strong>Distributor:</strong>{' '}
                              {[p.distributor_code, p.distributor_name].filter(Boolean).join(' — ') || '—'}
                            </Typography>
                            <Typography variant="body2">
                              <strong>Reason:</strong> {reasonLabel(p.reason)}
                            </Typography>
                            {p.competition?.competing_case_ids?.length ? (
                              <Typography variant="body2">
                                <strong>Competing case ids:</strong> {p.competition.competing_case_ids.join(', ')}
                              </Typography>
                            ) : null}
                            {p.matched_products.length > 0 ? (
                              <Box>
                                <Typography variant="subtitle2" gutterBottom>
                                  Matched products ({p.matched_products.length})
                                </Typography>
                                <Stack spacing={0.5}>
                                  {p.matched_products.map((m) => (
                                    <Typography key={m.product_id} variant="body2">
                                      {productDisplayLabel(m)} — planned {fmtUnits(m.planned_units)}, shipped{' '}
                                      {fmtUnits(m.shipped_units)}
                                    </Typography>
                                  ))}
                                </Stack>
                              </Box>
                            ) : null}
                          </Stack>
                        ),
                        renderDispositionActions: (p) => (
                          <Stack direction="row" spacing={1}>
                            <Button
                              size="small"
                              variant="contained"
                              onClick={() => {
                                setApplyError(null);
                                setConfirmProposal(p);
                              }}
                              data-testid={`po-auto-link-drawer-link-${p.proposal_key}`}
                            >
                              Link
                            </Button>
                            <Button size="small" color="warning" onClick={() => setDismissTarget(p)}>
                              Dismiss
                            </Button>
                          </Stack>
                        ),
                      }}
                    />
                  </Box>
                </>
              )}
            </Stack>
          </Collapse>
        </Stack>
      </CardContent>

      <PoAutoLinkConfirmDialog
        open={!!confirmProposal}
        proposal={confirmProposal}
        onClose={() => {
          setConfirmProposal(null);
          setApplyError(null);
        }}
        onConfirm={handleSingleConfirm}
        isPending={applyMut.isPending}
        error={applyError}
      />

      <BulkLinkConfirmDialog
        open={!!bulkConfirmKeys?.length}
        totalCount={bulkConfirmPartition.linkable.length}
        byCustomer={bulkConfirmBreakdown}
        excluded={bulkExcludedRows}
        onClose={() => {
          setBulkConfirmKeys(null);
          setApplyError(null);
        }}
        onConfirm={executeBulkApply}
        isPending={applyMut.isPending}
        progress={applyProgress}
        error={applyError}
      />

      <PoDismissReasonDialog
        open={!!dismissTarget}
        title="Dismiss link proposal"
        description={
          dismissTarget
            ? `PO ${dismissTarget.po_number ?? dismissTarget.purchase_order_id} ↔ case ${dismissTarget.case_id}`
            : undefined
        }
        defaultReason="wrong match"
        isPending={dismissMut.isPending}
        error={dismissMut.isError ? safeDisplayError(dismissMut.error) : null}
        onClose={() => setDismissTarget(null)}
        onConfirm={(reason) => {
          if (!dismissTarget) return;
          dismissMut.mutate({
            proposal_key: dismissTarget.proposal_key,
            case_id: dismissTarget.case_id,
            purchase_order_id: dismissTarget.purchase_order_id,
            reason_code: reason,
          });
        }}
      />
    </Card>
  );
}

/**
 * Active case↔PO link worklist — Unlink disposition on ResolutionWorklist (Unit 6a / BACKLOG-109).
 * PO-shaped verb only (no requiresTarget). Stamp/alias is Unit 6b.
 */
'use client';

import { useMemo, useState, type InputHTMLAttributes } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  Stack,
  TextField,
  Typography,
  Chip,
} from '@mui/material';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { apiGet, apiPost } from '@/lib/api';
import {
  ResolutionWorklist,
  type ResolutionBucket,
  type WorkItemProtection,
} from '@/features/steward-worklist';

export type CasePoLinkItem = {
  link_id: number;
  item_key: string;
  case_id: number;
  case_period_label?: string | null;
  commercial_status?: string | null;
  purchase_order_id: number;
  po_number?: string | null;
  po_number_norm?: string | null;
  notes?: string | null;
  carried_under_d032: boolean;
  row_class: 'active' | 'historical';
  po_link_count: number;
  bulk_protection?: {
    selection_protected: boolean;
    requires_allow_protected: boolean;
    reasons: string[];
    contested: boolean;
  } | null;
};

type CasePoLinksResponse = {
  links: CasePoLinkItem[];
  total: number;
  data_unavailable?: boolean;
};

type UnlinkResponse = {
  unlinked_count: number;
  results: Array<{
    case_id: number;
    purchase_order_id: number;
    before_status?: string;
    after_status?: string;
    before_po_count?: number;
    after_po_count?: number;
    carried_under_d032?: boolean;
  }>;
  reason: string;
};

function toProtection(item: CasePoLinkItem): WorkItemProtection | null {
  const p = item.bulk_protection;
  if (!p) return null;
  if (!p.selection_protected && !p.requires_allow_protected && !p.contested) return null;
  return {
    selectionProtected: !!p.selection_protected,
    requiresOverride: !!p.requires_allow_protected,
    contested: !!p.contested,
    reasonLabels: p.reasons ?? [],
  };
}

export const PO_CASE_LINK_SECTION_ID = 'po-case-link-section';

export function PoCaseLinkWorklistSection() {
  const qc = useQueryClient();
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const [unlinkTarget, setUnlinkTarget] = useState<CasePoLinkItem | null>(null);
  const [bulkKeys, setBulkKeys] = useState<string[] | null>(null);
  const [reason, setReason] = useState('wrong link');
  const [allowProtected, setAllowProtected] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  const linksQ = useQuery({
    queryKey: ['case-po-links'],
    queryFn: ({ signal }) =>
      apiGet<CasePoLinksResponse>('/api/v1/commercial-planner/lineup/case-po-links?limit=500', {
        signal,
      }),
  });

  const links = linksQ.data?.links ?? [];
  const byKey = useMemo(() => {
    const m = new Map<string, CasePoLinkItem>();
    for (const l of links) m.set(l.item_key, l);
    return m;
  }, [links]);

  const unlinkMut = useMutation({
    mutationFn: (vars: {
      items: Array<{ case_id: number; purchase_order_id: number; allow_protected?: boolean }>;
      reason: string;
      allow_protected?: boolean;
    }) => apiPost<UnlinkResponse>('/api/v1/commercial-planner/lineup/case-po-links/unlink', vars),
    onSuccess: (data) => {
      const lines = data.results.map(
        (r) =>
          `case ${r.case_id}↔PO ${r.purchase_order_id}: ${r.before_po_count}→${r.after_po_count} links, status ${r.before_status}→${r.after_status}`,
      );
      setSuccess(`Unlinked ${data.unlinked_count}: ${lines.join('; ')}`);
      setError(null);
      setUnlinkTarget(null);
      setBulkKeys(null);
      setAllowProtected(false);
      setSelected(new Set());
      void qc.invalidateQueries({ queryKey: ['case-po-links'] });
      void qc.invalidateQueries({ queryKey: ['po-auto-link'] });
      void qc.invalidateQueries({ queryKey: ['po-management'] });
    },
    onError: (err: unknown) => {
      const msg =
        err && typeof err === 'object' && 'message' in err
          ? String((err as { message?: string }).message)
          : String(err);
      setError(msg);
    },
  });

  const buckets: ResolutionBucket<'all' | 'protected' | 'carried'>[] = [
    { id: 'all', label: 'All active', count: links.length },
    {
      id: 'protected',
      label: 'Protected',
      count: links.filter((l) => l.bulk_protection?.requires_allow_protected).length,
    },
    {
      id: 'carried',
      label: 'D-032 carried',
      count: links.filter((l) => l.carried_under_d032).length,
    },
  ];
  const [bucket, setBucket] = useState<'all' | 'protected' | 'carried'>('all');
  const filtered = links.filter((l) => {
    if (bucket === 'protected') return !!l.bulk_protection?.requires_allow_protected;
    if (bucket === 'carried') return l.carried_under_d032;
    return true;
  });

  const openUnlink = (item: CasePoLinkItem) => {
    setUnlinkTarget(item);
    setReason('wrong link');
    setAllowProtected(false);
    setError(null);
  };

  const confirmUnlink = () => {
    if (unlinkTarget) {
      unlinkMut.mutate({
        items: [
          {
            case_id: unlinkTarget.case_id,
            purchase_order_id: unlinkTarget.purchase_order_id,
            allow_protected: allowProtected,
          },
        ],
        reason,
        allow_protected: allowProtected,
      });
      return;
    }
    if (bulkKeys?.length) {
      const items = bulkKeys
        .map((k) => byKey.get(k))
        .filter((x): x is CasePoLinkItem => !!x)
        .filter((x) => !x.bulk_protection?.requires_allow_protected)
        .map((x) => ({
          case_id: x.case_id,
          purchase_order_id: x.purchase_order_id,
          allow_protected: false,
        }));
      if (!items.length) {
        setError('No unprotected links in selection — protected cases must be unlinked individually.');
        return;
      }
      unlinkMut.mutate({ items, reason, allow_protected: false });
    }
  };

  const activeItem = activeKey ? byKey.get(activeKey) ?? null : null;

  return (
    <Card variant="outlined" id={PO_CASE_LINK_SECTION_ID} data-testid="po-case-link-section" sx={{ mb: 2 }}>
      <CardContent>
        <Stack spacing={1.5}>
          <Typography variant="h6">Linked case ↔ PO (unlink)</Typography>
          <Typography variant="body2" color="text.secondary">
            Remove an active link only. Historical links on superseded cases are refused. Protected cases
            require individual confirm with allow_protected.
          </Typography>
          {linksQ.isLoading ? (
            <Typography variant="body2" color="text.secondary">
              Loading links…
            </Typography>
          ) : linksQ.data?.data_unavailable ? (
            <Alert severity="info">Link list unavailable.</Alert>
          ) : !filtered.length ? (
            <Alert severity="info" data-testid="po-case-link-empty">
              No active case↔PO links.
            </Alert>
          ) : (
            <ResolutionWorklist<CasePoLinkItem, 'all' | 'protected' | 'carried'>
              rootTestId="po-case-link"
              getCheckboxTestId={(k) => `po-case-link-select-${k}`}
              items={filtered}
              getItemKey={(i) => i.item_key}
              getProtection={toProtection}
              buckets={buckets}
              activeBucket={bucket}
              onBucketChange={setBucket}
              selection={{
                selected,
                onToggle: (k) =>
                  setSelected((prev) => {
                    const next = new Set(prev);
                    if (next.has(k)) next.delete(k);
                    else next.add(k);
                    return next;
                  }),
                onReplace: (ks) => setSelected(new Set(ks)),
              }}
              actions={[
                {
                  id: 'unlink',
                  label: 'Unlink',
                  allowBulk: true,
                  requiresTarget: false,
                  onRun: ({ items }) => {
                    if (items.length === 1) openUnlink(items[0]);
                    else {
                      setBulkKeys(items.map((i) => i.item_key));
                      setReason('wrong link');
                      setAllowProtected(false);
                    }
                  },
                },
              ]}
              bulkActions={[
                {
                  id: 'unlink-bulk',
                  label: 'Unlink selected',
                  allowBulk: true,
                  requiresTarget: false,
                  onRun: ({ items }) => {
                    setBulkKeys(items.map((i) => i.item_key));
                    setReason('wrong link');
                    setAllowProtected(false);
                  },
                },
              ]}
              renderRow={(item, api) => (
                <Stack
                  direction="row"
                  spacing={1}
                  alignItems="center"
                  onClick={() => setActiveKey(item.item_key)}
                  sx={{ cursor: 'pointer', opacity: api.selected ? 1 : 0.95 }}
                >
                  <Typography variant="body2" sx={{ minWidth: 120 }}>
                    Case {item.case_id}
                  </Typography>
                  <Chip size="small" label={item.po_number ?? item.purchase_order_id} />
                  <Chip size="small" variant="outlined" label={item.commercial_status ?? '—'} />
                  {item.carried_under_d032 ? (
                    <Chip size="small" color="info" label="D-032 carried" data-testid={`po-case-link-carried-${item.item_key}`} />
                  ) : null}
                  {item.bulk_protection?.requires_allow_protected ? (
                    <Chip size="small" color="warning" label="Protected" data-testid={`po-case-link-protected-${item.item_key}`} />
                  ) : null}
                  <Box sx={{ flex: 1 }} />
                  <Button
                    size="small"
                    color="warning"
                    data-testid={`po-case-link-unlink-${item.item_key}`}
                    onClick={(e) => {
                      e.stopPropagation();
                      openUnlink(item);
                    }}
                  >
                    Unlink
                  </Button>
                </Stack>
              )}
              renderToolbar={() => (
                <Stack direction="row" spacing={1}>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={!selected.size || unlinkMut.isPending}
                    data-testid="po-case-link-bulk-unlink"
                    onClick={() => setBulkKeys([...selected])}
                  >
                    Unlink selected ({selected.size})
                  </Button>
                </Stack>
              )}
              drawer={{
                activeKey,
                onClose: () => setActiveKey(null),
                title: (item) => `Case ${item.case_id} ↔ ${item.po_number ?? item.purchase_order_id}`,
                renderEvidence: (item) => (
                  <Stack spacing={1}>
                    <Typography variant="body2">Status: {item.commercial_status}</Typography>
                    <Typography variant="body2">PO links on case: {item.po_link_count}</Typography>
                    <Typography variant="body2">
                      Carried under D-032: {item.carried_under_d032 ? 'yes' : 'no'}
                    </Typography>
                    {item.notes ? (
                      <Typography variant="body2" color="text.secondary">
                        Notes: {item.notes}
                      </Typography>
                    ) : null}
                  </Stack>
                ),
                renderDispositionActions: (item) => (
                  <Button
                    size="small"
                    color="warning"
                    variant="contained"
                    data-testid={`po-case-link-drawer-unlink-${item.item_key}`}
                    onClick={() => openUnlink(item)}
                  >
                    Unlink
                  </Button>
                ),
              }}
            />
          )}
          {success ? (
            <Alert severity="success" data-testid="po-case-link-success" onClose={() => setSuccess(null)}>
              {success}
            </Alert>
          ) : null}
          {error ? (
            <Alert severity="error" data-testid="po-case-link-error" onClose={() => setError(null)}>
              {error}
            </Alert>
          ) : null}
        </Stack>
      </CardContent>

      <Dialog
        open={!!unlinkTarget || !!bulkKeys}
        onClose={() => {
          setUnlinkTarget(null);
          setBulkKeys(null);
        }}
        data-testid="po-case-link-unlink-dialog"
      >
        <DialogTitle>
          {unlinkTarget
            ? `Unlink case ${unlinkTarget.case_id} ↔ ${unlinkTarget.po_number ?? unlinkTarget.purchase_order_id}`
            : `Unlink ${bulkKeys?.length ?? 0} selected links`}
        </DialogTitle>
        <DialogContent>
          <Stack spacing={1.5} sx={{ mt: 1 }}>
            <Typography variant="body2">
              Removes the active link row. Historical (superseded-case) links are refused. Does not delete the
              purchase order or shipment facts.
            </Typography>
            {unlinkTarget ? (
              <Typography variant="body2" data-testid="po-case-link-unlink-before">
                Before: {unlinkTarget.po_link_count} link(s) on case · status {unlinkTarget.commercial_status}
                {unlinkTarget.carried_under_d032 ? ' · originally carried under D-032' : ''}
              </Typography>
            ) : null}
            <TextField
              label="Reason"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              fullWidth
              size="small"
              inputProps={{ 'data-testid': 'po-case-link-unlink-reason' }}
            />
            {unlinkTarget?.bulk_protection?.requires_allow_protected ? (
              <FormControlLabel
                control={
                  <Checkbox
                    checked={allowProtected}
                    onChange={(e) => setAllowProtected(e.target.checked)}
                    inputProps={{ 'data-testid': 'po-case-link-allow-protected' } as InputHTMLAttributes<HTMLInputElement>}
                  />
                }
                label="Allow protected case (individual override)"
              />
            ) : null}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={() => {
              setUnlinkTarget(null);
              setBulkKeys(null);
            }}
          >
            Cancel
          </Button>
          <Button
            color="warning"
            variant="contained"
            disabled={!reason.trim() || unlinkMut.isPending}
            data-testid="po-case-link-unlink-submit"
            onClick={confirmUnlink}
          >
            {unlinkMut.isPending ? 'Unlinking…' : 'Confirm unlink'}
          </Button>
        </DialogActions>
      </Dialog>
    </Card>
  );
}

'use client';

import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Divider,
  LinearProgress,
  Stack,
  Tooltip,
  Typography,
} from '@mui/material';
import type { ColDef, GridOptions, ICellRendererParams } from 'ag-grid-community';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import Link from 'next/link';
import { useEffect, useMemo, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

import { EnterpriseDataGrid } from '@/components/EnterpriseDataGrid';
import { OPS_LIST_GRID_PAGINATION } from '@/features/shell/opsListGridPagination';
import { apiGet, apiPost, safeDisplayError } from '@/lib/api';

import { PoAutoLinkProposalsSection, PO_AUTO_LINK_SECTION_ID } from './PoAutoLinkProposalsSection';
import { PoCaseLinkWorklistSection } from './PoCaseLinkWorklistSection';
import { CustomerTokenWorklistSection } from './CustomerTokenWorklistSection';
import { DistributorAttributionReviewSection } from './DistributorAttributionReviewSection';
import { LineupDuplicatePartitionPanel } from './LineupDuplicatePartitionPanel';
import { PoDismissReasonDialog } from './PoDismissReasonDialog';
import { buildPlanVsExecutedHref } from '@/features/plan-vs-executed/productDisplay';

type BacklogGroup = {
  year: number;
  quarter: number;
  quarter_label: string;
  product_line: string;
  shipped_units: number;
  shipped_value_cost: number;
  shipped_value_plan: number;
  fx_complete: boolean;
  po_count: number;
  linked_po_count: number;
  status: 'linked' | 'unlinked';
  linked_case_ids?: number[];
  lineup_case_exists?: boolean;
  parse_incomplete?: boolean;
  upload_prompt?: { period_label: string | null; product_line: string };
};

type BacklogResponse = { groups: BacklogGroup[]; data_unavailable?: boolean };

type CoverageResponse = {
  total_pos_observed: number;
  total_pos_linked: number;
  first_run: boolean;
  data_unavailable?: boolean;
};

type GapRow = {
  purchase_order_id: number;
  po_number_raw: string | null;
  product_id: number;
  product_name: string | null;
  product_line: string | null;
  shipped_units: number;
  period_label: string;
  dismissed: boolean;
  quarter_label?: string;
  row_key?: string;
};

type GapGroup = {
  year: number;
  quarter: number;
  quarter_label: string;
  rows: GapRow[];
  shipped_units: number;
  po_count: number;
  product_count: number;
};

type GapResponse = {
  groups: GapGroup[];
  dismissed: { purchase_order_id: number; po_number_raw: string | null; dismiss_reason_code: string | null }[];
  total_gap_rows: number;
  data_unavailable?: boolean;
};

function fmtUnits(n: number | null | undefined): string {
  if (n == null) return '—';
  return new Intl.NumberFormat().format(Math.round(n));
}

function fmtValue(n: number | null | undefined): string {
  if (n == null) return '—';
  return new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(n);
}

function poGroupDomId(g: Pick<BacklogGroup, 'year' | 'quarter' | 'product_line'>): string {
  return `po-mgmt-group-${g.year}-${g.quarter}-${g.product_line}`;
}

export const PO_BACKLOG_SECTION_ID = 'po-mgmt-backlog';
export const PO_GAP_SECTION_ID = 'po-mgmt-gap';

function needsLineupUpload(g: BacklogGroup): boolean {
  return g.status === 'unlinked' && !g.lineup_case_exists && !g.parse_incomplete;
}

export function PoManagementView() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const qc = useQueryClient();
  const [showDismissed, setShowDismissed] = useState(false);
  const [dismissTarget, setDismissTarget] = useState<GapRow | null>(null);
  const [pendingLinkProposals, setPendingLinkProposals] = useState(0);
  const [highlightGroupId, setHighlightGroupId] = useState<string | null>(null);
  const [highlightCustomerId, setHighlightCustomerId] = useState<number | null>(null);

  const deepLinkPeriod = searchParams.get('period');
  const deepLinkBU = searchParams.get('business_unit');
  const deepLinkCustomerRaw = searchParams.get('customer_id');
  const deepLinkCustomerId = deepLinkCustomerRaw ? Number.parseInt(deepLinkCustomerRaw, 10) : null;

  const scrollToAutoLink = () => {
    document.getElementById(PO_AUTO_LINK_SECTION_ID)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const coverageQ = useQuery({
    queryKey: ['po-management', 'coverage'],
    queryFn: ({ signal }) => apiGet<CoverageResponse>('/api/v1/po-management/coverage', { signal }),
  });
  const backlogQ = useQuery({
    queryKey: ['po-management', 'backlog'],
    queryFn: ({ signal }) => apiGet<BacklogResponse>('/api/v1/po-management/backlog', { signal }),
  });

  useEffect(() => {
    if (!deepLinkPeriod || backlogQ.data?.data_unavailable || !backlogQ.data?.groups?.length) return;
    const match = backlogQ.data.groups.find(
      (g) =>
        g.quarter_label === deepLinkPeriod && (!deepLinkBU || g.product_line === deepLinkBU),
    );
    if (!match) return;
    const groupId = poGroupDomId(match);
    setHighlightGroupId(groupId);
    if (deepLinkCustomerId != null && !Number.isNaN(deepLinkCustomerId)) {
      setHighlightCustomerId(deepLinkCustomerId);
    }
    const timer = window.setTimeout(() => {
      document.getElementById(groupId)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 150);
    return () => window.clearTimeout(timer);
  }, [backlogQ.data, deepLinkPeriod, deepLinkBU, deepLinkCustomerId]);
  const gapQ = useQuery({
    queryKey: ['po-management', 'gap', showDismissed],
    queryFn: ({ signal }) =>
      apiGet<GapResponse>(
        `/api/v1/commercial-planner/lineup/po-gap-worklist?include_dismissed=${showDismissed ? 'true' : 'false'}`,
        { signal }
      ),
  });

  const dismissMut = useMutation({
    mutationFn: (vars: { purchase_order_id: number; reason_code: string }) =>
      apiPost('/api/v1/commercial-planner/lineup/po-gap-worklist/dismiss', vars),
    onSuccess: () => {
      setDismissTarget(null);
      void qc.invalidateQueries({ queryKey: ['po-management', 'gap'] });
    },
  });
  const restoreMut = useMutation({
    mutationFn: (purchaseOrderId: number) =>
      apiPost(
        `/api/v1/commercial-planner/lineup/po-gap-worklist/restore?purchase_order_id=${purchaseOrderId}`,
        undefined
      ),
    onSuccess: () => {
      void qc.invalidateQueries({ queryKey: ['po-management', 'gap'] });
    },
  });

  const startUpload = (periodLabel: string | null) => {
    const params = new URLSearchParams({ unified: '1' });
    if (periodLabel) params.set('period', periodLabel);
    router.push(`/admin/imports?${params.toString()}`);
  };

  const viewShipmentsForPo = (poId: number, label: string | null) => {
    const params = new URLSearchParams({ purchase_order_id: String(poId) });
    if (label) params.set('po_label', label);
    router.push(`/supply/shipments?${params.toString()}`);
  };

  const coverage = coverageQ.data;
  const backlog = backlogQ.data;
  const gap = gapQ.data;
  const loading = coverageQ.isLoading || backlogQ.isLoading;

  const gapRows = useMemo<GapRow[]>(() => {
    if (!gap?.groups.length) return [];
    return gap.groups.flatMap((g) =>
      g.rows.map((r) => ({
        ...r,
        quarter_label: g.quarter_label,
        row_key: `${g.year}-${g.quarter}-${r.purchase_order_id}-${r.product_id}`,
      }))
    );
  }, [gap]);

  const worklistSummary = useMemo(() => {
    const observed = coverage?.total_pos_observed ?? 0;
    const linked = coverage?.total_pos_linked ?? 0;
    const unlinkedPos = Math.max(observed - linked, 0);
    const uploadNeeded =
      backlog?.groups.filter((g) => g.po_count > 0 && needsLineupUpload(g)).length ?? 0;
    const gapCount = gap?.total_gap_rows ?? 0;
    return { unlinkedPos, uploadNeeded, gapCount };
  }, [coverage, backlog, gap]);

  const scrollToSection = (id: string) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const gapColumnDefs = useMemo<ColDef<GapRow>[]>(
    () => [
      { headerName: 'Period', field: 'quarter_label', width: 90 },
      {
        headerName: 'PO',
        width: 130,
        cellRenderer: (p: ICellRendererParams<GapRow>) => {
          const row = p.data;
          if (!row) return null;
          return (
            <Button
              size="small"
              variant="text"
              onClick={() => viewShipmentsForPo(row.purchase_order_id, row.po_number_raw)}
            >
              {row.po_number_raw ?? `#${row.purchase_order_id}`}
            </Button>
          );
        },
      },
      {
        headerName: 'Product',
        flex: 1,
        minWidth: 140,
        valueGetter: (p) => p.data?.product_name ?? (p.data ? `#${p.data.product_id}` : ''),
      },
      { headerName: 'Line', field: 'product_line', width: 120 },
      {
        headerName: 'Units',
        width: 100,
        type: 'numericColumn',
        field: 'shipped_units',
        valueFormatter: (p) => fmtUnits(p.value as number),
      },
      {
        headerName: 'Actions',
        colId: 'actions',
        width: 110,
        pinned: 'right',
        sortable: false,
        filter: false,
        cellRenderer: (p: ICellRendererParams<GapRow>) => {
          const row = p.data;
          if (!row) return null;
          if (row.dismissed) {
            return (
              <Button
                size="small"
                onClick={() => restoreMut.mutate(row.purchase_order_id)}
                disabled={restoreMut.isPending}
                data-testid={`gap-restore-${row.purchase_order_id}`}
              >
                Restore
              </Button>
            );
          }
          return (
            <Button
              size="small"
              color="warning"
              onClick={() => setDismissTarget(row)}
              disabled={dismissMut.isPending}
              data-testid={`gap-dismiss-${row.purchase_order_id}`}
            >
              Dismiss
            </Button>
          );
        },
      },
    ],
    [dismissMut.isPending, restoreMut]
  );

  const gapGridOptions = useMemo<GridOptions<GapRow>>(
    () => ({
      getRowId: (p) => p.data.row_key ?? `${p.data.purchase_order_id}-${p.data.product_id}`,
      ...OPS_LIST_GRID_PAGINATION,
    }),
    []
  );

  return (
    <Stack spacing={3}>
      <LineupDuplicatePartitionPanel />
      <Card variant="outlined">
        <CardContent>
          <Typography variant="h6" gutterBottom>
            PO coverage
          </Typography>
          {loading ? (
            <LinearProgress data-testid="po-coverage-loading" />
          ) : coverage?.data_unavailable ? (
            <Alert severity="info">
              PO coverage is unavailable — no shipment evidence with purchase orders has been imported yet.
            </Alert>
          ) : (
            <Stack direction="row" spacing={2} alignItems="center" flexWrap="wrap" useFlexGap>
              <Chip
                color="primary"
                label={`${coverage?.total_pos_observed ?? 0} POs observed`}
                data-testid="po-coverage-observed"
              />
              <Chip
                color={coverage?.total_pos_linked ? 'success' : 'default'}
                variant={coverage?.total_pos_linked ? 'filled' : 'outlined'}
                label={`${coverage?.total_pos_linked ?? 0} linked to a lineup`}
                data-testid="po-coverage-linked"
              />
              {pendingLinkProposals > 0 ? (
                <Chip
                  clickable
                  color="warning"
                  variant="filled"
                  onClick={scrollToAutoLink}
                  label={`${pendingLinkProposals} CRAD link suggestion${pendingLinkProposals === 1 ? '' : 's'}`}
                  data-testid="po-coverage-pending-links"
                />
              ) : null}
              {coverage?.first_run ? (
                <Alert severity="warning" sx={{ flex: 1, minWidth: 280 }}>
                  First run — no confirmed lineups link to any observed PO yet. Upload a lineup for a period below to
                  start reconciling.
                </Alert>
              ) : null}
            </Stack>
          )}
        </CardContent>
      </Card>

      {!loading && !coverage?.data_unavailable ? (
        <Card variant="outlined" data-testid="po-worklist-summary">
          <CardContent>
            <Typography variant="subtitle1" fontWeight={600} gutterBottom>
              What needs action
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap alignItems="center">
              <Chip
                clickable={worklistSummary.unlinkedPos > 0}
                onClick={() => scrollToSection(PO_BACKLOG_SECTION_ID)}
                label={`${worklistSummary.unlinkedPos} PO${worklistSummary.unlinkedPos === 1 ? '' : 's'} unlinked`}
                color={worklistSummary.unlinkedPos > 0 ? 'warning' : 'default'}
                variant={worklistSummary.unlinkedPos > 0 ? 'filled' : 'outlined'}
                data-testid="po-worklist-unlinked"
              />
              <Chip
                clickable={worklistSummary.uploadNeeded > 0}
                onClick={() => scrollToSection(PO_BACKLOG_SECTION_ID)}
                label={`${worklistSummary.uploadNeeded} period×BU need lineup upload`}
                color={worklistSummary.uploadNeeded > 0 ? 'error' : 'default'}
                variant={worklistSummary.uploadNeeded > 0 ? 'filled' : 'outlined'}
                data-testid="po-worklist-upload-needed"
              />
              <Chip
                clickable={worklistSummary.gapCount > 0}
                onClick={() => scrollToSection(PO_GAP_SECTION_ID)}
                label={`${worklistSummary.gapCount.toLocaleString()} gap line${worklistSummary.gapCount === 1 ? '' : 's'}`}
                color={worklistSummary.gapCount > 0 ? 'warning' : 'default'}
                variant={worklistSummary.gapCount > 0 ? 'filled' : 'outlined'}
                data-testid="po-worklist-gaps"
              />
              <Typography variant="caption" color="text.secondary">
                Reconciliation outcomes live on Execution vs plan — this page is the operational worklist only.
              </Typography>
            </Stack>
          </CardContent>
        </Card>
      ) : null}

      <PoCaseLinkWorklistSection />

      <CustomerTokenWorklistSection />

      <DistributorAttributionReviewSection />

      <PoAutoLinkProposalsSection autoFetch onPendingCountChange={setPendingLinkProposals} />

      <Box id={PO_BACKLOG_SECTION_ID}>
        <Typography variant="h6" gutterBottom>
          Observed purchase orders by period & product line
        </Typography>
        {backlogQ.isLoading ? (
          <LinearProgress />
        ) : backlog?.data_unavailable ? (
          <Alert severity="info">No observed purchase orders to report.</Alert>
        ) : !backlog?.groups.length ? (
          <Alert severity="info">No purchase orders observed in shipment history yet.</Alert>
        ) : (
          <Stack spacing={1.5}>
            {backlog.groups.map((g) => (
              <Card
                key={`${g.year}-${g.quarter}-${g.product_line}`}
                id={poGroupDomId(g)}
                variant="outlined"
                sx={
                  highlightGroupId === poGroupDomId(g)
                    ? { borderColor: 'warning.main', borderWidth: 2, boxShadow: 2 }
                    : undefined
                }
              >
                <CardContent>
                  <Stack
                    direction={{ xs: 'column', sm: 'row' }}
                    spacing={1}
                    alignItems={{ sm: 'center' }}
                    justifyContent="space-between"
                  >
                    <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
                      <Chip size="small" label={g.quarter_label} color="default" />
                      <Typography variant="subtitle1" fontWeight={600}>
                        {g.product_line}
                      </Typography>
                      <Chip
                        size="small"
                        variant="outlined"
                        label={g.status === 'linked' ? `${g.linked_po_count}/${g.po_count} POs linked` : `${g.po_count} POs`}
                        color={g.status === 'linked' ? 'success' : 'default'}
                      />
                    </Stack>
                    {g.status !== 'linked' ? (
                      <Stack direction="row" spacing={2} alignItems="center">
                        <Typography variant="body2" color="text.secondary">
                          {fmtUnits(g.shipped_units)} units observed
                        </Typography>
                        <Tooltip
                          title={
                            g.fx_complete
                              ? 'Shipped value bridged to plan currency'
                              : 'FX unavailable for some SKUs — value is best-effort'
                          }
                        >
                          <Typography variant="body2" color="text.secondary">
                            {fmtValue(g.fx_complete ? g.shipped_value_plan : g.shipped_value_cost)}
                            {g.fx_complete ? ' (plan)' : ' (cost · FX partial)'}
                          </Typography>
                        </Tooltip>
                      </Stack>
                    ) : null}
                  </Stack>

                  <Divider sx={{ my: 1.5 }} />

                  {g.status === 'linked' ? (
                    <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} flexWrap="wrap" useFlexGap>
                      <Typography variant="body2" color="text.secondary" data-testid={`po-linked-status-${g.year}-${g.quarter}-${g.product_line}`}>
                        Linked {g.linked_po_count}/{g.po_count} POs — operational linking complete for this group.
                      </Typography>
                      <Button
                        component={Link}
                        href={buildPlanVsExecutedHref({
                          periodFrom: g.quarter_label,
                          periodTo: g.quarter_label,
                          productLine: g.product_line,
                        })}
                        variant="contained"
                        size="small"
                        color="primary"
                        data-testid={`po-pve-link-${g.year}-${g.quarter}-${g.product_line}`}
                      >
                        Execution vs plan outcomes
                      </Button>
                      {highlightCustomerId != null && highlightGroupId === poGroupDomId(g) ? (
                        <Typography variant="caption" color="warning.main">
                          Highlighted customer #{highlightCustomerId} — link or upload work above; reconciliation
                          outcomes are on Execution vs plan.
                        </Typography>
                      ) : null}
                    </Stack>
                  ) : g.lineup_case_exists ? (
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Chip size="small" color="info" label="Lineup on file" />
                      <Typography variant="caption" color="text.secondary">
                        A lineup case exists for {g.quarter_label} {g.product_line} — link POs via suggested
                        auto-links above.
                      </Typography>
                    </Stack>
                  ) : g.parse_incomplete ? (
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Chip size="small" color="warning" label="Parse incomplete" />
                      <Typography variant="caption" color="text.secondary">
                        Lineup file uploaded for {g.quarter_label} {g.product_line} but lines were not parsed —
                        re-run parse from Import Center.
                      </Typography>
                    </Stack>
                  ) : (
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Button
                        size="small"
                        variant="contained"
                        onClick={() => startUpload(g.upload_prompt?.period_label ?? g.quarter_label)}
                        data-testid={`po-upload-${g.year}-${g.quarter}-${g.product_line}`}
                      >
                        Upload lineup for this period
                      </Button>
                      <Typography variant="caption" color="text.secondary">
                        Pre-fills the unified lineup importer with period {g.quarter_label}.
                      </Typography>
                    </Stack>
                  )}
                </CardContent>
              </Card>
            ))}
          </Stack>
        )}
      </Box>

      <Box id={PO_GAP_SECTION_ID}>
        <Stack direction="row" spacing={1} alignItems="center" justifyContent="space-between" sx={{ mb: 1 }}>
          <Typography variant="h6">POs with shipments but no covering lineup</Typography>
          <Button size="small" onClick={() => setShowDismissed((v) => !v)} data-testid="toggle-dismissed">
            {showDismissed ? 'Hide dismissed' : 'Show dismissed'}
          </Button>
        </Stack>
        {dismissMut.isError ? <Alert severity="error">{safeDisplayError(dismissMut.error)}</Alert> : null}
        {gapQ.isLoading ? (
          <LinearProgress />
        ) : gap?.data_unavailable ? (
          <Alert severity="info">Gap worklist is unavailable.</Alert>
        ) : !gap?.groups.length ? (
          <Alert severity="success">No gaps — every shipment PO is covered by a confirmed lineup.</Alert>
        ) : (
          <Stack spacing={1.5}>
            <Stack direction="row" spacing={1} alignItems="center" justifyContent="space-between">
              <Typography variant="body2" color="text.secondary">
                {gap.total_gap_rows} gap row{gap.total_gap_rows === 1 ? '' : 's'} across {gap.groups.length} period
                {gap.groups.length === 1 ? '' : 's'}
              </Typography>
              <Button
                size="small"
                variant="outlined"
                onClick={() => startUpload(gap.groups[0]?.quarter_label ?? null)}
                data-testid="gap-upload-top"
              >
                Upload lineup
              </Button>
            </Stack>
            <Box data-testid="po-gap-grid">
              <EnterpriseDataGrid
                rowData={gapRows}
                columnDefs={gapColumnDefs}
                gridOptions={gapGridOptions}
                height={480}
              />
            </Box>
          </Stack>
        )}
      </Box>

      <PoDismissReasonDialog
        open={!!dismissTarget}
        title="Dismiss gap PO"
        description={
          dismissTarget
            ? `PO ${dismissTarget.po_number_raw ?? `#${dismissTarget.purchase_order_id}`} has no covering lineup.`
            : undefined
        }
        defaultReason="no lineup needed"
        isPending={dismissMut.isPending}
        error={dismissMut.isError ? safeDisplayError(dismissMut.error) : null}
        onClose={() => setDismissTarget(null)}
        onConfirm={(reason) => {
          if (!dismissTarget) return;
          dismissMut.mutate({ purchase_order_id: dismissTarget.purchase_order_id, reason_code: reason });
        }}
      />
    </Stack>
  );
}

'use client';

import type { BulkTableSelectionMode } from '@/components/bulkTable/BulkSelectionToolbar';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useCallback, useMemo, useState } from 'react';

import { apiPost } from '@/lib/api';

import { registerClientBackgroundTask, finishClientBackgroundTask } from '@/features/background-tasks/backgroundTaskRegistry';

import type {
  StewardBulkApplyResponse,
  StewardBulkAsyncEnqueueResponse,
  StewardBulkEngineConfig,
  StewardBulkPreviewResponse,
  StewardEngineCandidateRow,
} from './stewardEngine.types';

export function useStewardBulkSteward({
  importJobId,
  selectedIds,
  setSelectedIds,
  setBulkMode,
  onInvalidate,
  onBulkClosed,
  onApplyPlanFallback,
  applySuggestedRegion,
  onPlanRefresh,
  onEvictResolvedCandidates,
  onShrinkPlanScope,
  getBulkBodyExtras,
  validateBulkForm,
  config,
}: {
  importJobId: number;
  selectedIds: number[];
  setSelectedIds: (ids: number[] | ((prev: number[]) => number[])) => void;
  setBulkMode: (mode: BulkTableSelectionMode) => void;
  onInvalidate: () => void;
  onBulkClosed?: () => void;
  onApplyPlanFallback?: (args: {
    action: 'set_plan_fallback_region' | 'set_plan_fallback_channel';
    regionId: string;
    channelId: string;
  }) => Promise<void>;
  applySuggestedRegion?: (args: { candidateIds: number[] }) => Promise<void>;
  onPlanRefresh?: () => void | Promise<unknown>;
  onEvictResolvedCandidates?: (candidateIds: number[]) => void;
  onShrinkPlanScope?: (candidateIds: number[]) => void;
  /** Consumer composition seam (e.g. shipment per-candidate display_names). */
  getBulkBodyExtras?: (action: string) => Record<string, unknown>;
  /** When set, replaces default ready check for create_provisional_customer (and may gate other actions). */
  validateBulkForm?: () => boolean;
  config: StewardBulkEngineConfig;
}) {
  const qc = useQueryClient();

  const [bulkAction, setBulkAction] = useState<string>('ignore');
  const [bulkNotes, setBulkNotes] = useState('');
  const [bulkCustomerId, setBulkCustomerId] = useState('');
  const [bulkDistributorId, setBulkDistributorId] = useState('');
  const [bulkProductId, setBulkProductId] = useState('');
  const [bulkRawToken, setBulkRawToken] = useState('');
  const [bulkConfirmIneligible, setBulkConfirmIneligible] = useState(false);
  const [bulkAuditNote, setBulkAuditNote] = useState('');
  const [bulkRegionId, setBulkRegionId] = useState('');
  const [bulkChannelId, setBulkChannelId] = useState('');
  const [bulkPreferredDistributorId, setBulkPreferredDistributorId] = useState('');
  const [bulkPartnerTier, setBulkPartnerTier] = useState('unmanaged');
  const [bulkProvisionalNotes, setBulkProvisionalNotes] = useState('');
  const [bulkDistSuspiciousOk, setBulkDistSuspiciousOk] = useState(false);
  const [bulkProvisionalDistCode, setBulkProvisionalDistCode] = useState('');
  const [bulkApplySummary, setBulkApplySummary] = useState<string | null>(null);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [previewData, setPreviewData] = useState<StewardBulkPreviewResponse | null>(null);
  const [previewApplyToken, setPreviewApplyToken] = useState<string | null>(null);

  const buildBulkBody = useCallback(() => {
    const ids = [...selectedIds];
    const base: Record<string, unknown> = {
      action: bulkAction,
      candidate_ids: ids,
    };
    if (bulkAction === 'ignore') {
      base.notes = bulkNotes.trim() || null;
    }
    if (bulkAction === 'map_customer') {
      base.customer_id = Number(bulkCustomerId);
      base.raw_token = bulkRawToken.trim() || null;
    }
    if (bulkAction === 'map_distributor') {
      base.distributor_id = Number(bulkDistributorId);
      base.raw_token = bulkRawToken.trim() || null;
    }
    if (bulkAction === 'resolve_product') {
      base.product_id = Number(bulkProductId);
      base.raw_token = bulkRawToken.trim() || null;
      base.confirm_ineligible_product = bulkConfirmIneligible;
      base.audit_note = bulkAuditNote.trim() || null;
    }
    if (bulkAction === 'create_provisional_customer') {
      const r = bulkRegionId.trim();
      const c = bulkChannelId.trim();
      base.region_id = r !== '' && Number.isFinite(Number(r)) ? Number(r) : null;
      base.channel_id = c !== '' && Number.isFinite(Number(c)) ? Number(c) : null;
      base.partner_tier = bulkPartnerTier.trim() || 'unmanaged';
      base.provisional_notes_summary = bulkProvisionalNotes.trim() || null;
      const pd = bulkPreferredDistributorId.trim();
      base.preferred_distributor_id = pd !== '' && Number.isFinite(Number(pd)) ? Number(pd) : null;
    }
    if (bulkAction === 'create_provisional_distributor') {
      base.confirm_for_suspicious_distributor_token = bulkDistSuspiciousOk;
      base.provisional_distributor_code = bulkProvisionalDistCode.trim() || null;
    }
    if (getBulkBodyExtras) {
      Object.assign(base, getBulkBodyExtras(bulkAction));
    }
    return base;
  }, [
    selectedIds,
    bulkAction,
    bulkNotes,
    bulkCustomerId,
    bulkDistributorId,
    bulkProductId,
    bulkRawToken,
    bulkConfirmIneligible,
    bulkAuditNote,
    bulkRegionId,
    bulkChannelId,
    bulkPreferredDistributorId,
    bulkPartnerTier,
    bulkProvisionalNotes,
    bulkDistSuspiciousOk,
    bulkProvisionalDistCode,
    getBulkBodyExtras,
  ]);

  const previewToken = useMemo(() => JSON.stringify(buildBulkBody()), [buildBulkBody]);

  const bulkFormReady = useMemo(() => {
    if (bulkAction === 'ignore') return true;
    if (bulkAction === 'map_customer') {
      return bulkCustomerId.trim() !== '' && Number.isFinite(Number(bulkCustomerId));
    }
    if (bulkAction === 'map_distributor') {
      return bulkDistributorId.trim() !== '' && Number.isFinite(Number(bulkDistributorId));
    }
    if (bulkAction === 'resolve_product') {
      const pid = bulkProductId.trim();
      if (!pid || !Number.isFinite(Number(pid))) return false;
      if (bulkConfirmIneligible && bulkAuditNote.trim().length < 8) return false;
      return true;
    }
    if (bulkAction === 'create_provisional_customer') {
      return validateBulkForm ? validateBulkForm() : true;
    }
    if (bulkAction === 'create_provisional_distributor') return true;
    if (bulkAction === 'set_plan_fallback_region' || bulkAction === 'set_plan_fallback_channel') return true;
    if (bulkAction === 'apply_suggested_region') return selectedIds.length > 0;
    return false;
  }, [
    bulkAction,
    bulkCustomerId,
    bulkDistributorId,
    bulkProductId,
    bulkConfirmIneligible,
    bulkAuditNote,
    bulkRegionId,
    bulkChannelId,
    validateBulkForm,
  ]);

  const bulkPreview = useMutation({
    mutationFn: async () => {
      if (
        bulkAction === 'set_plan_fallback_region' ||
        bulkAction === 'set_plan_fallback_channel' ||
        bulkAction === 'apply_suggested_region'
      ) {
        return {
          import_job_id: importJobId,
          action: bulkAction,
          results: selectedIds.map((id) => ({ candidate_id: id })),
          totals: { plan_only: true },
        } satisfies StewardBulkPreviewResponse;
      }
      const body = buildBulkBody();
      const chunkSize = config.bulkChunkSize(bulkAction);
      const chunks = config.chunkBulkCandidateIds(selectedIds, chunkSize);
      const parts: StewardBulkPreviewResponse[] = [];
      for (const candidate_ids of chunks) {
        const part = await apiPost<StewardBulkPreviewResponse>(
          config.bulkPreviewPath(importJobId),
          { ...body, candidate_ids }
        );
        parts.push(part);
      }
      return config.mergeBulkPreviewResponses(importJobId, bulkAction, parts);
    },
    onSuccess: (data) => {
      setBulkApplySummary(null);
      setPreviewData(data);
      setPreviewApplyToken(previewToken);
      setPreviewOpen(true);
    },
  });

  const bulkApply = useMutation({
    mutationFn: async () => {
      if (bulkAction === 'apply_suggested_region' && applySuggestedRegion) {
        await applySuggestedRegion({ candidateIds: [...selectedIds] });
        return {
          import_job_id: importJobId,
          action: bulkAction,
          applied: selectedIds.length,
          failed: 0,
          results: [],
        } satisfies StewardBulkApplyResponse;
      }
      if (
        (bulkAction === 'set_plan_fallback_region' || bulkAction === 'set_plan_fallback_channel') &&
        onApplyPlanFallback
      ) {
        await onApplyPlanFallback({
          action: bulkAction,
          regionId: bulkRegionId,
          channelId: bulkChannelId,
        });
        return {
          import_job_id: importJobId,
          action: bulkAction,
          applied: 0,
          failed: 0,
          results: [],
        } satisfies StewardBulkApplyResponse;
      }
      const body = buildBulkBody();
      if (bulkAction === 'ignore') {
        let taskId: string | undefined;
        try {
          const enqueued = await apiPost<StewardBulkAsyncEnqueueResponse>(
            config.bulkIgnoreAsyncPath(importJobId),
            body
          );
          taskId = enqueued.task_id;
          registerClientBackgroundTask({
            taskId: enqueued.task_id,
            importJobId,
            kind: config.bulkIgnoreBackgroundKind as never,
            label: config.bulkIgnoreBackgroundLabel(importJobId),
          });
          void qc.invalidateQueries({ queryKey: ['background-tasks-active'] });
          return config.pollBulkProvisionalTask(importJobId, enqueued.task_id, {
            rowCount: selectedIds.length,
          });
        } finally {
          if (taskId) finishClientBackgroundTask(taskId);
          void qc.invalidateQueries({ queryKey: ['background-tasks-active'] });
        }
      }
      if (bulkAction === 'create_provisional_customer') {
        let taskId: string | undefined;
        try {
          const enqueued = await apiPost<StewardBulkAsyncEnqueueResponse>(
            config.bulkProvisionalCustomersAsyncPath(importJobId),
            body
          );
          taskId = enqueued.task_id;
          registerClientBackgroundTask({
            taskId: enqueued.task_id,
            importJobId,
            kind: config.bulkProvisionalBackgroundKind as never,
            label: config.bulkProvisionalBackgroundLabel(importJobId),
          });
          void qc.invalidateQueries({ queryKey: ['background-tasks-active'] });
          return config.pollBulkProvisionalTask(importJobId, enqueued.task_id, {
            rowCount: selectedIds.length,
          });
        } finally {
          if (taskId) finishClientBackgroundTask(taskId);
          void qc.invalidateQueries({ queryKey: ['background-tasks-active'] });
        }
      }
      const chunkSize = config.bulkChunkSize(bulkAction);
      const chunks = config.chunkBulkCandidateIds(selectedIds, chunkSize);
      const parts: StewardBulkApplyResponse[] = [];
      for (const candidate_ids of chunks) {
        const part = await apiPost<StewardBulkApplyResponse>(
          config.bulkApplyPath(importJobId),
          { ...body, candidate_ids }
        );
        parts.push(part);
      }
      return config.mergeBulkApplyResponses(importJobId, bulkAction, parts);
    },
    onMutate: async () => {
      if (
        bulkAction === 'create_provisional_customer' ||
        bulkAction === 'ignore' ||
        bulkAction === 'set_plan_fallback_region' ||
        bulkAction === 'set_plan_fallback_channel' ||
        bulkAction === 'apply_suggested_region'
      ) {
        return undefined;
      }
      const stewardAction = config.bulkActionToStewardAction(bulkAction);
      if (!stewardAction || selectedIds.length === 0) return undefined;
      const previous = config.optimisticallyApplyBulk(qc, importJobId, selectedIds, stewardAction);
      return { previous, stewardAction } satisfies {
        previous?: StewardEngineCandidateRow[];
        stewardAction: string;
      };
    },
    onError: (_err, _vars, ctx) => {
      if (ctx?.previous) {
        qc.setQueryData(config.candidatesQueryKey(importJobId), ctx.previous);
      }
    },
    onSuccess: (data) => {
      const appliedIds = (data.results || [])
        .filter((r) => r.ok === true && r.candidate_id != null)
        .map((r) => Number(r.candidate_id))
        .filter((id) => Number.isFinite(id));
      const planOnly =
        bulkAction === 'set_plan_fallback_region' ||
        bulkAction === 'set_plan_fallback_channel' ||
        bulkAction === 'apply_suggested_region';
      setBulkApplySummary(
        planOnly
          ? bulkAction === 'apply_suggested_region'
            ? 'Suggested region overrides applied to the plan — review effective geo, then Apply selected ready when ready.'
            : 'Plan fallback updated — refresh suggestions if the grid does not update automatically.'
          : `Bulk steward: applied ${data.applied}, failed ${data.failed}. Re-run import validation (server) when ready.`
      );
      setPreviewOpen(false);
      setPreviewData(null);
      setPreviewApplyToken(null);
      setBulkMode('normal');
      setSelectedIds([]);
      config.invalidateStewardQueries(qc, importJobId, { includeImportJobsList: true });
      onInvalidate();
      if (appliedIds.length > 0) {
        onShrinkPlanScope?.(appliedIds);
        if (bulkAction === 'ignore') {
          onEvictResolvedCandidates?.(appliedIds);
        }
      }
      if (
        !planOnly &&
        (bulkAction === 'ignore' ||
          bulkAction === 'map_customer' ||
          bulkAction === 'map_distributor' ||
          bulkAction === 'resolve_product')
      ) {
        void Promise.resolve(onPlanRefresh?.()).catch(() => {});
      }
      onBulkClosed?.();
    },
  });

  const applyReady = previewApplyToken !== null && previewApplyToken === previewToken && previewData !== null;

  return {
    bulkAction,
    setBulkAction,
    bulkNotes,
    setBulkNotes,
    bulkCustomerId,
    setBulkCustomerId,
    bulkDistributorId,
    setBulkDistributorId,
    bulkProductId,
    setBulkProductId,
    bulkRawToken,
    setBulkRawToken,
    bulkConfirmIneligible,
    setBulkConfirmIneligible,
    bulkAuditNote,
    setBulkAuditNote,
    bulkRegionId,
    setBulkRegionId,
    bulkChannelId,
    setBulkChannelId,
    bulkPreferredDistributorId,
    setBulkPreferredDistributorId,
    bulkPartnerTier,
    setBulkPartnerTier,
    bulkProvisionalNotes,
    setBulkProvisionalNotes,
    bulkDistSuspiciousOk,
    setBulkDistSuspiciousOk,
    bulkProvisionalDistCode,
    setBulkProvisionalDistCode,
    bulkApplySummary,
    setBulkApplySummary,
    previewOpen,
    setPreviewOpen,
    previewData,
    bulkPreview,
    bulkApply,
    bulkFormReady,
    applyReady,
  };
}

