type SettlementBook = {
  open_case_count?: number;
  book_total?: number;
  settled_amount?: number;
  outstanding_amount?: number;
  blocked_amount?: number;
  book_total_usd_booked?: number | null;
  settled_usd_booked?: number | null;
  outstanding_usd_booked?: number | null;
  open_booked_count?: number;
  open_unbooked_count?: number;
  currency_code?: string;
  by_evidence_basis?: Record<
    string,
    { case_count?: number; owed?: number; paid?: number; outstanding?: number }
  >;
  evidence_basis_note?: string;
};

type BookFilter = 'proposed' | 'ended' | 'settled' | 'blocked' | 'draft' | null;

type FxBackfillSuggestion = {
  case_id: number;
  case_code: string;
  status: string;
  suggested_rate: number | null;
  suggested_rate_date: string | null;
  source: string;
  is_fallback: boolean;
  will_book_on_confirm: boolean;
};

function fxBlockedReason(row: CporCaseListRow): string | undefined {
  const r = row.settle_readiness;
  if (!r || r.fx_settle_allowed !== false) return undefined;
  if (!r.fx_declared) return 'FX undeclared — no positive ROE snapshot';
  if (!r.fx_mode_declared) return 'FX mode not declared (booked / floating)';
  return 'FX settle blocked';
}

function isOpenBookStatus(status: string): boolean {
  const s = (status || '').toLowerCase();
  return s !== 'settled' && s !== 'cancelled';
}

function isFxBlocked(row: CporCaseListRow): boolean {
  return row.settle_readiness?.fx_settle_allowed === false;
}

function ageDays(row: CporCaseListRow): number | null {
  if (!row.last_claim_sale_date) return null;
  const sale = Date.parse(row.last_claim_sale_date);
  if (!Number.isFinite(sale)) return null;
  return Math.max(0, Math.floor((Date.now() - sale) / 86_400_000));
}

function windowEndAgeDays(row: CporCaseListRow): number | null {
  if (!row.window_end) return null;
  const end = Date.parse(row.window_end);
  if (!Number.isFinite(end)) return null;
  return Math.max(0, Math.floor((Date.now() - end) / 86_400_000));
}

function bucketOutstanding(
  items: CporCaseListRow[],
  daysOf: (row: CporCaseListRow) => number | null,
): Array<{ bucket: string; value: number }> {
  const buckets = [
    { bucket: '0–14d', value: 0 },
    { bucket: '15–30d', value: 0 },
    { bucket: '31–60d', value: 0 },
    { bucket: '60d+', value: 0 },
  ];
  for (const r of items) {
    if (r.status === 'settled') continue;
    const d = daysOf(r);
    if (d == null) continue;
    const v = Number(r.outstanding_amount) || 0;
    if (d <= 14) buckets[0].value += v;
    else if (d <= 30) buckets[1].value += v;
    else if (d <= 60) buckets[2].value += v;
    else buckets[3].value += v;
  }
  return buckets;
}

export function CaseBookSurface() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'), { noSsr: true });
  const router = useRouter();
  const search = useSearchParams();
  const qc = useQueryClient();
  const statusParam = search.get('status');
  const filter: BookFilter =
    statusParam === 'blocked'
      ? 'blocked'
      : statusParam === 'proposed' ||
          statusParam === 'ended' ||
          statusParam === 'settled' ||
          statusParam === 'draft'
        ? statusParam
        : null;
  const selectedParam = search.get('case');
  const evidenceParam = search.get('evidence');
  const evidenceFilter: EvidenceBasis | null = isEvidenceBasis(evidenceParam) ? evidenceParam : null;
  const testDataOnly = search.get('test_data') === 'only';
  const scope = caseScopeFromSearch(search);
  const hasEntityScope = caseScopeIsActive(scope);
  const hasGridScope = hasEntityScope || testDataOnly;
  const [toastAction, setToastAction] = useState<string | null>(null);
  const [backfillItems, setBackfillItems] = useState<FxBackfillSuggestion[] | null>(null);
  const [declareModeOpen, setDeclareModeOpen] = useState(false);

  const setParams = useCallback(
    (patch: Record<string, string | null>) => {
      const next = new URLSearchParams(search.toString());
      Object.entries(patch).forEach(([k, v]) => (v == null || v === '' ? next.delete(k) : next.set(k, v)));
      const qs = next.toString();
      router.replace(qs ? `/commercial-planner/cpor-cases?${qs}` : '/commercial-planner/cpor-cases', {
        scroll: false,
      });
    },
    [router, search],
  );

  const { data, isLoading, isError, error, refetch } = useQuery({
    queryKey: ['cpor', 'cases', 'book'],
    queryFn: ({ signal }) =>
      apiGet<CporCasesPage>('/api/v1/cpor/cases?page=1&page_size=500', { signal }),
  });

  const { data: scopedPage, isLoading: scopedLoading } = useQuery({
    queryKey: ['cpor', 'cases', 'book', 'scoped', scope, testDataOnly],
    enabled: hasGridScope,
    queryFn: ({ signal }) => {
      const sp = new URLSearchParams({ page: '1', page_size: '500' });
      if (testDataOnly) sp.set('test_data', 'only');
      caseScopeToQuery(scope).forEach((v, k) => sp.set(k, v));
      return apiGet<CporCasesPage>(`/api/v1/cpor/cases?${sp.toString()}`, { signal });
    },
  });

  const { data: book } = useQuery({
    queryKey: ['cpor', 'settlement', 'book'],
    queryFn: ({ signal }) => apiGet<SettlementBook>('/api/v1/cpor/settlement/book', { signal }),
    staleTime: 15_000,
  });

  const counts = data?.status_counts ?? {};
  const proposedN = counts.proposed ?? 0;
  const ccy = book?.currency_code ?? 'ZAR';
  const allItems = data?.items ?? [];
  const fxBlockedRows = allItems.filter(isFxBlocked);
  const fxBlockedPositive = fxBlockedRows.filter(
    (r) => isOpenBookStatus(r.status) && (Number(r.outstanding_amount) || 0) > 0,
  );
  const negativeSupport = allItems.filter(
    (r) => isOpenBookStatus(r.status) && (Number(r.outstanding_amount) || 0) < -0.005,
  );
  const rateNoModeRows = allItems.filter(
    (r) => Boolean(r.settle_readiness?.fx_declared) && r.settle_readiness?.fx_mode_declared === false,
  );
  const missingRateRows = allItems.filter((r) => r.settle_readiness?.fx_declared === false);

  const scopedItems = hasGridScope ? (scopedPage?.items ?? []) : allItems;
  const rows = useMemo(() => {
    let next = scopedItems;
    if (filter === 'blocked') {
      next = next.filter(
        (r) => isFxBlocked(r) && isOpenBookStatus(r.status) && (Number(r.outstanding_amount) || 0) > 0,
      );
    } else if (filter) {
      next = next.filter((r) => r.status === filter);
    }
    if (evidenceFilter) next = next.filter((r) => r.evidence_basis === evidenceFilter);
    return next;
  }, [scopedItems, filter, evidenceFilter]);

  const selectedId = selectedParam && /^\d+$/.test(selectedParam) ? Number(selectedParam) : null;
  const { data: selectedDetail } = useQuery({
    queryKey: ['cpor', 'case', selectedId, 'book-drawer'],
    enabled: selectedId != null,
    queryFn: ({ signal }) => apiGet<CporCaseListRow>(`/api/v1/cpor/cases/${selectedId}`, { signal }),
  });
  const selected =
    allItems.find((r) => r.id === selectedId) ??
    rows.find((r) => r.id === selectedId) ??
    (selectedDetail && selectedId != null && selectedDetail.id === selectedId ? selectedDetail : null);

  const ageingClaim = useMemo(() => bucketOutstanding(allItems, ageDays), [allItems]);
  const ageingWindow = useMemo(() => bucketOutstanding(allItems, windowEndAgeDays), [allItems]);
  const hasClaimAge = allItems.some((r) => r.last_claim_sale_date);
  const ageing = hasClaimAge ? ageingClaim : ageingWindow;
  const evidenceCounts = data?.evidence_basis_counts ?? {
    claim_evidenced: allItems.filter((r) => r.evidence_basis === 'claim_evidenced').length,
    source_attested: allItems.filter((r) => r.evidence_basis === 'source_attested').length,
    none: allItems.filter((r) => (r.evidence_basis ?? 'none') === 'none').length,
  };

  const loadFxSuggestions = useMutation({
    mutationFn: () =>
      apiGet<{
        items: FxBackfillSuggestion[];
        count: number;
        missing_rate_count?: number;
        rate_no_mode_count?: number;
      }>('/api/v1/cpor/fx/backfill-suggestions'),
    onSuccess: (payload) => setBackfillItems(payload.items),
  });

  const declareBookedMode = useMutation({
    mutationFn: () =>
      apiPost<{ declared: number; mode: string }>('/api/v1/cpor/fx/declare-mode', {
        confirm: true,
        mode: 'booked',
      }),
    onSuccess: async (payload) => {
      setDeclareModeOpen(false);
      setToastAction(`Declared booked FX mode on ${payload.declared} case(s). Rates were not changed.`);
      await qc.invalidateQueries({ queryKey: ['cpor', 'cases'] });
      await qc.invalidateQueries({ queryKey: ['cpor', 'settlement', 'book'] });
    },
  });

  const confirmFxBackfill = useMutation({
    mutationFn: () =>
      apiPost<{ confirmed: number; booked: number }>('/api/v1/cpor/fx/backfill-confirm', {
        items: (backfillItems ?? [])
          .filter((row) => row.suggested_rate != null)
          .map((row) => ({ case_id: row.case_id, rate: row.suggested_rate })),
      }),
    onSuccess: async (payload) => {
      setToastAction(
        `Confirmed ${payload.confirmed} rate(s); booked ${payload.booked} already-approved case(s)`,
      );
      setBackfillItems(null);
      await qc.invalidateQueries({ queryKey: ['cpor', 'cases'] });
      await qc.invalidateQueries({ queryKey: ['cpor', 'settlement', 'book'] });
    },
  });

  const transition = useMutation({
    mutationFn: (payload: { id: number; action: string; comment?: string }) =>
      apiPost(`/api/v1/cpor/cases/${payload.id}/transition`, {
        action: payload.action,
        comment: payload.comment,
      }),
    onSuccess: async (_r, vars) => {
      setToastAction(`${vars.action} recorded`);
      setParams({ case: null });
      await qc.invalidateQueries({ queryKey: ['cpor', 'cases'] });
      await qc.invalidateQueries({ queryKey: ['cpor', 'settlement', 'book'] });
    },
  });

  const columnDefs = useMemo<ColDef<CporCaseListRow>[]>(
    () => [
      { field: 'case_code', headerName: 'Case', width: 130, pinned: 'left' },
      { field: 'customer_name', headerName: 'Customer', minWidth: 160, flex: 1 },
      { field: 'promotion_type', headerName: 'Type', minWidth: 150, flex: 1 },
      {
        field: 'estimate_qty_sum',
        headerName: 'Est. units',
        type: 'rightAligned',
        width: 110,
        valueFormatter: (p) => fmtInt(p.value as number | null),
      },
      {
        field: 'owed_amount',
        headerName: 'Owed',
        type: 'rightAligned',
        width: 168,
        wrapText: true,
        autoHeight: true,
        valueFormatter: (p) => {
          const dual = formatDualMoneyLine(p.value as number | null, {
            currencyCode: p.data?.currency_code ?? ccy,
            roeSnapshot: p.data?.roe_snapshot,
            missingRoe: Boolean(p.data?.missing_roe) || p.data?.fx_booked === false,
          });
          return `${dual.local} · ${dual.usdLine}`;
        },
      },
      {
        field: 'outstanding_amount',
        headerName: 'Outstanding',
        type: 'rightAligned',
        width: 180,
        wrapText: true,
        autoHeight: true,
        valueFormatter: (p) => {
          const dual = formatDualMoneyLine(p.value as number | null, {
            currencyCode: p.data?.currency_code ?? ccy,
            roeSnapshot: p.data?.roe_snapshot,
            missingRoe: Boolean(p.data?.missing_roe) || p.data?.fx_booked === false,
          });
          return `${dual.local} · ${dual.usdLine}`;
        },
        sort: 'desc',
      },
      {
        colId: 'age',
        headerName: hasClaimAge ? 'Age (claim sale)' : 'Age (window end)',
        type: 'rightAligned',
        width: 110,
        valueGetter: (p) =>
          hasClaimAge
            ? ageDays(p.data as CporCaseListRow)
            : windowEndAgeDays(p.data as CporCaseListRow),
        valueFormatter: (p) => (p.value == null ? '—' : `${p.value}d`),
      },
      {
        colId: 'evidence_basis',
        headerName: 'Evidence',
        width: 140,
        valueGetter: (p) => evidenceBasisLabel((p.data as CporCaseListRow | undefined)?.evidence_basis),
      },
      {
        field: 'status',
        headerName: 'Status',
        width: 120,
        cellRenderer: (p: { data?: CporCaseListRow }) =>
          p.data ? (
            <StatusChip label={STAGE_LABEL[p.data.status as PlanStage] ?? p.data.status} tone={stageTone(p.data.status)} />
          ) : null,
      },
      {
        colId: 'blocked_reason',
        headerName: 'Blocked reason',
        minWidth: 220,
        flex: 1.4,
        valueGetter: (p) => fxBlockedReason(p.data as CporCaseListRow) ?? '',
      },
    ],
    [ccy, hasClaimAge],
  );

  const chips = (
    [
      ['proposed', 'Awaiting approval', proposedN, 'warning'],
      ['ended', 'Ended', counts.ended ?? 0, 'default'],
      ['blocked', 'FX blocked', fxBlockedPositive.length, 'danger'],
      ['settled', 'Settled', counts.settled ?? 0, 'success'],
      ['draft', 'Draft', counts.draft ?? 0, 'default'],
    ] as const
  ).map(([key, label, n, tone]) => ({
    key,
    label: `${label} · ${n}`,
    active: filter === key,
    onToggle: () => setParams({ status: filter === key ? null : key, case: null }),
    tone: tone as 'danger' | 'warning' | 'success' | 'default',
  }));

  const evidenceChips = (
    [
      ['claim_evidenced', 'Claim evidenced', evidenceCounts.claim_evidenced ?? 0],
      ['source_attested', 'Source attested', evidenceCounts.source_attested ?? 0],
      ['none', 'No evidence', evidenceCounts.none ?? 0],
    ] as const
  ).map(([key, label, n]) => ({
    key,
    label: `${label} · ${n}`,
    active: evidenceFilter === key,
    onToggle: () => setParams({ evidence: evidenceFilter === key ? null : key, case: null }),
    tone: key === 'none' ? ('default' as const) : key === 'source_attested' ? ('warning' as const) : ('success' as const),
  }));

  const evidenceRow = (label: string, ok: boolean) => (
    <Stack direction="row" spacing={1} alignItems="center" key={label}>
      {ok ? <CheckCircleOutlineIcon fontSize="small" color="success" /> : <RadioButtonUncheckedIcon fontSize="small" color="disabled" />}
      <Typography variant="body2" color={ok ? 'text.primary' : 'text.secondary'}>
        {label} {ok ? '' : '— missing'}
      </Typography>
    </Stack>
  );

  const canApprove = !!selected?.allowed_next?.includes('approved');
  const canReject = !!selected?.allowed_next?.includes('rejected');

  return (
    <Stack spacing={2} sx={{ mt: 2 }} data-testid="funding-case-book">
      <HeadlineStrip columns={5}>
        <HeadlineFigure
          label="Open book total"
          value={
            <DualMoney
              amount={book?.book_total}
              currencyCode={ccy}
              usdAmount={book?.book_total_usd_booked ?? null}
              usdNote={
                (book?.open_unbooked_count ?? 0) > 0
                  ? `Σ ${book?.open_booked_count ?? 0} booked · ${book?.open_unbooked_count} unbooked have no USD`
                  : 'Σ booked cases'
              }
              missingRoe={!book?.book_total_usd_booked}
              testId="case-book-total"
            />
          }
          compact
          caption={`${book?.open_case_count ?? '—'} open cases (draft and ended; settled and cancelled are out). Owed is the sum of line support. Mix: claim ${book?.by_evidence_basis?.claim_evidenced?.case_count ?? 0} · attested ${book?.by_evidence_basis?.source_attested?.case_count ?? 0} · none ${book?.by_evidence_basis?.none?.case_count ?? 0}. Dollar totals add each case at its own booked rate.`}
        />
        <HeadlineFigure
          label="Paid on the open book"
          value={
            <DualMoney
              amount={book?.settled_amount}
              currencyCode={ccy}
              usdAmount={book?.settled_usd_booked ?? null}
              missingRoe={!book?.settled_usd_booked}
              testId="case-book-paid"
            />
          }
          compact
          severity="good"
          caption="Same-currency payment evidence only (paid/processed/closed). USD pending-report rows do not pay this ZAR book — R0 is expected until FX is declared."
        />
        <HeadlineFigure
          label="Outstanding"
          value={
            <DualMoney
              amount={book?.outstanding_amount}
              currencyCode={ccy}
              usdAmount={book?.outstanding_usd_booked ?? null}
              missingRoe={!book?.outstanding_usd_booked}
              testId="case-book-outstanding"
            />
          }
          compact
          caption="Owed − paid on the open book"
        />
        <HeadlineFigure
          label="FX blocked"
          value={fxBlockedPositive.length}
          unit="cases"
          compact
          severity="bad"
          caption={`${fmtCompact(book?.blocked_amount, ccy)} positive outstanding on the open book (excludes settled and negative-support cases)`}
          onClick={() => setParams({ status: 'blocked' })}
        />
        <HeadlineFigure
          label="Awaiting approval"
          value={proposedN}
          unit="cases"
          compact
          severity={proposedN ? 'warn' : 'neutral'}
          caption="Proposed — planner decision. Not ended cases waiting on claims."
          onClick={() => setParams({ status: 'proposed' })}
        />
      </HeadlineStrip>

      <Stack spacing={1} data-testid="case-book-lifecycle">
        <Typography variant="caption" color="text.secondary">
          Settlement half of the same lifecycle — not a second object. Pending disputes and unmatched
          Case IDs are below the grid.
        </Typography>
        <Box sx={{ minWidth: { md: 520 } }}>
          <LifecycleRail
            stages={[...LIFECYCLE_STAGES]}
            labels={STAGE_LABEL}
            counts={counts}
            dense
            onSelect={(s) => {
              if (s === 'ended' || s === 'settled') {
                setParams({ status: filter === s ? null : s, case: null });
              } else {
                router.push(`/promotions?stage=${s}`);
              }
            }}
          />
        </Box>
      </Stack>

      <ScopeBar
        chips={[
          ...chips,
          ...evidenceChips,
          {
            key: 'test_data',
            label: `Test data · ${data?.test_data_count ?? 0}`,
            active: testDataOnly,
            onToggle: () => setParams({ test_data: testDataOnly ? null : 'only', case: null }),
            tone: 'warning' as const,
          },
        ]}
        summary={`${rows.length} of ${hasGridScope ? (scopedPage?.total ?? rows.length) : (data?.total ?? rows.length)} cases${hasGridScope ? ' in this find' : ''}`}
        onClear={() =>
          setParams({ status: null, evidence: null, case: null, test_data: null, ...caseScopeClearPatch() })
        }
        clearAvailable={hasGridScope}
        filters={<CaseScopeFilters scope={scope} onPatch={setParams} />}
      />

      <ModuleDataSection
        isLoading={isLoading || (hasGridScope && scopedLoading)}
        isError={isError}
        error={error as Error | null}
        onRetry={() => void refetch()}
        isEmpty={rows.length === 0}
        empty={{
          title: 'No cases in this scope',
          description: 'Clear the status chips or find filters, or import claim / payment evidence from the domain actions.',
          primary: {
            label: 'Clear scope',
            onClick: () => setParams({ status: null, evidence: null, test_data: null, ...caseScopeClearPatch() }),
          },
        }}
      >
        {isMobile ? (
          <Stack spacing={1} data-testid="funding-record-cards">
            {rows.map((c) => (
              <Card key={c.id} variant="outlined" sx={{ boxShadow: 'none' }}>
                <CardActionArea onClick={() => setParams({ case: String(c.id) })}>
                  <CardContent sx={{ py: 1.25, '&:last-child': { pb: 1.25 } }}>
                    <Stack direction="row" justifyContent="space-between" alignItems="flex-start" spacing={1}>
                      <Box sx={{ minWidth: 0 }}>
                        <Typography variant="body2" sx={{ fontWeight: 600 }}>
                          {c.customer_name} · {c.case_code}
                        </Typography>
                        <Typography variant="caption" color="text.secondary" noWrap sx={{ display: 'block' }}>
                          {c.promotion_type}
                        </Typography>
                      </Box>
                      <StatusChip label={STAGE_LABEL[c.status as PlanStage] ?? c.status} tone={stageTone(c.status)} />
                    </Stack>
                    <Stack direction="row" spacing={2} sx={{ mt: 1 }}>
                      <Typography variant="caption">
                        Owed <b>{fmtCompact(c.owed_amount, c.currency_code)}</b>
                      </Typography>
                      <Typography variant="caption">
                        Outstanding <b>{fmtCompact(c.outstanding_amount, c.currency_code)}</b>
                      </Typography>
                    </Stack>
                    {fxBlockedReason(c) ? (
                      <Typography variant="caption" color="error.main" sx={{ display: 'block', mt: 0.5 }}>
                        {fxBlockedReason(c)}
                      </Typography>
                    ) : null}
                  </CardContent>
                </CardActionArea>
              </Card>
            ))}
          </Stack>
        ) : (
          <EnterpriseDataGrid<CporCaseListRow>
            rowData={rows}
            columnDefs={columnDefs}
            height={420}
            gridOptions={{
              onRowClicked: (e: RowClickedEvent<CporCaseListRow>) => e.data && setParams({ case: String(e.data.id) }),
              getRowId: (p) => String(p.data.id),
            }}
          />
        )}
      </ModuleDataSection>

      <PaymentEvidenceOverlayPanel />

      <Box sx={{ display: 'grid', gap: 2, gridTemplateColumns: { xs: '1fr', md: '2fr 3fr' } }}>
        <Panel
          title="Outstanding by age"
          subtitle={
            hasClaimAge
              ? 'Unsettled value by days since claim sale_date — not window end'
              : 'Unsettled value by days since window end. Claim-sale ageing stays available when claim lines exist — not estimated as sale_date.'
          }
        >
          <Box data-testid="case-book-ageing">
            <CategoryBars
              data={ageing}
              x="bucket"
              y="value"
              height={170}
              // Other currencies keep bare ticks; the title names the currency (N-0114).
              unit={ccy === 'ZAR' ? 'zar' : ccy === 'USD' ? 'usd' : 'number'}
              xAxisTitle={hasClaimAge ? 'Age since claim sale date (days)' : 'Age since window end (days)'}
              yAxisTitle={`Outstanding (${ccy === 'ZAR' ? 'R' : ccy === 'USD' ? 'US$' : ccy})`}
              // Age buckets are ordered: no top N or re-sort.
              controls={false}
              colorBy={(r) =>
                String(r.bucket) === '60d+'
                  ? theme.palette.error.main
                  : String(r.bucket) === '31–60d'
                    ? theme.palette.warning.main
                    : theme.palette.primary.main
              }
            />
          </Box>
        </Panel>
        <Panel title="Blocked cases — reasons" subtitle="FX settle refuses until ROE and mode are declared" flush>
          <Stack spacing={0.25} sx={{ px: 1, pb: 1 }}>
            <Stack direction="row" spacing={1} sx={{ px: 1, pt: 1, pb: 0.5 }} flexWrap="wrap" useFlexGap>
              {rateNoModeRows.length > 0 ? (
                <Button
                  size="small"
                  variant="contained"
                  onClick={() => setDeclareModeOpen(true)}
                  data-testid="fx-declare-mode"
                >
                  Declare booked FX mode · {rateNoModeRows.length}
                </Button>
              ) : null}
              {missingRateRows.length > 0 ? (
                <Button
                  size="small"
                  variant="outlined"
                  disabled={loadFxSuggestions.isPending}
                  onClick={() => loadFxSuggestions.mutate()}
                  data-testid="fx-backfill-suggest"
                >
                  {loadFxSuggestions.isPending
                    ? 'Loading suggestions…'
                    : `Suggest rates for ${missingRateRows.length} case${missingRateRows.length === 1 ? '' : 's'} missing a rate`}
                </Button>
              ) : null}
              {backfillItems && backfillItems.length > 0 ? (
                <Button
                  size="small"
                  variant="contained"
                  disabled={confirmFxBackfill.isPending}
                  onClick={() => confirmFxBackfill.mutate()}
                  data-testid="fx-backfill-confirm"
                >
                  Confirm {backfillItems.filter((r) => r.suggested_rate != null).length} suggestion
                  {backfillItems.filter((r) => r.suggested_rate != null).length === 1 ? '' : 's'}
                </Button>
              ) : null}
            </Stack>
            {missingRateRows.length === 0 ? (
              <Typography variant="body2" color="text.secondary" sx={{ px: 1.5, py: 0.5 }}>
                No cases are missing a rate. Rate suggestion is not offered. {rateNoModeRows.length}{' '}
                {rateNoModeRows.length === 1 ? 'case has' : 'cases have'} a rate and need a booked or floating rate.
              </Typography>
            ) : null}
            {backfillItems && backfillItems.length === 0 && missingRateRows.length > 0 ? (
              <Typography variant="body2" color="text.secondary" sx={{ px: 1.5, py: 0.5 }}>
                No missing-rate cases received a window-start suggestion.
              </Typography>
            ) : null}
            {backfillItems
              ?.filter((row) => row.suggested_rate != null)
              .slice(0, 8)
              .map((row) => (
                <PanelRow
                  key={`sug-${row.case_id}`}
                  severity="warning"
                  primary={`${row.case_code} · ${row.suggested_rate?.toFixed(2)} ZAR/USD`}
                  secondary={`${row.source}${row.is_fallback ? ' (fallback)' : ''} · ${row.suggested_rate_date ?? 'no date'} · ${
                    row.will_book_on_confirm ? 'confirm books (already approved)' : 'confirm proposes only'
                  }`}
                />
              ))}
            {negativeSupport.map((c) => (
              <PanelRow
                key={`neg-${c.id}`}
                severity="warning"
                primary={`${c.case_code} · ${c.customer_name}`}
                secondary="A stored credit on the line, not a missing exchange rate. This is why the blocked positive outstanding is larger than the open book."
                figure={fmtCompact(c.outstanding_amount, c.currency_code ?? ccy)}
                onClick={() => setParams({ case: String(c.id) })}
              />
            ))}
            {fxBlockedPositive.slice(0, 6).map((c) => (
              <PanelRow
                key={c.id}
                severity="danger"
                primary={`${c.case_code} · ${c.customer_name}`}
                secondary={fxBlockedReason(c)}
                figure={fmtCompact(c.outstanding_amount, c.currency_code ?? ccy)}
                onClick={() => setParams({ case: String(c.id) })}
              />
            ))}
            {!fxBlockedPositive.length && !negativeSupport.length ? (
              <Typography variant="body2" color="text.secondary" sx={{ px: 1.5, py: 1 }}>
                No FX-blocked cases in this page.
              </Typography>
            ) : null}
          </Stack>
        </Panel>
      </Box>

      <PortfolioReadPanel currencyCode={ccy} />

      {toastAction ? (
        <Alert severity="success" onClose={() => setToastAction(null)}>
          {toastAction}
        </Alert>
      ) : null}

      <EntityContextPanel
        open={!!selected}
        onClose={() => setParams({ case: null })}
        kicker={selected ? STAGE_LABEL[selected.status as PlanStage] ?? selected.status : undefined}
        title={selected ? `${selected.case_code} · ${selected.customer_name}` : ''}
        subtitle={selected ? `${selected.promotion_type} · ${selected.window_start} → ${selected.window_end}` : undefined}
        width={480}
        figures={
          selected ? (
            <HeadlineStrip columns={3}>
              <HeadlineFigure
                label="Owed"
                value={fmtCompact(selected.owed_amount, selected.currency_code)}
                dense
                caption={`${fmtInt(selected.estimate_qty_sum)} est. units`}
              />
              <HeadlineFigure
                label="Outstanding"
                value={fmtCompact(selected.outstanding_amount, selected.currency_code)}
                dense
                severity={(selected.outstanding_amount ?? 0) > 0 ? 'warn' : 'good'}
              />
              <HeadlineFigure
                label="Age"
                value={ageDays(selected) ?? '—'}
                unit={ageDays(selected) != null ? 'days' : undefined}
                dense
                caption={selected.last_claim_sale_date ? 'Since last claim sale_date' : 'No claim sale_date'}
              />
            </HeadlineStrip>
          ) : null
        }
        related={
          selected
            ? [
                {
                  label: 'Open in Promotion planner',
                  href: `/promotions?plan=${selected.id}`,
                  hint: 'Same promotion case — planning workspace',
                },
                {
                  label: 'Settlement workspace (claims, settle, FX)',
                  href: `/commercial-planner/cpor-cases/${selected.id}`,
                  hint: 'Claim upload, settle, events, exports',
                },
                {
                  label: 'Was the promotion live at the planned price?',
                  href: '/listing-capture?tab=intelligence',
                  hint: 'Market & Listings › Activation',
                },
                { label: 'Stock cover', href: '/stock?lens=cover', hint: 'Stock & Sell-through › Cover' },
                {
                  label: 'Customer terms',
                  href: '/admin/customer-commercial-terms',
                  hint: 'Terms & assumptions',
                },
              ]
            : []
        }
        footer={
          selected && (canApprove || canReject) ? (
            <>
              {canReject ? (
                <Button
                  variant="outlined"
                  color="error"
                  size="small"
                  onClick={() =>
                    transition.mutate({
                      id: selected.id,
                      action: 'reject',
                      comment: 'Returned from case book — evidence or terms insufficient',
                    })
                  }
                  data-testid="case-return"
                >
                  Return with reason
                </Button>
              ) : null}
              {canApprove ? (
                <Button
                  variant="contained"
                  size="small"
                  onClick={() => transition.mutate({ id: selected.id, action: 'approve' })}
                  disabled={(selected.settle_readiness?.claim_evidence_count ?? 0) < 1}
                  data-testid="case-approve"
                >
                  Approve
                </Button>
              ) : null}
            </>
          ) : selected ? (
            <Button size="small" variant="outlined" onClick={() => setParams({ case: null })}>
              Close
            </Button>
          ) : null
        }
      >
        {selected ? (
          <Stack spacing={2}>
            <Box>
              <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                Lifecycle
              </Typography>
              <Box sx={{ mt: 1 }}>
                <LifecycleRail
                  stages={[...LIFECYCLE_STAGES]}
                  labels={STAGE_LABEL}
                  current={
                    LIFECYCLE_STAGES.includes(selected.status as (typeof LIFECYCLE_STAGES)[number])
                      ? (selected.status as (typeof LIFECYCLE_STAGES)[number])
                      : undefined
                  }
                  dense
                />
              </Box>
            </Box>
            {fxBlockedReason(selected) ? (
              <Alert severity="error" variant="outlined">
                {fxBlockedReason(selected)}
              </Alert>
            ) : null}
            {(Number(selected.outstanding_amount) || 0) < -0.005 ? (
              <Alert severity="warning" variant="outlined">
                Outstanding is negative because the stored line support sums below zero.
                That is a stored credit, not exchange-rate rounding.
              </Alert>
            ) : null}
            <Box>
              <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                Evidence
              </Typography>
              <Stack spacing={0.75} sx={{ mt: 1 }}>
                {evidenceRow('Claim file matched', (selected.settle_readiness?.claim_evidence_count ?? 0) > 0)}
                {evidenceRow('Payment evidence', (selected.payment_evidence_count ?? 0) > 0)}
                {evidenceRow(
                  'Sell-through corroborates claimed units',
                  false,
                )}
              </Stack>
              <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                Sell-through is not on this case list — open the settlement
                workspace. Approve in this drawer is only offered when the case may actually transition
                to approved.
              </Typography>
            </Box>
            <KeyValueList
              items={[
                { k: 'Type', v: selected.promotion_type },
                { k: 'Est. units', v: fmtInt(selected.estimate_qty_sum) },
                { k: 'Owed (line support)', v: fmtCompact(selected.owed_amount, selected.currency_code) },
                { k: 'Paid', v: fmtCompact(selected.paid_amount_sum, selected.currency_code) },
                { k: 'Window', v: `${selected.window_start ?? '—'} → ${selected.window_end ?? '—'}` },
              ]}
            />
          </Stack>
        ) : null}
      </EntityContextPanel>
      <Dialog
        open={declareModeOpen}
        onClose={() => !declareBookedMode.isPending && setDeclareModeOpen(false)}
        fullWidth
        maxWidth="sm"
      >
        <DialogTitle>Declare booked FX mode</DialogTitle>
        <DialogContent>
          <Typography variant="body2">
            This sets <code>fx_mode = booked</code> on {rateNoModeRows.length} case
            {rateNoModeRows.length === 1 ? '' : 's'} that already have a positive rate and no valid
            mode. It does not change <code>roe_snapshot</code>. It does not run unless you confirm.
            Booked is the settled default; floating remains available on a single case.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeclareModeOpen(false)} disabled={declareBookedMode.isPending}>
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={() => declareBookedMode.mutate()}
            disabled={declareBookedMode.isPending || rateNoModeRows.length === 0}
            data-testid="fx-declare-mode-confirm"
          >
            {declareBookedMode.isPending ? 'Declaring…' : `Confirm booked on ${rateNoModeRows.length}`}
          </Button>
        </DialogActions>
      </Dialog>
    </Stack>
  );
}

'use client';

import SwapHorizOutlinedIcon from '@mui/icons-material/SwapHorizOutlined';
import UploadFileOutlinedIcon from '@mui/icons-material/UploadFileOutlined';
import {
  Alert,
  Box,
  Button,
  Card,
  CardActionArea,
  CardContent,
  Chip,
  Snackbar,
  Stack,
  Step,
  StepLabel,
  Stepper,
  Typography,
} from '@mui/material';
import { useQuery } from '@tanstack/react-query';
import Link from 'next/link';
import { useRouter, useSearchParams } from 'next/navigation';
import { useCallback, useMemo, useState } from 'react';

import {
  CanonicalColumnMappingPanel,
  type CanonicalRequiredGroup,
  type CanonicalTargetOption,
} from '@/features/import-mapping/CanonicalColumnMappingPanel';
import { TEMPLATE_CAPABILITIES } from '@/features/promotions-funding/capabilities';
import type { CporCasesPage } from '@/features/promotions-funding/types';
import { apiGet } from '@/lib/api';
import { CapabilityLedger } from '@/features/workbench-ui/CapabilityLedger';
import { CapabilityStatus } from '@/features/shell/CapabilityStatus';
import { StatusChip } from '@/features/workbench-ui/controls';
import { HeadlineFigure, HeadlineStrip } from '@/features/workbench-ui/HeadlineFigure';
import { Panel } from '@/features/workbench-ui/Panel';

/** Canonical targets for the stored historical-import profile (not the frozen 32-column export). */
export const TEMPLATE_CANONICAL: CanonicalTargetOption[] = [
  { value: 'case_code', label: 'Case reference' },
  { value: 'case_name', label: 'Case name' },
  { value: 'customer_token', label: 'Customer' },
  { value: 'promotion_type', label: 'Promotion type' },
  { value: 'window_start', label: 'Window start' },
  { value: 'window_end', label: 'Window end' },
  { value: 'sales_model_token', label: 'Product (SKU / model)' },
  { value: 'distributor_token', label: 'Distributor' },
  { value: 'pod_quarter', label: 'POD quarter / layer' },
  { value: 'srp', label: 'Promo SRP' },
  { value: 'dealer_margin_pct', label: 'Dealer margin %' },
  { value: 'disti_margin_pct', label: 'Distributor margin %' },
  { value: 'rebate_pct', label: 'Rebate %' },
  { value: 'cost_basis', label: 'Cost basis' },
  { value: 'support_unit', label: 'Support per unit' },
  { value: 'estimate_qty', label: 'Estimated units' },
  { value: 'ttl_support', label: 'Total support' },
  { value: 'result_qty', label: 'Actual units (result)' },
  { value: 'status', label: 'Status' },
];

const REQUIRED: CanonicalRequiredGroup[] = [
  { id: 'who', label: 'Customer', anyOf: ['customer_token'] },
  { id: 'what', label: 'Product', anyOf: ['sales_model_token'] },
  { id: 'when', label: 'Window', anyOf: ['window_start'] },
  { id: 'type', label: 'Promotion type', anyOf: ['promotion_type'] },
  { id: 'price', label: 'Promo SRP', anyOf: ['srp'] },
  { id: 'qty', label: 'Estimated units', anyOf: ['estimate_qty'] },
];

export type MappingProfile = {
  id: number;
  profile_code: string;
  display_name: string;
  header_row_index?: number;
  column_map_json: Record<string, string[]>;
  sheet_roles_json: Record<string, string>;
  value_maps_json?: Record<string, unknown>;
  is_default: boolean;
  notes?: string | null;
};

export function draftFromColumnMap(map: Record<string, string[]> | undefined): Record<string, string> {
  const draft: Record<string, string> = {};
  for (const [canonical, headers] of Object.entries(map ?? {})) {
    for (const header of headers ?? []) {
      if (header) draft[header] = canonical;
    }
  }
  return draft;
}

function mappedCount(map: Record<string, string[]> | undefined): number {
  return Object.values(map ?? {}).filter((h) => (h ?? []).some((x) => Boolean(x))).length;
}

export function PlanTemplatesSurface() {
  const router = useRouter();
  const search = useSearchParams();
  const code = search.get('template');
  const setTemplate = useCallback(
    (c: string) => {
      const next = new URLSearchParams(search.toString());
      next.set('template', c);
      next.delete('learn');
      router.replace(`/commercial-planner/cpor-cases/historical-import?${next.toString()}`, { scroll: false });
    },
    [router, search],
  );

  const { data: profilePage } = useQuery({
    queryKey: ['cpor', 'historical', 'profiles'],
    queryFn: ({ signal }) =>
      apiGet<{ profiles: MappingProfile[] }>('/api/v1/cpor/historical-import/profiles', { signal }),
  });
  const { data: casesPage } = useQuery({
    queryKey: ['cpor', 'cases', 'templates-origin'],
    queryFn: ({ signal }) =>
      apiGet<CporCasesPage>('/api/v1/cpor/cases?page=1&page_size=500', { signal }),
  });

  const profiles = profilePage?.profiles ?? [];
  const selected =
    profiles.find((p) => p.profile_code === code) ?? profiles.find((p) => p.is_default) ?? profiles[0];
  const historicalN = (casesPage?.items ?? []).filter((r) => r.origin === 'historical_import').length;

  const [drafts, setDrafts] = useState<Record<string, Record<string, string>>>({});
  const [toast, setToast] = useState<string | null>(null);

  const initialDraft = useMemo(
    () => (selected ? draftFromColumnMap(selected.column_map_json) : {}),
    [selected],
  );
  const draft = (selected && drafts[selected.profile_code]) || initialDraft;
  const dirty =
    !!selected &&
    drafts[selected.profile_code] !== undefined &&
    JSON.stringify(drafts[selected.profile_code]) !== JSON.stringify(initialDraft);

  const extraTargets = useMemo(() => {
    const known = new Set(TEMPLATE_CANONICAL.map((c) => c.value));
    const extra: CanonicalTargetOption[] = [];
    for (const p of profiles) {
      for (const key of Object.keys(p.column_map_json ?? {})) {
        if (!known.has(key)) {
          known.add(key);
          extra.push({ value: key, label: key.replace(/_/g, ' ') });
        }
      }
    }
    return extra;
  }, [profiles]);
  const targets = [...TEMPLATE_CANONICAL, ...extraTargets];

  const fileHeaders = Object.keys(draft);
  const mappedCanonical = new Set(Object.values(draft));
  const missingRequired = REQUIRED.filter((g) => !g.anyOf.some((v) => mappedCanonical.has(v)));
  const step = selected && missingRequired.length === 0 && !dirty ? 3 : missingRequired.length ? 1 : 2;
  const canonicalFieldCount = Object.keys(selected?.column_map_json ?? {}).length || targets.length;

  return (
    <Stack spacing={2} sx={{ mt: 2 }} data-testid="plan-templates">
      <Alert severity="info" variant="outlined" icon={<SwapHorizOutlinedIcon />}>
        <b>Upload historical cases here.</b> A customer promotion or funding workbook is validated,
        the names are matched, and the cases are applied. Learn a template only when that
        customer’s column layout is new. Writing a plan back into that layout is not built — export
        stays the fixed workbook.
      </Alert>

      <HeadlineStrip columns={4}>
        <HeadlineFigure
          label="Templates"
          value={profiles.length}
          compact
          caption={`${profiles.filter((p) => mappedCount(p.column_map_json) > 0).length} with a stored column map`}
        />
        <HeadlineFigure
          label="Plans read through templates"
          value={historicalN}
          compact
          caption="Plans that came in through a historical import. The column map is not stored on the case."
        />
        <HeadlineFigure
          label="Plan fields"
          value={canonicalFieldCount}
          compact
          caption={`${REQUIRED.length} required groups`}
        />
        <HeadlineFigure
          label="Export side"
          value="—"
          compact
          caption="The import map is saved. Writing a plan back into the customer layout is not built."
        />
      </HeadlineStrip>

      <Box
        sx={{
          display: 'grid',
          gap: 2,
          gridTemplateColumns: { xs: 'minmax(0, 1fr)', lg: 'minmax(260px, 1fr) minmax(0, 3fr)' },
          alignItems: 'start',
        }}
      >
        <Stack spacing={2} sx={{ minWidth: 0 }}>
          <Panel title="Templates" subtitle="One per customer workbook layout" flush>
            <Stack spacing={1} sx={{ px: 1.5, pb: 1.5 }}>
              {profiles.map((t) => {
                const mapped = mappedCount(t.column_map_json);
                const ok = REQUIRED.every((g) =>
                  g.anyOf.some((v) => (t.column_map_json[v] ?? []).some(Boolean)),
                );
                return (
                  <Card
                    key={t.profile_code}
                    variant="outlined"
                    sx={{
                      boxShadow: 'none',
                      borderColor: t.profile_code === selected?.profile_code ? 'primary.main' : 'divider',
                    }}
                  >
                    <CardActionArea
                      onClick={() => setTemplate(t.profile_code)}
                      data-testid={`template-${t.profile_code}`}
                    >
                      <CardContent sx={{ py: 1.25, '&:last-child': { pb: 1.25 } }}>
                        <Stack direction="row" justifyContent="space-between" alignItems="flex-start" spacing={1}>
                          <Box sx={{ minWidth: 0 }}>
                            <Typography variant="body2" sx={{ fontWeight: 600 }} noWrap>
                              {t.display_name}
                            </Typography>
                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }} noWrap>
                              {t.profile_code}
                              {t.is_default ? ' · default' : ''}
                            </Typography>
                          </Box>
                          <StatusChip
                            label={ok ? 'Mapped' : 'Needs mapping'}
                            tone={ok ? 'success' : 'warning'}
                          />
                        </Stack>
                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                          {mapped}/{Object.keys(t.column_map_json ?? {}).length || mapped} fields ·{' '}
                          {Object.keys(t.value_maps_json ?? {}).length} value maps
                        </Typography>
                      </CardContent>
                    </CardActionArea>
                  </Card>
                );
              })}
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                <Button
                  component={Link}
                  href="/commercial-planner/cpor-cases/historical-import?upload=1"
                  variant="contained"
                  size="small"
                  startIcon={<UploadFileOutlinedIcon />}
                  data-testid="historical-cases-upload"
                >
                  Upload historical cases
                </Button>
                <Button
                  component={Link}
                  href="/commercial-planner/cpor-cases/historical-import?learn=1"
                  variant="outlined"
                  size="small"
                  data-testid="template-learn"
                >
                  Learn a new template from a workbook
                </Button>
              </Stack>
            </Stack>
          </Panel>
          <CapabilityLedger title="What works here" items={TEMPLATE_CAPABILITIES} />
        </Stack>

        {selected ? (
          <Stack spacing={2} sx={{ minWidth: 0 }}>
            <Panel
              title={
                <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" useFlexGap>
                  <span>{selected.display_name}</span>
                  <Chip
                    size="small"
                    variant="outlined"
                    label={selected.profile_code}
                    sx={{ height: 20, fontSize: 11, fontFamily: 'monospace' }}
                  />
                  <CapabilityStatus status={missingRequired.length ? 'partial' : 'live'} size="inline" />
                </Stack>
              }
              subtitle={`sheets: ${Object.keys(selected.sheet_roles_json ?? {}).join(', ') || '—'} · header row ${selected.header_row_index ?? 1}${selected.notes ? ` · ${selected.notes}` : ''}`}
              actions={
                <Stack direction="row" spacing={1}>
                  <Button
                    size="small"
                    disabled={!dirty}
                    onClick={() =>
                      setDrafts((d) => {
                        const next = { ...d };
                        delete next[selected.profile_code];
                        return next;
                      })
                    }
                  >
                    Discard
                  </Button>
                  <Button
                    size="small"
                    variant="contained"
                    disabled={!dirty || missingRequired.length > 0}
                    onClick={() =>
                      setToast(
                        'Profile edits are not a writer on this surface — the stored map is cpor_historical_mapping_profile, applied on the next historical import. Template-driven export is Planned.',
                      )
                    }
                    data-testid="template-save"
                  >
                    Save profile
                  </Button>
                </Stack>
              }
            >
              <Stepper activeStep={step} alternativeLabel sx={{ mb: 2 }}>
                <Step completed>
                  <StepLabel>Example workbook</StepLabel>
                </Step>
                <Step completed={step > 1}>
                  <StepLabel>Map columns</StepLabel>
                </Step>
                <Step completed={step > 2}>
                  <StepLabel>Value maps & constants</StepLabel>
                </Step>
                <Step completed={false}>
                  <StepLabel>Use for import & export</StepLabel>
                </Step>
              </Stepper>
              <CanonicalColumnMappingPanel
                fileHeaders={fileHeaders}
                draft={draft}
                onChange={(next) => setDrafts((d) => ({ ...d, [selected.profile_code]: next }))}
                targetOptions={targets}
                requiredGroups={REQUIRED}
                blockingErrors={missingRequired.map((g) => ({
                  code: `missing_${g.id}`,
                  message: `Required field “${g.label}” has no column in this workbook — map a column or set a constant.`,
                }))}
                adjustmentNotices={[
                  {
                    code: 'export_planned',
                    message:
                      '“Use for import & export” is partly built: import uses this profile today; writing a plan back into that layout is not built. Export stays the fixed workbook.',
                  },
                ]}
                dirty={dirty}
                testIdPrefix="plan-template"
              />
            </Panel>
            <Panel
              title="Fields with no column"
              subtitle="Plan fields this workbook does not map. Required ones block a complete map; optional ones are left out."
            >
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                {TEMPLATE_CANONICAL.filter((c) => !mappedCanonical.has(c.value)).map((c) => {
                  const req = REQUIRED.some((g) => g.anyOf.includes(c.value));
                  return (
                    <Chip
                      key={c.value}
                      size="small"
                      label={c.label}
                      color={req ? 'error' : 'default'}
                      variant={req ? 'filled' : 'outlined'}
                    />
                  );
                })}
              </Stack>
            </Panel>
          </Stack>
        ) : (
          <Alert severity="info">No mapping profiles yet. Upload a historical workbook, or learn a template from an example file.</Alert>
        )}
      </Box>
      <Snackbar
        open={!!toast}
        autoHideDuration={6000}
        onClose={() => setToast(null)}
        message={toast}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      />
    </Stack>
  );
}

'use client';

import {
  Alert,
  Box,
  Button,
  Checkbox,
  Divider,
  FormControl,
  FormControlLabel,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Switch,
  TextField,
  Typography,
} from '@mui/material';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useEffect, useMemo, useState } from 'react';

import { apiGet, apiPut, safeDisplayError } from '@/lib/api';

type GrainSet = string[];

type BaseMetric = {
  id: string;
  key: string;
  label: string;
  allowed_grains: GrainSet[];
  fact_family: string | null;
  handler_backed: boolean;
  locked: { formula: string; source_facts: string[]; owner_surface: string };
};

type OverlayPatch = { label?: string; hidden?: boolean; allowed_grains?: GrainSet[] };

type ComposedDraft = {
  key: string;
  label: string;
  op: 'ratio' | 'alias';
  inputs: string[];
  grain: GrainSet;
};

type OverlayEditorPayload = {
  tenant_id: string;
  overlay: { metrics?: Record<string, OverlayPatch>; composed?: Record<string, unknown> };
  base_metrics: BaseMetric[];
  compose_ops: Array<'ratio' | 'alias'>;
};

const OVERLAY_QUERY_KEY = ['semantics', 'overlay'] as const;
const CATALOG_QUERY_KEY = ['semantics', 'catalog'] as const;

function grainToken(set: GrainSet): string {
  return [...set].map((d) => d.trim().toLowerCase()).filter(Boolean).sort().join(',');
}

function parseGrainToken(token: string): GrainSet {
  return token.split(',').map((d) => d.trim()).filter(Boolean);
}

function sameSets(a: GrainSet[], b: GrainSet[]): boolean {
  const left = new Set(a.map(grainToken));
  const right = new Set(b.map(grainToken));
  if (left.size !== right.size) return false;
  for (const t of left) if (!right.has(t)) return false;
  return true;
}

function intersectGrainSets(sets: GrainSet[][]): GrainSet[] {
  if (!sets.length) return [];
  const [first, ...rest] = sets;
  return first.filter((candidate) =>
    rest.every((group) => group.some((g) => grainToken(g) === grainToken(candidate)))
  );
}

function composedFromOverlay(raw: Record<string, unknown> | undefined): ComposedDraft[] {
  if (!raw) return [];
  const out: ComposedDraft[] = [];
  for (const [ident, body] of Object.entries(raw)) {
    if (!body || typeof body !== 'object') continue;
    const row = body as {
      key?: string;
      label?: string;
      compose?: { op?: string; inputs?: string[]; grain?: GrainSet };
    };
    const op = row.compose?.op === 'alias' ? 'alias' : 'ratio';
    const inputs = Array.isArray(row.compose?.inputs) ? row.compose.inputs.map(String) : [];
    out.push({
      key: String(row.key || ident),
      label: String(row.label || ident),
      op,
      inputs: op === 'alias' ? inputs.slice(0, 1) : inputs.slice(0, 2),
      grain: Array.isArray(row.compose?.grain) ? row.compose.grain.map(String) : [],
    });
  }
  return out;
}

export function SemanticCatalogOverlayPanel() {
  const qc = useQueryClient();
  const overlayQuery = useQuery({
    queryKey: OVERLAY_QUERY_KEY,
    queryFn: () => apiGet<OverlayEditorPayload>('/api/v1/semantics/overlay'),
    staleTime: 15_000,
  });

  const [labels, setLabels] = useState<Record<string, string>>({});
  const [hidden, setHidden] = useState<Record<string, boolean>>({});
  const [grainTokens, setGrainTokens] = useState<Record<string, string[]>>({});
  const [composed, setComposed] = useState<ComposedDraft[]>([]);
  const [saveOk, setSaveOk] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);

  const baseMetrics = overlayQuery.data?.base_metrics ?? [];
  const byKey = useMemo(() => {
    const map = new Map<string, BaseMetric>();
    for (const m of baseMetrics) map.set(m.key, m);
    return map;
  }, [baseMetrics]);

  useEffect(() => {
    const data = overlayQuery.data;
    if (!data) return;
    const nextLabels: Record<string, string> = {};
    const nextHidden: Record<string, boolean> = {};
    const nextGrains: Record<string, string[]> = {};
    const patches = data.overlay.metrics || {};
    for (const m of data.base_metrics) {
      const patch = patches[m.key] || patches[m.id] || {};
      nextLabels[m.key] = typeof patch.label === 'string' && patch.label.trim() ? patch.label : m.label;
      nextHidden[m.key] = Boolean(patch.hidden);
      const selected = Array.isArray(patch.allowed_grains) && patch.allowed_grains.length
        ? patch.allowed_grains.map(grainToken)
        : m.allowed_grains.map(grainToken);
      nextGrains[m.key] = selected;
    }
    setLabels(nextLabels);
    setHidden(nextHidden);
    setGrainTokens(nextGrains);
    setComposed(composedFromOverlay(data.overlay.composed as Record<string, unknown> | undefined));
  }, [overlayQuery.data]);

  const handlerBacked = useMemo(
    () => baseMetrics.filter((m) => m.handler_backed && m.fact_family),
    [baseMetrics]
  );

  const mutation = useMutation({
    mutationFn: () => {
      const metrics: Record<string, OverlayPatch> = {};
      for (const m of baseMetrics) {
        const patch: OverlayPatch = {};
        const label = (labels[m.key] || '').trim();
        if (label && label !== m.label) patch.label = label;
        if (hidden[m.key]) patch.hidden = true;
        const selected = (grainTokens[m.key] || []).map(parseGrainToken).filter((g) => g.length);
        if (selected.length && !sameSets(selected, m.allowed_grains)) {
          patch.allowed_grains = selected;
        }
        if (Object.keys(patch).length) metrics[m.key] = patch;
      }
      const composedPayload: Record<string, unknown> = {};
      for (const row of composed) {
        const key = row.key.trim().toLowerCase();
        if (!key || !row.label.trim()) continue;
        const inputs = row.op === 'alias' ? row.inputs.slice(0, 1) : row.inputs.slice(0, 2);
        composedPayload[key] = {
          key,
          label: row.label.trim(),
          compose: { op: row.op, inputs, grain: row.grain },
        };
      }
      return apiPut<OverlayEditorPayload>('/api/v1/semantics/overlay', {
        metrics,
        composed: composedPayload,
      });
    },
    onSuccess: async (data) => {
      setSaveError(null);
      setSaveOk('Saved. Catalog and queries now use this overlay.');
      qc.setQueryData(OVERLAY_QUERY_KEY, data);
      await qc.invalidateQueries({ queryKey: CATALOG_QUERY_KEY });
      await qc.invalidateQueries({ queryKey: ['semantics-catalog'] });
      await qc.invalidateQueries({ queryKey: ['auth', 'tenant-commercial-profile'] });
    },
    onError: (err) => {
      setSaveOk(null);
      setSaveError(safeDisplayError(err));
    },
  });

  function addComposed() {
    const first = handlerBacked[0];
    const second = handlerBacked.find((m) => m.fact_family === first?.fact_family && m.key !== first?.key);
    const grain = first?.allowed_grains[0] || ['period'];
    setComposed((rows) => [
      ...rows,
      {
        key: `custom_metric_${rows.length + 1}`,
        label: 'Custom metric',
        op: 'ratio',
        inputs: [first?.key || '', second?.key || first?.key || ''].filter(Boolean),
        grain,
      },
    ]);
  }

  function updateComposed(index: number, patch: Partial<ComposedDraft>) {
    setComposed((rows) => rows.map((row, i) => (i === index ? { ...row, ...patch } : row)));
  }

  if (overlayQuery.isError) {
    return (
      <Alert severity="error" data-testid="semantic-overlay-load-error">
        {safeDisplayError(overlayQuery.error)}
      </Alert>
    );
  }

  return (
    <Stack spacing={2} data-testid="semantic-overlay-panel">
      <Typography variant="subtitle1" fontWeight={600} data-testid="semantic-overlay-heading">
        Semantic catalog (metrics)
      </Typography>
      <Typography variant="body2" color="text.secondary">
        Relabel, hide, or narrow grains for this tenant without a deploy. Formulas stay locked.
        New metrics may only be a ratio or alias of same-family handler-backed metrics.
      </Typography>
      {saveError ? (
        <Alert severity="error" data-testid="semantic-overlay-save-error">
          {saveError}
        </Alert>
      ) : null}
      {saveOk ? (
        <Alert severity="success" data-testid="semantic-overlay-save-ok">
          {saveOk}
        </Alert>
      ) : null}

      <Typography variant="subtitle2">Platform metrics</Typography>
      <Stack spacing={2}>
        {baseMetrics.map((m) => (
          <Box key={m.key} data-testid={`semantic-overlay-metric-${m.key}`}>
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} alignItems={{ md: 'center' }}>
              <TextField
                label={`${m.key} label`}
                size="small"
                value={labels[m.key] || ''}
                onChange={(e) => setLabels((prev) => ({ ...prev, [m.key]: e.target.value }))}
                inputProps={{ 'data-testid': `semantic-overlay-label-${m.key}` }}
                sx={{ minWidth: 220, flex: 1 }}
              />
              <FormControlLabel
                control={
                  <Switch
                    checked={Boolean(hidden[m.key])}
                    onChange={(e) => setHidden((prev) => ({ ...prev, [m.key]: e.target.checked }))}
                    slotProps={{
                      input: {
                        'data-testid': `semantic-overlay-hide-${m.key}`,
                      } as React.InputHTMLAttributes<HTMLInputElement>,
                    }}
                  />
                }
                label="Hide"
              />
              <FormControl size="small" sx={{ minWidth: 220 }}>
                <InputLabel id={`semantic-overlay-grains-${m.key}-label`}>Allowed grains</InputLabel>
                <Select
                  labelId={`semantic-overlay-grains-${m.key}-label`}
                  multiple
                  label="Allowed grains"
                  value={grainTokens[m.key] || []}
                  onChange={(e) => {
                    const value = e.target.value;
                    setGrainTokens((prev) => ({
                      ...prev,
                      [m.key]: typeof value === 'string' ? value.split(',') : value,
                    }));
                  }}
                  renderValue={(selected) => selected.map((t) => `{${t}}`).join('; ')}
                  inputProps={{ 'data-testid': `semantic-overlay-grains-${m.key}` }}
                >
                  {m.allowed_grains.map((set) => {
                    const token = grainToken(set);
                    return (
                      <MenuItem key={token} value={token}>
                        <Checkbox checked={(grainTokens[m.key] || []).includes(token)} />
                        {`{${token}}`}
                      </MenuItem>
                    );
                  })}
                </Select>
              </FormControl>
            </Stack>
            <Typography variant="caption" color="text.disabled" data-testid={`semantic-overlay-locked-${m.key}`}>
              Locked formula · {m.locked.owner_surface}
            </Typography>
          </Box>
        ))}
      </Stack>

      <Divider />
      <Stack direction="row" spacing={1} alignItems="center">
        <Typography variant="subtitle2">Composed metrics</Typography>
        <Button size="small" onClick={addComposed} data-testid="semantic-overlay-add-composed">
          Add ratio or alias
        </Button>
      </Stack>
      {composed.map((row, index) => {
        const first = byKey.get(row.inputs[0] || '');
        const family = first?.fact_family;
        const inputOptions =
          row.op === 'alias'
            ? handlerBacked
            : handlerBacked.filter((m) => !family || m.fact_family === family);
        const inputMetrics = row.inputs.map((k) => byKey.get(k)).filter(Boolean) as BaseMetric[];
        const grainChoices = intersectGrainSets(inputMetrics.map((m) => m.allowed_grains));
        return (
          <Stack
            key={`${row.key}-${index}`}
            spacing={1}
            data-testid={`semantic-overlay-composed-${index}`}
            sx={{ pl: 1, borderLeft: 2, borderColor: 'divider' }}
          >
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={1}>
              <TextField
                size="small"
                label="Key"
                value={row.key}
                onChange={(e) => updateComposed(index, { key: e.target.value })}
                inputProps={{ 'data-testid': `semantic-overlay-composed-key-${index}` }}
              />
              <TextField
                size="small"
                label="Label"
                value={row.label}
                onChange={(e) => updateComposed(index, { label: e.target.value })}
                inputProps={{ 'data-testid': `semantic-overlay-composed-label-${index}` }}
              />
              <FormControl size="small" sx={{ minWidth: 140 }}>
                <InputLabel id={`semantic-overlay-op-${index}-label`}>Op</InputLabel>
                <Select
                  labelId={`semantic-overlay-op-${index}-label`}
                  label="Op"
                  value={row.op}
                  onChange={(e) => {
                    const op = e.target.value as 'ratio' | 'alias';
                    updateComposed(index, {
                      op,
                      inputs: op === 'alias' ? row.inputs.slice(0, 1) : row.inputs,
                    });
                  }}
                  inputProps={{ 'data-testid': `semantic-overlay-composed-op-${index}` }}
                >
                  <MenuItem value="ratio">ratio</MenuItem>
                  <MenuItem value="alias">alias</MenuItem>
                </Select>
              </FormControl>
            </Stack>
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={1}>
              {(row.op === 'alias' ? [0] : [0, 1]).map((slot) => (
                <FormControl key={slot} size="small" sx={{ minWidth: 200 }}>
                  <InputLabel id={`semantic-overlay-input-${index}-${slot}-label`}>
                    {row.op === 'ratio' ? (slot === 0 ? 'Numerator' : 'Denominator') : 'Alias of'}
                  </InputLabel>
                  <Select
                    labelId={`semantic-overlay-input-${index}-${slot}-label`}
                    label={row.op === 'ratio' ? (slot === 0 ? 'Numerator' : 'Denominator') : 'Alias of'}
                    value={row.inputs[slot] || ''}
                    onChange={(e) => {
                      const next = [...row.inputs];
                      next[slot] = String(e.target.value);
                      if (slot === 0 && row.op === 'ratio') {
                        const fam = byKey.get(String(e.target.value))?.fact_family;
                        if (fam && byKey.get(next[1] || '')?.fact_family !== fam) next[1] = '';
                      }
                      updateComposed(index, { inputs: next });
                    }}
                    inputProps={{ 'data-testid': `semantic-overlay-composed-input-${index}-${slot}` }}
                  >
                    {(slot === 0 ? handlerBacked : inputOptions).map((m) => (
                      <MenuItem key={m.key} value={m.key}>
                        {m.label}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              ))}
              <FormControl size="small" sx={{ minWidth: 180 }}>
                <InputLabel id={`semantic-overlay-composed-grain-${index}-label`}>Grain</InputLabel>
                <Select
                  labelId={`semantic-overlay-composed-grain-${index}-label`}
                  label="Grain"
                  value={grainToken(row.grain)}
                  onChange={(e) => updateComposed(index, { grain: parseGrainToken(String(e.target.value)) })}
                  inputProps={{ 'data-testid': `semantic-overlay-composed-grain-${index}` }}
                >
                  {grainChoices.map((set) => {
                    const token = grainToken(set);
                    return (
                      <MenuItem key={token} value={token}>
                        {`{${token}}`}
                      </MenuItem>
                    );
                  })}
                </Select>
              </FormControl>
              <Button color="inherit" onClick={() => setComposed((rows) => rows.filter((_, i) => i !== index))}>
                Remove
              </Button>
            </Stack>
          </Stack>
        );
      })}

      <Box>
        <Button
          variant="contained"
          disabled={mutation.isPending || overlayQuery.isPending}
          onClick={() => {
            setSaveOk(null);
            setSaveError(null);
            mutation.mutate();
          }}
          data-testid="semantic-overlay-save"
        >
          {mutation.isPending ? 'Saving…' : 'Save metric overlay'}
        </Button>
      </Box>
    </Stack>
  );
}

