  // Page size shares LS_GRID with the column layout; both sides merge into the stored object.
  useEffect(() => {
    try {
      const raw = localStorage.getItem(LS_GRID);
      if (raw) {
        const p = JSON.parse(raw) as { pageSize?: number };
        if (typeof p.pageSize === 'number' && PAGE_SIZE_OPTIONS.includes(p.pageSize as (typeof PAGE_SIZE_OPTIONS)[number])) {
          setLimit(p.pageSize);
        }
      }
    } catch {
      /* ignore */
    }
    setPersistReady(true);
  }, []);

  useEffect(() => {
    if (!persistReady) return;
    try {
      const raw = localStorage.getItem(LS_GRID);
      const prev = raw ? (JSON.parse(raw) as Record<string, unknown>) : {};
      localStorage.setItem(LS_GRID, JSON.stringify({ ...prev, pageSize: limit }));
    } catch {
      /* ignore */
    }
  }, [limit, persistReady]);

  const clearSmartPreset = useCallback(() => {
    setSmartPreset(null);
    setDeliveryLens(null);
    setCohort('');
    setLineState('');
    setCargoStatus('');
    setDateField('eta_date');
    setDateFrom('');
    setDateTo('');
    setPodDateFilter('');
    resetPagination();
  }, [resetPagination]);

  const applyDeliveryLens = useCallback(
    (id: DeliveryLensId) => {
      setSmartPreset(null);
      setDeliveryLens(id);
      setCohort('');
      resetPagination();
      setDateField('eta_date');
      setDateFrom('');
      setDateTo('');
      setLineState('');
      if (id === 'delivered') {
        setCargoStatus('received');
        setPodDateFilter('false');
      } else {
        setCargoStatus('scheduled');
        setPodDateFilter('true');
      }
      gridSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    },
    [resetPagination]
  );

  const toggleDeliveryLens = (id: DeliveryLensId) => {
    if (deliveryLens === id) {
      clearSmartPreset();
      return;
    }
    applyDeliveryLens(id);
  };

  const applySmartPreset = useCallback(
    (id: SmartPresetId) => {
      const today = new Date();
      const w0 = startOfISOWeek(today);
      const w6 = addDaysCal(w0, 6);
      const yest = addDaysCal(today, -1);
      const staleCut = addDaysCal(today, -180);
      setSmartPreset(id);
      setDeliveryLens(null);
      resetPagination();
      switch (id) {
        case 'arriving_week':
          setCohort('arriving_week');
          setDateField('eta_date');
          setDateFrom(localDateYMD(w0));
          setDateTo(localDateYMD(w6));
          setCargoStatus('scheduled');
          setLineState('');
          setPodDateFilter('true');
          break;
        case 'overdue':
          setCohort('overdue');
          setDateField('promise_date');
          setDateFrom(localDateYMD(staleCut));
          setDateTo(localDateYMD(yest));
          setCargoStatus('scheduled');
          setLineState('');
          setPodDateFilter('true');
          break;
        case 'landed_week':
          setCohort('landed_week');
          setDateField('pod_date');
          setDateFrom(localDateYMD(w0));
          setDateTo(localDateYMD(w6));
          setCargoStatus('received');
          setLineState('');
          setPodDateFilter('false');
          break;
        case 'outstanding':
          setCohort('');
          setLineState('open_order');
          setDateField('eta_date');
          setDateFrom('');
          setDateTo('');
          setCargoStatus('');
          setPodDateFilter('');
          break;
        default:
          break;
      }
      gridSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    },
    [resetPagination]
  );

  const filterScheduledPipeline = useCallback(() => {
    const today = new Date();
    const horizon = addDaysCal(today, 90);
    setSmartPreset(null);
    setDeliveryLens(null);
    setCohort('current_incoming');
    setCargoStatus('scheduled');
    setLineState('');
    setPodDateFilter('true');
    setDateField('effective_arrival_date');
    setDateFrom(localDateYMD(today));
    setDateTo(localDateYMD(horizon));
    resetPagination();
    gridSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, [resetPagination]);

  const toggleSmartPreset = (id: SmartPresetId) => {
    if (smartPreset === id) {
      clearSmartPreset();
      return;
    }
    applySmartPreset(id);
  };

  const { data: summary } = useQuery({
    queryKey: ['shipping-summary'],
    queryFn: ({ signal }) => apiGet<ShippingSummary>('/api/v1/shipping/summary', { signal }),
  });

  const { data: filterOptions } = useQuery({
    queryKey: ['shipping-filter-options'],
    queryFn: ({ signal }) =>
      apiGet<{ distributors: DistHit[]; customers: CustHit[] }>('/api/v1/shipping/filter-options', { signal }),
  });

  const { data: planPeriods } = useQuery({
    queryKey: ['shipping-lineup-plan-periods'],
    queryFn: ({ signal }) =>
      apiGet<{ items: PlanPeriod[] }>('/api/v1/shipping/lineup-plan-periods', { signal }),
  });

  const distOptions = filterOptions?.distributors ?? [];
  const custOptions = filterOptions?.customers ?? [];

  const includeRawRow = displayOptionalFields.includes('raw_source_row');

  // Deep-link: ?purchase_order_id=&po_label= or PvE ?plan_quarter=&customer_id=&plan_business_unit=
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const sp = new URLSearchParams(window.location.search);
    const poId = sp.get('purchase_order_id');
    if (poId && /^\d+$/.test(poId)) {
      setPurchaseOrderId(Number(poId));
      setPoFilterLabel(sp.get('po_label'));
    }
    const pq = sp.get('plan_quarter');
    if (pq) setPlanQuarter(pq);
    const pbu = sp.get('plan_business_unit');
    if (pbu) setPlanBusinessUnit(pbu);
    const cid = sp.get('customer_id');
    if (cid && /^\d+$/.test(cid)) {
      const id = Number(cid);
      const hit = custOptions.find((c) => c.id === id);
      if (hit) setCustomerPick(hit);
    }
  }, [custOptions]);

  const filterParams = useMemo<ShippingFilterParams>(
    () => ({
      lineState,
      cargoStatus,
      distributorId: distributorPick?.id ?? null,
      customerId: customerPick?.id ?? null,
      purchaseOrderId,
      search,
      dateField,
      dateFrom,
      dateTo,
      productFamily,
      productModel,
      currencyCode,
      operatingUnit,
      podDateFilter,
      planQuarter,
      planBusinessUnit,
      lineupAttribution,
      lifecycleBucket,
      slipDirection,
      cohort,
    }),
    [
      lineState,
      cargoStatus,
      distributorPick?.id,
      customerPick?.id,
      purchaseOrderId,
      search,
      dateField,
      dateFrom,
      dateTo,
      productFamily,
      productModel,
      currencyCode,
      operatingUnit,
      podDateFilter,
      planQuarter,
      planBusinessUnit,
      lineupAttribution,
      lifecycleBucket,
      slipDirection,
      cohort,
    ]
  );

  const listUrl = useMemo(
    () => buildShippingLinesUrl({ ...filterParams, skip, limit, includeRawRow }),
    [filterParams, skip, limit, includeRawRow]
  );

  const { data: lines, isLoading: linesLoading, isError: linesIsError, error: linesError, refetch } = useQuery({
    queryKey: ['shipping-lines', listUrl],
    queryFn: ({ signal }) => apiGet<LinesResponse>(listUrl, { signal }),
  });

  const baseColDefs: ColDef<ShippingLine>[] = useMemo(
    () => [
      { field: 'id', headerName: 'ID', width: 88, pinned: 'left' },
      {
        colId: 'receipt',
        headerName: 'Receipt',
        width: 110,
        sortable: false,
        filter: false,
        cellRenderer: (p: { data?: ShippingLine }) =>
          p.data?.id != null ? (
            <Link href={`/supply/shipments/${p.data.id}`} data-testid={`shipment-receipt-link-${p.data.id}`}>
              Open
            </Link>
          ) : null,
      },
      {
        headerName: 'Distributor',
        minWidth: 160,
        tooltipValueGetter: (p) => {
          const code = p.data?.distributor_code;
          const label = p.data?.distributor_display ?? p.data?.distributor_name;
          if (code && label && code !== label) return `${label} (${code})`;
          return (label ?? code ?? undefined) as string | undefined;
        },
        valueGetter: (p) => shippingDistributorCellValue(p.data),
        // Client filter matches display + code (valueGetter includes secondary TMP line).
        filter: true,
        sortable: true,
      },
      {
        headerName: 'Channel partner',
        minWidth: 160,
        valueGetter: (p) => (p.data?.channel_partner_label ?? '—') as string,
      },
      {
        headerName: 'Product (sales model)',
        minWidth: 180,
        valueGetter: (p) =>
          (p.data?.sales_model_name ?? p.data?.product_name ?? p.data?.item_code ?? '—') as string,
      },
      { field: 'line_state', headerName: 'Line state', minWidth: 120 },
      { field: 'status', headerName: 'Cargo status', minWidth: 120 },
      {
        field: 'plan_quarter_label',
        headerName: 'Plan quarter',
        minWidth: 108,
        valueFormatter: (p: ValueFormatterParams<ShippingLine>) =>
          (p.data?.plan_quarter_label ?? p.data?.plan_quarter ?? '—') as string,
      },
      {
        field: 'landing_quarter',
        headerName: 'Landing quarter',
        minWidth: 118,
        valueFormatter: (p: ValueFormatterParams<ShippingLine>) => (p.value ? String(p.value) : '—'),
        cellStyle: NUMERIC_CELL_STYLE,
      },
      {
        field: 'slipped',
        headerName: 'Slip',
        width: 72,
        valueFormatter: (p: ValueFormatterParams<ShippingLine>) => (p.value ? 'Yes' : '—'),
        cellStyle: NUMERIC_CELL_STYLE,
      },
      {
        field: 'awaiting_pod_days',
        headerName: 'Awaiting POD (days)',
        minWidth: 140,
        valueFormatter: (p: ValueFormatterParams<ShippingLine>) =>
          p.value != null ? String(p.value) : '—',
        cellStyle: NUMERIC_CELL_STYLE,
      },
      { field: 'eta_date', headerName: 'ETA', minWidth: 118, valueFormatter: dateColFormatter },
      { field: 'promise_date', headerName: 'Promise', minWidth: 118, valueFormatter: dateColFormatter },
      { field: 'pod_date', headerName: 'POD', minWidth: 118, valueFormatter: dateColFormatter },
      {
        field: 'customer_po',
        headerName: 'Customer PO',
        minWidth: 140,
        valueFormatter: (p: ValueFormatterParams<ShippingLine>) => (p.value ? String(p.value) : '—'),
        onCellClicked: (p) => {
          const poId = p.data?.purchase_order_id;
          if (poId == null) return;
          setPurchaseOrderId(Number(poId));
          setPoFilterLabel(p.data?.customer_po ?? null);
          resetPagination();
        },
        cellStyle: (p) =>
          p.data?.purchase_order_id != null
            ? { cursor: 'pointer', color: theme.palette.primary.main, textDecoration: 'underline' }
            : undefined,
      },
      { field: 'quantity', headerName: 'Qty', width: 90 },
      { field: 'amount', headerName: 'Amount', width: 100 },
      { field: 'currency_code', headerName: 'CCY', width: 72 },
    ],
    [resetPagination, theme]
  );

  const optionalColDefs = factColumns.optionalColDefs;

  const colDefs = useMemo(() => [...baseColDefs, ...optionalColDefs], [baseColDefs, optionalColDefs]);

  const gridOptions = useMemo(
    () => ({
      getRowId: (p: { data: ShippingLine }) => String(p.data.id),
      defaultColDef: { sortable: true, filter: true, resizable: true },
      ...gridRowMetrics('comfortable'),
    }),
    []
  );

  const total = lines?.total ?? 0;
  const page = limit > 0 ? Math.floor(skip / limit) : 0;
  const pageCount = Math.max(0, Math.ceil(total / limit) - 1);

  return (
    <>
      <Alert severity="info" sx={{ mb: 2 }}>
        Shipment rows appear after an inbound import is applied.
        Raw files are reviewed under <strong>Receipts & POD</strong>.
      </Alert>
      {purchaseOrderId != null && (
        <Alert
          severity="info"
          sx={{ mb: 2 }}
          action={
            <Chip
              label="Clear PO filter"
              size="small"
              onClick={() => {
                setPurchaseOrderId(null);
                setPoFilterLabel(null);
                resetPagination();
              }}
              data-testid="clear-po-filter"
            />
          }
          data-testid="po-filter-banner"
        >
          Filtered to purchase order{poFilterLabel ? ` ${poFilterLabel}` : ` #${purchaseOrderId}`} — showing only
          shipment lines under this PO.
        </Alert>
      )}
      <ShippingCommercialSummary
        filterParams={filterParams}
        onApplySmartPreset={applySmartPreset}
        onFilterScheduledPipeline={filterScheduledPipeline}
      />

      {planQuarter && lineupAttribution !== 'unattributed' ? (
        <ShippingLineupQuarterSummary
          planQuarter={planQuarter}
          customerId={customerPick?.id ?? null}
          planBusinessUnit={planBusinessUnit}
        />
      ) : null}

      <Box sx={{ mb: 2 }}>
        <ScopeBar
          chips={[
            {
              key: 'unattributed',
              label: 'Unattributed',
              active: lineupAttribution === 'unattributed',
              tone: 'warning',
              onToggle: () => {
                setLineupAttribution((prev) => (prev === 'unattributed' ? '' : 'unattributed'));
                setPlanQuarter('');
                resetPagination();
              },
            },
            ...(['shipped', 'pipeline', 'landed'] as const).map((b) => ({
              key: b,
              label: b === 'pipeline' ? 'Pipeline' : b.charAt(0).toUpperCase() + b.slice(1),
              active: lifecycleBucket === b,
              onToggle: () => {
                setLifecycleBucket((prev) => (prev === b ? '' : b));
                resetPagination();
              },
            })),
            {
              key: 'slipped_in',
              label: 'Slipped in',
              active: slipDirection === 'slipped_in',
              disabled: !planQuarter,
              onToggle: () => {
                setSlipDirection((prev) => (prev === 'slipped_in' ? '' : 'slipped_in'));
                resetPagination();
              },
            },
            {
              key: 'slipped_out',
              label: 'Slipped out',
              active: slipDirection === 'slipped_out',
              disabled: !planQuarter,
              onToggle: () => {
                setSlipDirection((prev) => (prev === 'slipped_out' ? '' : 'slipped_out'));
                resetPagination();
              },
            },
            {
              key: 'arriving_week',
              label: 'Arriving this week',
              active: smartPreset === 'arriving_week',
              onToggle: () => toggleSmartPreset('arriving_week'),
            },
            {
              key: 'overdue',
              label: 'Overdue (promise passed, not landed)',
              active: smartPreset === 'overdue',
              onToggle: () => toggleSmartPreset('overdue'),
            },
            {
              key: 'landed_week',
              label: 'Delivered this week',
              active: smartPreset === 'landed_week',
              onToggle: () => toggleSmartPreset('landed_week'),
            },
            {
              key: 'delivered',
              label: 'Delivered (all)',
              active: deliveryLens === 'delivered',
              tone: 'success' as const,
              onToggle: () => toggleDeliveryLens('delivered'),
            },
            {
              key: 'in_transit',
              label: 'In transit',
              active: deliveryLens === 'in_transit',
              onToggle: () => toggleDeliveryLens('in_transit'),
            },
            {
              key: 'outstanding',
              label: 'Outstanding orders',
              active: smartPreset === 'outstanding',
              onToggle: () => toggleSmartPreset('outstanding'),
            },
          ]}
          clearAvailable={Boolean(smartPreset || deliveryLens || cohort)}
          onClear={clearSmartPreset}
          filters={
            <>
              <FormControl size="small" sx={{ minWidth: 160 }}>
                <InputLabel id="flt-plan-quarter">Plan quarter</InputLabel>
                <Select
                  labelId="flt-plan-quarter"
                  label="Plan quarter"
                  value={planQuarter}
                  onChange={(e) => {
                    setPlanQuarter(String(e.target.value));
                    setLineupAttribution('');
                    resetPagination();
                  }}
                >
                  <MenuItem value="">(any)</MenuItem>
                  {(planPeriods?.items ?? []).map((p) => (
                    <MenuItem key={p.label} value={p.label}>
                      {p.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <TextField
                size="small"
                label="Plan BU"
                placeholder="e.g. NB"
                value={planBusinessUnit}
                onChange={(e) => {
                  setPlanBusinessUnit(e.target.value);
                  resetPagination();
                }}
                sx={{ width: 100 }}
              />
              <TextField
                size="small"
                label="Search"
                placeholder="Distributor, product, SKU, sales model, order #, channel partner…"
                value={search}
                onChange={(e) => {
                  setSearch(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  setCohort('');
                  resetPagination();
                }}
                sx={{ minWidth: 240, flex: 1 }}
                data-testid="shipping-search"
              />
              <Autocomplete
                sx={{ minWidth: 240, flex: 1 }}
                size="small"
                loading={!filterOptions}
                options={distOptions}
                value={distributorPick}
                onChange={(_e, v) => {
                  setDistributorPick(v);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  setCohort('');
                  resetPagination();
                }}
                getOptionLabel={(o) => `${o.distributor_name} (${o.distributor_code})`}
                isOptionEqualToValue={(a, b) => a.id === b.id}
                renderInput={(params) => (
                  <TextField {...params} label="Distributor" placeholder="All distributors · type to filter" />
                )}
              />
              <Autocomplete
                sx={{ minWidth: 220, flex: 1 }}
                size="small"
                loading={!filterOptions}
                options={custOptions}
                value={customerPick}
                onChange={(_e, v) => {
                  setCustomerPick(v);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  setCohort('');
                  resetPagination();
                }}
                getOptionLabel={(o) => `${o.customer_name} (${o.customer_code})`}
                isOptionEqualToValue={(a, b) => a.id === b.id}
                renderInput={(params) => (
                  <TextField {...params} label="Channel partner (customer)" placeholder="All customers · type to filter" />
                )}
              />
              <FormControl size="small" sx={{ minWidth: 140 }}>
                <InputLabel id="flt-line-state">Line state</InputLabel>
                <Select
                  labelId="flt-line-state"
                  label="Line state"
                  value={lineState}
                  onChange={(e) => {
                    setLineState(String(e.target.value));
                    setSmartPreset(null);
                    setDeliveryLens(null);
                    setCohort('');
                    resetPagination();
                  }}
                >
                  <MenuItem value="">(any)</MenuItem>
                  {(summary?.by_line_state ?? []).map((b) => (
                    <MenuItem key={b.key} value={b.key}>
                      {b.key}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl size="small" sx={{ minWidth: 140 }}>
                <InputLabel id="flt-cargo">Cargo status</InputLabel>
                <Select
                  labelId="flt-cargo"
                  label="Cargo status"
                  value={cargoStatus}
                  onChange={(e) => {
                    setCargoStatus(String(e.target.value));
                    setSmartPreset(null);
                    setDeliveryLens(null);
                    setCohort('');
                    resetPagination();
                  }}
                >
                  <MenuItem value="">(any)</MenuItem>
                  {(summary?.by_status ?? []).map((b) => (
                    <MenuItem key={b.key} value={b.key}>
                      {cargoStatusLabel(b.key)}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl size="small" sx={{ minWidth: 180 }}>
                <InputLabel id="flt-date-field">Date field</InputLabel>
                <Select
                  labelId="flt-date-field"
                  label="Date field"
                  value={dateField}
                  onChange={(e) => {
                    setDateField(String(e.target.value));
                    setSmartPreset(null);
                    setDeliveryLens(null);
                    setCohort('');
                    resetPagination();
                  }}
                >
                  {DATE_FIELD_OPTIONS.map((o) => (
                    <MenuItem key={o.value} value={o.value}>
                      {o.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <TextField
                size="small"
                label="Date from"
                type="date"
                InputLabelProps={{ shrink: true }}
                value={dateFrom}
                onChange={(e) => {
                  setDateFrom(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  resetPagination();
                }}
                sx={{ width: 160 }}
              />
              <TextField
                size="small"
                label="Date to"
                type="date"
                InputLabelProps={{ shrink: true }}
                value={dateTo}
                onChange={(e) => {
                  setDateTo(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  resetPagination();
                }}
                sx={{ width: 160 }}
              />
              <TextField
                size="small"
                label="Product family"
                placeholder="Category / line / series"
                value={productFamily}
                onChange={(e) => {
                  setProductFamily(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  resetPagination();
                }}
                sx={{ minWidth: 160 }}
              />
              <TextField
                size="small"
                label="Product model"
                placeholder="Model, marketing name, SKU…"
                value={productModel}
                onChange={(e) => {
                  setProductModel(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  resetPagination();
                }}
                sx={{ minWidth: 160 }}
              />
              <TextField
                size="small"
                label="Currency"
                placeholder="e.g. USD"
                value={currencyCode}
                onChange={(e) => {
                  setCurrencyCode(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  resetPagination();
                }}
                sx={{ width: 100 }}
              />
              <TextField
                size="small"
                label="Operating unit"
                value={operatingUnit}
                onChange={(e) => {
                  setOperatingUnit(e.target.value);
                  setSmartPreset(null);
                  setDeliveryLens(null);
                  resetPagination();
                }}
                sx={{ minWidth: 140 }}
              />
            </>
          }
          trailing={
            <Button
              size="small"
              variant="outlined"
              startIcon={<ViewColumnIcon />}
              onClick={factColumns.openPicker}
              aria-haspopup="dialog"
              data-testid="shipping-additional-columns"
            >
              Additional columns
            </Button>
          }
        />
      </Box>

      <Paper ref={gridSectionRef} variant="outlined" sx={{ p: 1.5, mb: 2 }}>
        <TablePagination
          component="div"
          count={total}
          page={total === 0 ? 0 : Math.min(page, pageCount)}
          onPageChange={(_, nextPage) => {
            setSkip(nextPage * limit);
          }}
          rowsPerPage={limit}
          onRowsPerPageChange={(e) => {
            const next = Number(e.target.value);
            setLimit(next);
            setSkip(0);
          }}
          rowsPerPageOptions={[...PAGE_SIZE_OPTIONS]}
          labelDisplayedRows={({ from, to, count }) => `${from}–${to} of ${count !== -1 ? count : `more than ${to}`}`}
          sx={{ borderBottom: 1, borderColor: 'divider', mb: 1 }}
        />

        <ModuleDataSection
          intro="Sort and filter in the grid. Pagination applies to the server query — change filters to narrow the full result set."
          introWhen="always"
          isLoading={linesLoading}
          isError={linesIsError}
          error={toQueryError(linesError)}
          onRetry={() => void refetch()}
          isEmpty={!linesLoading && (lines?.items?.length ?? 0) === 0}
          empty={{
            title: 'No shipment lines match',
            description: 'Adjust the filters, or apply an inbound shipment import.',
            primary: { label: 'Import Center', href: '/admin/imports?template=inbound_shipments' },
            secondary: { label: 'Shipment evidence', href: '/admin/shipment-evidence' },
          }}
          toolbar={
            <ModuleGridToolbar onRefresh={() => void refetch()} importsHref="/admin/imports?template=inbound_shipments" />
          }
        >
          <EnterpriseDataGrid
            rowData={lines?.items ?? []}
            columnDefs={colDefs as ColDef[]}
            gridOptions={gridOptions as GridOptions}
            height={520}
          />
        </ModuleDataSection>
      </Paper>

      <FactColumnPicker
        {...factColumns.pickerProps}
        data-testid="shipping-column-picker"
        title="Additional columns"
        description="Default columns stay shipping-focused (distributor, product model and SKU, line and cargo state, key dates). Every other shipment column can be turned on below."
        factGroupLabel="Shipment fields"
      />
    </>
  );
}

import React from 'react';

/** Minimal AG Grid React mock with api surface used by admin grid pages. */
export function createAgGridReactMock() {
  return {
    AgGridReact: (props: Record<string, unknown>) => {
      (globalThis as unknown as { __agGridLastProps?: Record<string, unknown> }).__agGridLastProps = props;
      const rowData = (props.rowData as unknown[] | undefined) ?? [];
      const gridOptions = props.gridOptions as { onGridReady?: (e: { api: unknown }) => void } | undefined;
      const api = {
        getDisplayedRowCount: () => rowData.length,
        getSelectedRows: () => [] as unknown[],
        deselectAll: () => undefined,
        exportDataAsCsv: () => undefined,
        getColumnState: () => [] as unknown[],
        applyColumnState: () => undefined,
        setColumnsVisible: () => undefined,
        getColumns: () => [] as unknown[],
        forEachNodeAfterFilterAndSort: (
          cb: (node: { data?: unknown; setSelected: (v: boolean) => void }) => void
        ) => {
          rowData.forEach((row) => cb({ data: row, setSelected: () => undefined }));
        },
      };
      React.useEffect(() => {
        gridOptions?.onGridReady?.({ api });
      }, [gridOptions, rowData.length]);
      return React.createElement('div', {
        'data-testid': 'ag-grid-mock',
        'data-has-row-selection': props.rowSelection ? 'yes' : 'no',
        'data-displayed-rows': String(rowData.length),
      });
    },
  };
}
